insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L1-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ركل لاعب كرة فارتفعت في الهواء. بإهمال مقاومة الهواء، ما القوى المؤثرة في الكرة في أثناء حركتها في الهواء؟', null, null, '["قوة الركلة وحدها","قوة الجاذبية الأرضية وقوة الركلة","قوة الجاذبية الأرضية وحدها","لا تؤثر فيها أيّ قوة"]'::jsonb, 'فهم', 'تحديد القوى', 'سهل', 'الكتاب ص 161–162 — القوى المؤثرة في المقذوف بعد إطلاقه'),
('mcq', 2, 'أيّ قوة تجعل المقذوف يتحرك في مسار منحنٍ بدلًا من أن يتحرك في خط مستقيم؟', null, null, '["قوة الجاذبية الأرضية","قوة الإطلاق من القاذف","القوة العمودية من الأرض","قوة الشد في الهواء"]'::jsonb, 'فهم', 'ربط السبب بالنتيجة', 'سهل', 'الكتاب ص 161 — «وهذه القوة هي التي تجعله يتحرك في مسار منحنٍ»'),
('mcq', 3, 'يقول طالب: «بعد أن يرمي اللاعب الكرة تبقى قوة الرمية مؤثرة فيها وتدفعها إلى الأمام حتى تسقط». بإهمال مقاومة الهواء، ما تقويم هذه العبارة؟', null, null, '["صحيحة؛ لأن الكرة تستمر في الحركة إلى الأمام حتى تسقط","صحيحة؛ لأن قوة الرمية تتناقص تدريجيًا حتى تنعدم عند الأرض","خاطئة؛ لأن الكرة لا تؤثر فيها أيّ قوة على الإطلاق بعد رميها","خاطئة؛ فقوة الرمية تؤثر في أثناء التلامس فقط، ثم تبقى الجاذبية وحدها"]'::jsonb, 'تقويم', 'تقويم عبارة', 'متوسط', 'الكتاب ص 161–162 — القوى المؤثرة في المقذوف بعد إطلاقه'),
('mcq', 4, 'يبين الشكل الآتي كرة لحظة وصولها إلى أعلى نقطة في مسارها، ومتجه سرعتها $\boldsymbol{v}$ أفقي. بإهمال مقاومة الهواء، أيّ مما يأتي يصف القوى المؤثرة في الكرة عند هذه النقطة؟', null, '[{"src":"qimg/phys1/c6l1-o02-top.svg","alt":"مسار منحنٍ متقطع لكرة قُذفت من الأرض بزاوية، يرتفع ثم ينخفض. الكرة مرسومة عند أعلى نقطة في المسار، وعندها سهم أحمر أفقي إلى اليمين مكتوب عنده v. في الزاوية مؤشر اتجاهين موجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, '["لا تؤثر فيها أيّ قوة؛ لأن سرعتها الرأسية صفر","قوة الجاذبية الأرضية إلى أسفل فقط","قوة الجاذبية الأرضية إلى أسفل وقوة أفقية إلى الأمام","قوة الجاذبية الأرضية إلى أسفل وقوة مساوية لها إلى أعلى"]'::jsonb, 'فهم', 'تحديد القوى من شكل', 'متوسط', 'الكتاب ص 161–162 — القوى المؤثرة في المقذوف بعد إطلاقه'),
('mcq', 5, 'في أثناء صعود كرة مقذوفة بزاوية، ما اتجاه القوة المحصلة المؤثرة فيها؟ (أهمل مقاومة الهواء)', null, null, '["إلى أعلى في اتجاه حركتها","مماسي للمسار في اتجاه السرعة","رأسيًا إلى أسفل","أفقي إلى الأمام"]'::jsonb, 'فهم', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 161–162 — القوى المؤثرة في المقذوف بعد إطلاقه'),
('mcq', 6, 'قذف لاعب كرة كتلتها 0.45 kg في الهواء. بإهمال مقاومة الهواء، ما مقدار القوة المحصلة المؤثرة في الكرة في أثناء طيرانها؟ ($g = 9.80\ \text{m/s}^2$)', null, null, '["0 N","0.45 N","4.4 N","0.046 N"]'::jsonb, 'تطبيق', 'حساب الوزن كقوة محصلة', 'متوسط', 'الكتاب ص 165 — $\boldsymbol{F}_g = \boldsymbol{F}_{\text{المحصلة}}$'),
('mcq', 7, 'قُذفت كرة في الهواء، ولم تُهمل مقاومة الهواء هذه المرة. أيّ مما يأتي يصف القوى المؤثرة فيها وهي صاعدة؟', null, null, '["الجاذبية الأرضية إلى أسفل، ومقاومة الهواء في عكس اتجاه حركتها","الجاذبية الأرضية إلى أسفل، ومقاومة الهواء في اتجاه حركتها","الجاذبية الأرضية إلى أسفل فقط","مقاومة الهواء في عكس اتجاه حركتها فقط"]'::jsonb, 'فهم', 'تحديد القوى مع مقاومة الهواء', 'صعب', 'الكتاب ص 161، 166 — مقاومة الهواء'),
('essay', 1, 'أطلق رامٍ سهمًا من قوسه. حدّد القوى المؤثرة في السهم في أثناء طيرانه في الهواء بإهمال مقاومة الهواء، وفسّر لماذا لا تُعدّ قوة الوتر إحدى هذه القوى.', null, null, null, 'فهم', 'تحديد القوى وتفسير', 'سهل', 'الكتاب ص 161–162 — القوى المؤثرة في المقذوف بعد إطلاقه'),
('essay', 2, 'يبين الشكل الآتي مسار كرة قُذفت بزاوية، وعليه ثلاث نقاط: $A$ في أثناء الصعود، و$B$ عند أعلى نقطة، و$C$ في أثناء النزول، والأسهم الحمراء تمثل سرعة الكرة. بإهمال مقاومة الهواء: (a) حدّد القوة المؤثرة في الكرة عند كل نقطة واتجاهها. (b) قارن بين هذه القوة عند النقاط الثلاث. (c) إذا كانت القوة كما وصفت، ففسّر لماذا يتغير اتجاه حركة الكرة على طول المسار.', null, '[{"src":"qimg/phys1/c6l1-o02-three.svg","alt":"مسار منحنٍ متقطع لكرة قُذفت من الأرض بزاوية. النقطة A على الجزء الصاعد وعندها سهم أحمر يتجه إلى أعلى وإلى اليمين. النقطة B عند أعلى نقطة وعندها سهم أحمر أفقي إلى اليمين. النقطة C على الجزء النازل وعندها سهم أحمر يتجه إلى أسفل وإلى اليمين. مؤشر الاتجاهين الموجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, null, 'تحليل', 'مقارنة القوى عند نقاط المسار', 'صعب', 'الكتاب ص 161–162 — القوى المؤثرة في المقذوف بعد إطلاقه'),
('essay', 3, 'كرة بيسبول كتلتها 0.145 kg قُذفت بزاوية في الهواء. بإهمال مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$: (a) احسب مقدار القوة المؤثرة في الكرة في أثناء صعودها، وحدّد اتجاهها. (b) ما مقدار هذه القوة عند أعلى نقطة في المسار؟ (c) استعمل القانون الثاني لنيوتن لإيجاد تسارع الكرة.', null, null, null, 'تطبيق', 'حساب ومراجعة', 'صعب', 'الكتاب ص 165 — المثال 1 ($\boldsymbol{F}_g = \boldsymbol{F}_{\text{المحصلة}}$)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
