from (values
('mcq', 1, 2, 'بعد أن تغادر الكرة قدم اللاعب، وبإهمال مقاومة الهواء، تكون القوة الوحيدة المؤثرة فيها قوة الجاذبية الأرضية المتجهة إلى أسفل.', '["قوة الركلة قوة تلامس تؤثر لحظة التلامس فقط، ولا تبقى بعد أن تغادر الكرة القدم.","قوة الركلة لا ترافق الكرة في الهواء؛ فهي تزول بزوال التلامس.","","الجاذبية الأرضية تؤثر في الكرة دائمًا، ولو لم تؤثر فيها قوة لتحركت في خط مستقيم بسرعة ثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-21T13:36:33.136Z"}'::jsonb),
('mcq', 2, 0, 'قوة الجاذبية الأرضية هي القوة الوحيدة المؤثرة في المقذوف بعد إطلاقه (بإهمال مقاومة الهواء)، وهي التي تجعله يتحرك في مسار منحنٍ على شكل قطع مكافئ.', '["","قوة الإطلاق تؤثر لحظة الإطلاق فقط ثم تزول، فلا تحني المسار في الهواء.","القوة العمودية قوة تلامس مع سطح، والمقذوف في الهواء لا يلامس سطحًا.","قوة الشد يؤثر بها حبل أو خيط متصل بالجسم، والمقذوف غير متصل بحبل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-21T13:36:33.137Z"}'::jsonb),
('mcq', 3, 3, 'قوة الرمية قوة تلامس تؤثر في الكرة ما دامت في يد اللاعب فقط. بعد ذلك تستمر الكرة في الحركة إلى الأمام بقصورها الذاتي بسرعة أفقية ثابتة، ولا تؤثر فيها إلا قوة الجاذبية الأرضية إلى أسفل.', '["استمرار الحركة إلى الأمام لا يحتاج إلى قوة؛ فالجسم يحافظ على سرعته الأفقية بقصوره الذاتي.","لا توجد قوة رمية متناقصة في الهواء؛ ولو وُجدت قوة أفقية لتغيرت السرعة الأفقية، وهي ثابتة.","الجاذبية الأرضية تؤثر في الكرة طوال حركتها في الهواء، فالقول بعدم وجود أيّ قوة خطأ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-21T13:36:33.137Z"}'::jsonb),
('mcq', 4, 1, 'تؤثر الجاذبية الأرضية في الكرة عند كل نقطة من مسارها، ومنها أعلى نقطة؛ وبإهمال مقاومة الهواء هي القوة الوحيدة، واتجاهها إلى أسفل. انعدام السرعة الرأسية لحظيًا لا يعني انعدام القوة.', '["انعدام السرعة الرأسية لحظيًا لا يعني انعدام القوة؛ فالجاذبية تؤثر دائمًا وهي التي تجعل الكرة تبدأ بالنزول.","","الحركة الأفقية لا تحتاج إلى قوة؛ فالسرعة الأفقية ثابتة لعدم وجود قوة أفقية.","لو وُجدت قوة إلى أعلى تساوي الوزن لكانت المحصلة صفرًا ولما عادت الكرة إلى الأسفل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-21T13:36:33.138Z"}'::jsonb),
('mcq', 5, 2, 'القوة الوحيدة المؤثرة في المقذوف هي وزنه، لذا فالقوة المحصلة تساوي الوزن واتجاهها رأسيًا إلى أسفل، سواء أكان المقذوف صاعدًا أم نازلًا.', '["اتجاه القوة المحصلة لا يلزم أن يكون في اتجاه الحركة؛ فالكرة الصاعدة تتباطأ رأسيًا لأن المحصلة إلى أسفل.","المحصلة لا تتجه مع السرعة؛ فالسرعة مماسية للمسار بينما الوزن رأسي دائمًا.","","لا تؤثر قوة أفقية في المقذوف، وإلا لتغيرت سرعته الأفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-21T13:36:33.138Z"}'::jsonb),
('mcq', 6, 2, 'القوة الوحيدة هي الوزن، فالمحصلة $F_g = mg = (0.45\ \text{kg})(9.80\ \text{m/s}^2) = 4.4\ \text{N}$ إلى أسفل.', '["المحصلة لا تساوي صفرًا؛ فالوزن يؤثر في الكرة دون قوة توازنه، ولذلك تتسارع إلى أسفل.","هذا مقدار الكتلة بالكيلوجرام وليس القوة؛ إذ لم يُضرب في $g$.","","قُسمت الكتلة على $g$ بدل ضربها فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-21T13:36:33.139Z"}'::jsonb),
('mcq', 7, 0, 'تؤثر الجاذبية الأرضية في الكرة إلى أسفل دائمًا، وعند عدم إهمال مقاومة الهواء تؤثر فيها أيضًا قوة معيقة تعاكس اتجاه حركتها (اتجاه سرعتها).', '["","مقاومة الهواء قوة معيقة تعاكس اتجاه الحركة ولا تكون في اتجاهها.","هذا صحيح فقط عند إهمال مقاومة الهواء، والسؤال يطلب عدم إهمالها.","الجاذبية الأرضية لا تختفي؛ فهي تؤثر في الكرة سواء أُهملت مقاومة الهواء أم لا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-21T13:36:33.139Z"}'::jsonb),
('essay', 1, null::int, null, null, 'بإهمال مقاومة الهواء تؤثر في السهم في أثناء طيرانه قوة واحدة هي قوة الجاذبية الأرضية (وزنه $\boldsymbol{F}_g$) المتجهة رأسيًا إلى أسفل. أما قوة الوتر فهي قوة تلامس تؤثر في السهم فقط في أثناء دفعه قبل أن يغادر القوس، فإذا غادره زال التلامس وزالت القوة، ويستمر السهم في الحركة بسرعته الابتدائية دون حاجة إلى قوة تدفعه.', '["القوة الوحيدة: قوة الجاذبية الأرضية (الوزن)","اتجاهها رأسيًا إلى أسفل","قوة الوتر قوة تلامس تزول بمغادرة السهم للوتر","استمرار الحركة لا يحتاج إلى قوة دافعة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد قوة الجاذبية","marks":1},{"element":"اتجاهها","marks":1},{"element":"تفسير زوال قوة الوتر","marks":1},{"element":"استمرار الحركة دون قوة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد القوة واتجاهها وتفسير كامل"},{"level":"2–3 درجات","description":"تحديد القوة مع تفسير ناقص"},{"level":"درجة واحدة","description":"ذكر الجاذبية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إضافة قوة الوتر أو «قوة الدفع» إلى القوى المؤثرة في السهم في الهواء","نسيان قوة الجاذبية الأرضية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-21T13:36:33.140Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) عند كل من $A$ و$B$ و$C$ تؤثر في الكرة قوة واحدة هي قوة الجاذبية الأرضية $\boldsymbol{F}_g$ واتجاهها رأسيًا إلى أسفل. (b) القوة متساوية عند النقاط الثلاث مقدارًا ($F_g = mg$) واتجاهًا (إلى أسفل)؛ فهي لا تعتمد على اتجاه الحركة ولا على موضع الكرة. (c) يتغير اتجاه الحركة لأن هذه القوة الرأسية تُكسب الكرة تسارعًا رأسيًا إلى أسفل يغيّر المركّبة الرأسية للسرعة باستمرار (تتناقص في الصعود حتى تنعدم عند $B$، ثم تزداد إلى أسفل في النزول)، بينما تبقى المركّبة الأفقية ثابتة لعدم وجود قوة أفقية؛ فيتغير اتجاه السرعة المحصلة ويصبح المسار منحنيًا.', '["الجاذبية الأرضية وحدها عند كل نقطة، إلى أسفل","القوة متساوية مقدارًا واتجاهًا عند النقاط الثلاث","القوة تغيّر المركّبة الرأسية للسرعة فقط","المركّبة الأفقية ثابتة فيتغير اتجاه السرعة"]'::jsonb, '[]'::jsonb, '[{"element":"الجزء a","marks":1},{"element":"الجزء b","marks":1},{"element":"تغير المركّبة الرأسية","marks":1},{"element":"ثبات المركّبة الأفقية وتغير الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الثلاثة صحيحة ومفسرة"},{"level":"2–3 درجات","description":"a وb صحيحان والتفسير ناقص"},{"level":"درجة واحدة","description":"تحديد القوة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القوة تنعدم عند أعلى نقطة","رسم القوة في اتجاه السرعة (مماسية)","القول إن القوة إلى أعلى في أثناء الصعود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-21T13:36:33.141Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) القوة الوحيدة هي الوزن: $F_g = mg = (0.145\ \text{kg})(9.80\ \text{m/s}^2) = 1.42\ \text{N}$، واتجاهها رأسيًا إلى أسفل. (b) المقدار نفسه 1.42 N إلى أسفل؛ فالوزن لا يتغير على طول المسار. (c) القوة المحصلة هي الوزن، لذا $a = \frac{F_{\text{المحصلة}}}{m} = \frac{1.42\ \text{N}}{0.145\ \text{kg}} = 9.80\ \text{m/s}^2$ رأسيًا إلى أسفل، أي إن تسارع الكرة هو $g$.', '["$F_g = 1.42\\ \\text{N}$ إلى أسفل","القوة نفسها عند أعلى نقطة","$F_{\\text{المحصلة}} = F_g$","$a = 9.80\\ \\text{m/s}^2$ إلى أسفل"]'::jsonb, '["$F_g = mg = (0.145)(9.80) = 1.42\\ \\text{N}$ إلى أسفل","عند أعلى نقطة: $F_g = 1.42\\ \\text{N}$ إلى أسفل أيضًا","$F_{\\text{المحصلة}} = F_g = 1.42\\ \\text{N}$","$a = \\frac{F_{\\text{المحصلة}}}{m} = \\frac{1.42}{0.145} = 9.80\\ \\text{m/s}^2$ إلى أسفل"]'::jsonb, '[{"element":"حساب الوزن واتجاهه","marks":1},{"element":"الوزن عند أعلى نقطة","marks":1},{"element":"تطبيق القانون الثاني","marks":1},{"element":"التسارع ومقداره واتجاهه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات صحيحة مع الوحدات والاتجاهات"},{"level":"2–3 درجات","description":"خطأ في جزء واحد أو إغفال الاتجاه"},{"level":"درجة واحدة","description":"حساب الوزن فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القوة صفر عند أعلى نقطة","استعمال الكتلة بدل الوزن","إضافة قوة أفقية إلى المحصلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-21T13:36:33.142Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C6-L1-O02') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L1-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'قذف طالب كرة بزاوية فوق الأفق، وهي الآن تتحرك صاعدة إلى أعلى وإلى اليمين. بإهمال مقاومة الهواء، أيّ مخططات الجسم الحر في الشكل الآتي يمثل الكرة في هذه اللحظة؟', null, '[{"src":"qimg/phys1/c6l1-o03-flight-fbds.svg","alt":"أربعة مخططات جسم حر مرقمة، الجسم في كل منها نقطة. (1): سهم أزرق واحد من النقطة رأسيًا إلى أسفل مكتوب عنده F_g. (2): سهم F_g رأسيًا إلى أسفل، وسهم أزرق آخر F يتجه إلى أعلى وإلى اليمين. (3): نقطة دون أيّ سهم. (4): سهم F_g رأسيًا إلى أسفل، وسهم أزرق F أفقي إلى اليمين. وعلى يمين الشكل مؤشر الاتجاهين الموجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, '["المخطط (2)","المخطط (3)","المخطط (4)","المخطط (1)"]'::jsonb, 'تطبيق', 'اختيار مخطط جسم حر', 'متوسط', 'الكتاب ص 161، 165، 167 — مخطط الجسم الحر للمقذوف'),
('mcq', 2, 'وصلت كرة مقذوفة إلى أعلى نقطة في مسارها. بإهمال مقاومة الهواء، أيّ مخططات الجسم الحر في الشكل الآتي يمثلها عند هذه النقطة؟', null, '[{"src":"qimg/phys1/c6l1-o03-top-fbds.svg","alt":"أربعة مخططات جسم حر مرقمة، الجسم في كل منها نقطة. (1): سهم أزرق F إلى أعلى وسهم أزرق F_g إلى أسفل متساويان في الطول. (2): سهم أزرق F أفقي إلى اليمين فقط. (3): سهم أزرق واحد F_g رأسيًا إلى أسفل. (4): نقطة دون أيّ سهم. وعلى يمين الشكل مؤشر الاتجاهين الموجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, '["المخطط (3)","المخطط (1)","المخطط (2)","المخطط (4)"]'::jsonb, 'تطبيق', 'اختيار مخطط جسم حر', 'متوسط', 'الكتاب ص 161، 165، 167 — مخطط الجسم الحر للمقذوف'),
('mcq', 3, 'ينزلق مكعب من الجليد على سطح طاولة أفقي أملس، ثم يغادر حافتها ويسقط. أيّ مخططات الجسم الحر في الشكل الآتي يمثل المكعب في أثناء حركته في الهواء؟', null, '[{"src":"qimg/phys1/c6l1-o03-ice-fbds.svg","alt":"أربعة مخططات جسم حر مرقمة، الجسم في كل منها نقطة. (1): سهم أزرق F_N إلى أعلى وسهم أزرق F_g إلى أسفل متساويان في الطول. (2): سهم F_g إلى أسفل وسهم أزرق F أفقي إلى اليمين. (3): سهم F_N قصير إلى أعلى وسهم F_g أطول إلى أسفل. (4): سهم أزرق واحد F_g رأسيًا إلى أسفل. وعلى يمين الشكل مؤشر الاتجاهين الموجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, '["المخطط (1)","المخطط (2)","المخطط (4)","المخطط (3)"]'::jsonb, 'تطبيق', 'اختيار مخطط جسم حر', 'سهل', 'الكتاب ص 167 — المراجعة 6 (مكعب الجليد)'),
('mcq', 4, 'كرة كتلتها 0.60 kg تتحرك في الهواء بعد قذفها. أيّ مما يأتي يصف السهم الذي يُرسم في مخطط الجسم الحر لها؟ (أهمل مقاومة الهواء، $g = 9.80\ \text{m/s}^2$)', null, null, '["سهم رأسي إلى أسفل يمثل قوة مقدارها 0.60 N","سهم رأسي إلى أعلى يمثل قوة مقدارها 5.9 N","سهم رأسي إلى أسفل يمثل قوة مقدارها 5.9 N","سهم في اتجاه السرعة يمثل قوة مقدارها 5.9 N"]'::jsonb, 'تطبيق', 'تحديد سهم القوة ومقداره', 'متوسط', 'الكتاب ص 161، 165، 167 — مخطط الجسم الحر للمقذوف'),
('mcq', 5, 'في مخطط الجسم الحر لمقذوف بإهمال مقاومة الهواء، ما العلاقة بين القوة الوحيدة المرسومة والقوة المحصلة؟', null, null, '["$\\boldsymbol{F}_{\\text{المحصلة}} = 0$","$\\boldsymbol{F}_g = \\boldsymbol{F}_{\\text{المحصلة}}$","القوة المحصلة أكبر من $\\boldsymbol{F}_g$","القوة المحصلة أفقية و$\\boldsymbol{F}_g$ رأسية"]'::jsonb, 'فهم', 'ربط المخطط بالمحصلة', 'سهل', 'الكتاب ص 165 — المثال 1 ($\boldsymbol{F}_g = \boldsymbol{F}_{\text{المحصلة}}$)'),
('mcq', 6, 'قُذف حجر أفقيًا من فوق جرف، ومع سقوطه أصبح اتجاه سرعته أقرب إلى الرأسي. كيف يتغير مخطط الجسم الحر للحجر في أثناء سقوطه؟ (أهمل مقاومة الهواء)', null, null, '["يدور سهم القوة ليبقى في اتجاه السرعة","يطول سهم الوزن كلما زادت سرعة الحجر","يُضاف سهم أفقي يمثل قوة القذف","لا يتغير؛ يبقى سهم $\\boldsymbol{F}_g$ نفسه رأسيًا إلى أسفل"]'::jsonb, 'فهم', 'ثبات المخطط على المسار', 'سهل', 'الكتاب ص 161، 165، 167 — مخطط الجسم الحر للمقذوف'),
('mcq', 7, 'قُذفت كرة بزاوية، وهي الآن تتحرك صاعدة إلى أعلى وإلى اليمين، ولم تُهمل مقاومة الهواء $\boldsymbol{F}_{\text{d}}$. أيّ مخططات الجسم الحر في الشكل الآتي يمثل الكرة في هذه اللحظة؟', null, '[{"src":"qimg/phys1/c6l1-o03-air-fbds.svg","alt":"أربعة مخططات جسم حر مرقمة، الجسم في كل منها نقطة، وفي كل منها سهم أزرق F_g رأسيًا إلى أسفل. (1): إضافة سهم F_d يتجه إلى أعلى وإلى اليمين. (2): لا يوجد إلا F_g. (3): إضافة سهم F_d أفقي إلى اليسار. (4): إضافة سهم F_d يتجه إلى أسفل وإلى اليسار. وعلى يمين الشكل مؤشر الاتجاهين الموجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, '["المخطط (2)","المخطط (4)","المخطط (1)","المخطط (3)"]'::jsonb, 'تحليل', 'اختيار مخطط مع مقاومة الهواء', 'صعب', 'الكتاب ص 166 — مقاومة الهواء'),
('essay', 1, 'ينزلق مكعب من الجليد على سطح طاولة أفقي بسرعة متجهة ثابتة دون احتكاك، ثم يغادر حافة الطاولة ساقطًا نحو الأرض. صف مخطط الجسم الحر للمكعب: (a) وهو على سطح الطاولة. (b) بعد مغادرته الحافة وهو في الهواء. ووضّح سبب الاختلاف بين المخططين.', null, null, null, 'تطبيق', 'رسم مخطط جسم حر', 'متوسط', 'الكتاب ص 167 — المراجعة 6'),
('essay', 2, 'قُذفت كرة كتلتها 0.250 kg بزاوية فوق الأفق. بإهمال مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$، و+y إلى أعلى: (a) احسب مقدار الوزن. (b) صف مخطط الجسم الحر للكرة عند ثلاث نقاط: في أثناء الصعود، وعند أعلى نقطة، وفي أثناء النزول. (c) ما الذي تستنتجه من المقارنة بين المخططات الثلاثة؟', null, null, null, 'تطبيق', 'رسم مخططات ومقارنتها', 'صعب', 'الكتاب ص 161، 165، 167 — مخطط الجسم الحر للمقذوف'),
('essay', 3, 'رسم طالب مخطط الجسم الحر الآتي لكرة قُذفت بزاوية لحظة وصولها إلى أعلى نقطة في مسارها، وكتب أن السهم $\boldsymbol{F}$ يمثل «قوة الرمية التي تحمل الكرة إلى الأمام». بإهمال مقاومة الهواء: (a) حدّد الخطأ في المخطط وفسّره. (b) صف المخطط الصحيح. (c) ما الذي يجعل الكرة تستمر في الحركة إلى الأمام إذن؟', null, '[{"src":"qimg/phys1/c6l1-o03-student-fbd.svg","alt":"مخطط جسم حر رسمه طالب: نقطة يخرج منها سهم أزرق رأسيًا إلى أسفل مكتوب عنده F_g، وسهم أزرق أفقي إلى اليمين مكتوب عنده F. في الأسفل مؤشر الاتجاهين الموجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, null, 'تحليل', 'تشخيص خطأ في رسم', 'صعب', 'الكتاب ص 161، 165، 167 — مخطط الجسم الحر للمقذوف')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
