select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'بعد إطلاق الكرة لا تؤثر فيها إلا قوة الجاذبية الأرضية، فيحتوي مخطط الجسم الحر على سهم واحد $\boldsymbol{F}_g$ يبدأ من الجسم ويتجه رأسيًا إلى أسفل، وهو المخطط (1).', '["المخطط (2) يضيف قوة $\\boldsymbol{F}$ في اتجاه الحركة، ولا توجد قوة تدفع الكرة بعد إطلاقها.","المخطط (3) لا يحتوي أيّ قوة، مع أن الجاذبية الأرضية تؤثر في الكرة دائمًا.","المخطط (4) يضيف قوة أفقية، ولا توجد قوة أفقية تؤثر في المقذوف؛ لذا تبقى سرعته الأفقية ثابتة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-21T13:36:33.143Z"}'::jsonb),
('mcq', 2, 0, 'عند أعلى نقطة تبقى الجاذبية الأرضية القوة الوحيدة المؤثرة في الكرة، فالمخطط الصحيح سهم واحد $\boldsymbol{F}_g$ إلى أسفل، وهو المخطط (3).', '["","المخطط (1) يضيف قوة إلى أعلى تساوي الوزن، فتكون المحصلة صفرًا ولا تعود الكرة إلى أسفل، وهذا خطأ.","المخطط (2) يحذف الوزن ويضيف قوة أفقية؛ والصحيح أن الوزن موجود ولا توجد قوة أفقية.","المخطط (4) بلا قوى بحجة أن السرعة الرأسية صفر، لكن الجاذبية تؤثر عند كل نقطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-21T13:36:33.143Z"}'::jsonb),
('mcq', 3, 2, 'بعد مغادرة المكعب الطاولة لم يعد يلامس سطحًا، فتزول القوة العمودية، وتبقى قوة الجاذبية الأرضية وحدها؛ فالمخطط الصحيح سهم واحد $\boldsymbol{F}_g$ إلى أسفل، وهو المخطط (4).', '["المخطط (1) يمثل المكعب وهو على سطح الطاولة (القوة العمودية تساوي الوزن)، لا وهو في الهواء.","المخطط (2) يضيف قوة أفقية تدفع المكعب، والمكعب يتحرك أفقيًا بسرعة ثابتة دون قوة.","","المخطط (3) يُبقي قوة عمودية، والقوة العمودية قوة تلامس تزول عند مغادرة السطح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.143Z"}'::jsonb),
('mcq', 4, 2, 'يُرسم سهم واحد يبدأ من الجسم رأسيًا إلى أسفل يمثل الوزن: $F_g = mg = (0.60\ \text{kg})(9.80\ \text{m/s}^2) = 5.9\ \text{N}$.', '["0.60 هو مقدار الكتلة بالكيلوجرام، ولم يُضرب في $g$ لإيجاد الوزن.","الوزن يتجه إلى أسفل نحو مركز الأرض، لا إلى أعلى.","","الوزن رأسي دائمًا ولا يتجه مع السرعة؛ فالسرعة مماسية للمسار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.144Z"}'::jsonb),
('mcq', 5, 1, 'لأن الوزن هو القوة الوحيدة في المخطط، فهو نفسه القوة المحصلة: $\boldsymbol{F}_g = \boldsymbol{F}_{\text{المحصلة}}$، واتجاهها رأسيًا إلى أسفل.', '["لو كانت المحصلة صفرًا لتحرك المقذوف بسرعة ثابتة في خط مستقيم، وهو يتسارع إلى أسفل.","","لا توجد قوة أخرى تُضاف إلى الوزن، فالمحصلة تساويه ولا تزيد عليه.","لا توجد قوة أفقية، فلا يمكن أن تكون المحصلة أفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.144Z"}'::jsonb),
('mcq', 6, 3, 'الوزن $F_g = mg$ ثابت المقدار والاتجاه، ولا يعتمد على سرعة الحجر ولا على اتجاه حركته؛ لذا يبقى مخطط الجسم الحر سهمًا واحدًا $\boldsymbol{F}_g$ رأسيًا إلى أسفل طوال السقوط.', '["القوة لا تتبع اتجاه السرعة؛ فالوزن رأسي دائمًا مهما كان اتجاه الحركة.","مقدار الوزن يعتمد على الكتلة و$g$ فقط، ولا يزداد بزيادة السرعة.","قوة القذف تؤثر لحظة الإطلاق فقط، ولا تظهر في المخطط بعده.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-21T13:36:33.144Z"}'::jsonb),
('mcq', 7, 1, 'تؤثر في الكرة قوتان: الوزن $\boldsymbol{F}_g$ رأسيًا إلى أسفل، ومقاومة الهواء $\boldsymbol{F}_{\text{d}}$ في عكس اتجاه الحركة؛ ولأن الكرة تتحرك إلى أعلى وإلى اليمين تتجه $\boldsymbol{F}_{\text{d}}$ إلى أسفل وإلى اليسار، وهذا هو المخطط (4).', '["المخطط (2) يهمل مقاومة الهواء، والسؤال يطلب أخذها في الحسبان.","","المخطط (1) يجعل مقاومة الهواء في اتجاه الحركة، وهي قوة معيقة تعاكس اتجاه الحركة.","المخطط (3) يجعل مقاومة الهواء أفقية فقط، والحركة ليست أفقية بل إلى أعلى وإلى اليمين، فالمقاومة تعاكس هذا الاتجاه كله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-21T13:36:33.145Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) على الطاولة: يُرسم المكعب نقطة، ويخرج منها سهمان: $\boldsymbol{F}_{\text{N}}$ رأسيًا إلى أعلى و$\boldsymbol{F}_g$ رأسيًا إلى أسفل، وطولاهما متساويان لأن المكعب لا يتسارع رأسيًا؛ ولا يُرسم سهم أفقي لأن السطح أملس والسرعة ثابتة. (b) في الهواء: سهم واحد $\boldsymbol{F}_g$ رأسيًا إلى أسفل بالطول نفسه. سبب الاختلاف: القوة العمودية قوة تلامس تزول عندما يغادر المكعب سطح الطاولة، فيبقى الوزن وحده قوةً محصلة تُكسبه تسارعًا إلى أسفل، مع بقاء سرعته الأفقية ثابتة.', '["(a) $\\boldsymbol{F}_{\\text{N}}$ إلى أعلى و$\\boldsymbol{F}_g$ إلى أسفل متساويان","(a) لا قوة أفقية","(b) $\\boldsymbol{F}_g$ وحده إلى أسفل","السبب: زوال القوة العمودية بانتهاء التلامس"]'::jsonb, '[]'::jsonb, '[{"element":"مخطط a","marks":1},{"element":"غياب القوة الأفقية","marks":1},{"element":"مخطط b","marks":1},{"element":"تفسير الاختلاف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المخططان صحيحان مع التفسير"},{"level":"2–3 درجات","description":"مخطط صحيح وآخر ناقص، أو بلا تفسير"},{"level":"درجة واحدة","description":"عناصر صحيحة قليلة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم قوة أفقية في اتجاه الحركة","إبقاء القوة العمودية بعد مغادرة الطاولة","رسم الأسهم متجهة نحو الجسم بدل أن تبدأ منه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.145Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $F_g = mg = (0.250\ \text{kg})(9.80\ \text{m/s}^2) = 2.45\ \text{N}$. (b) عند كل نقطة من الثلاث يُرسم الجسم نقطة يخرج منها سهم أزرق واحد $\boldsymbol{F}_g$ رأسيًا إلى أسفل (في الاتجاه السالب للمحور y) يمثل 2.45 N، وبالطول نفسه في المخططات الثلاثة؛ ولا يُرسم سهم في اتجاه الحركة ولا سهم أفقي. (c) المخططات الثلاثة متطابقة: القوة المحصلة على المقذوف ثابتة مقدارًا واتجاهًا ($\boldsymbol{F}_g = \boldsymbol{F}_{\text{المحصلة}}$) ولا تعتمد على موضعه في المسار أو اتجاه سرعته، لذا يكون تسارعه ثابتًا ($g$ إلى أسفل).', '["$F_g = 2.45\\ \\text{N}$","سهم واحد $\\boldsymbol{F}_g$ إلى أسفل عند كل نقطة","الطول نفسه في المخططات الثلاثة دون سهم أفقي أو مماسي","الاستنتاج: المحصلة ثابتة فالتسارع ثابت"]'::jsonb, '["$F_g = mg = (0.250)(9.80) = 2.45\\ \\text{N}$","عند كل نقطة: $\\boldsymbol{F}_g$ وحده، مقداره 2.45 N، في اتجاه $-y$"]'::jsonb, '[{"element":"حساب الوزن","marks":1},{"element":"وصف المخطط","marks":1},{"element":"تطابق المخططات","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحساب والمخططات والاستنتاج صحيحة"},{"level":"2–3 درجات","description":"خطأ في أحد المخططات أو استنتاج ناقص"},{"level":"درجة واحدة","description":"حساب الوزن فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم المخطط عند أعلى نقطة دون قوى","إضافة قوة في اتجاه السرعة","تغيير طول السهم من نقطة إلى أخرى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.146Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) الخطأ هو السهم $\boldsymbol{F}$؛ فقوة الرمية قوة تلامس تؤثر في الكرة ما دامت في يد اللاعب فقط، وتزول بعد إطلاقها؛ ولو وُجدت قوة أفقية لتغيرت السرعة الأفقية، وهي ثابتة. (b) المخطط الصحيح: نقطة يخرج منها سهم واحد $\boldsymbol{F}_g$ رأسيًا إلى أسفل. (c) تستمر الكرة في الحركة إلى الأمام بسرعتها الأفقية الثابتة التي اكتسبتها عند الإطلاق (القصور الذاتي)؛ فالحركة بسرعة ثابتة لا تحتاج إلى قوة.', '["الخطأ: السهم F (قوة الرمية)","التفسير: قوة تلامس تزول بعد الإطلاق، ولا قوة أفقية","المخطط الصحيح: $\\boldsymbol{F}_g$ وحده إلى أسفل","استمرار الحركة بالقصور الذاتي وثبات السرعة الأفقية"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الخطأ","marks":1},{"element":"تفسيره","marks":1},{"element":"المخطط الصحيح","marks":1},{"element":"تفسير استمرار الحركة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأ وتفسيره والمخطط الصحيح وتفسير الحركة"},{"level":"2–3 درجات","description":"تحديد الخطأ والمخطط الصحيح دون تفسير كافٍ"},{"level":"درجة واحدة","description":"تحديد الخطأ فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حذف الوزن بدل حذف قوة الرمية","القول إن الحركة إلى الأمام تتطلب قوة","القول إن الكرة عند أعلى نقطة لا تؤثر فيها قوة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.147Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
