from (values
('mcq', 1, 'ما الاسم الرياضي للمنحنى الذي يسلكه المقذوف في الهواء عند إهمال مقاومة الهواء؟', null, null, '["الدائرة","الخط المستقيم","القطع المكافئ","القطع الناقص"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 161–163 — مسار المقذوف (القطع المكافئ)'),
('mcq', 2, 'ركل لاعب كرة من سطح الأرض بزاوية فوق الأفق. بإهمال مقاومة الهواء، أيّ المسارات في الشكل الآتي يمثل حركة الكرة؟', null, '[{"src":"qimg/phys1/c6l1-o04-paths-ground.svg","alt":"أربعة مسارات مرقمة لكرة تبدأ من سطح الأرض. (1): خط مستقيم مائل يرتفع إلى أعلى وإلى اليمين. (2): خطان مستقيمان على شكل حرف V مقلوب، يرتفع ثم ينزل برأس حاد. (3): منحنى أملس يرتفع ثم ينحني تدريجيًا ويهبط إلى الأرض. (4): خط مائل يرتفع ثم خط أفقي ثم خط رأسي يهبط إلى الأرض."}]'::jsonb, '["المسار (1)","المسار (3)","المسار (2)","المسار (4)"]'::jsonb, 'فهم', 'تعرّف المسار من شكل', 'سهل', 'الكتاب ص 161–163 — مسار المقذوف (القطع المكافئ)'),
('mcq', 3, 'بمَ يفسَّر اتخاذ مسار المقذوف شكل القطع المكافئ؟', null, null, '["بتسارع أفقي ثابت مع سرعة رأسية ثابتة","بتناقص السرعة الأفقية وتزايد السرعة الرأسية بالمعدل نفسه","بثبات مقدار سرعة المقذوف طوال حركته","بسرعة أفقية ثابتة مع تسارع رأسي منتظم"]'::jsonb, 'فهم', 'تفسير شكل المسار', 'متوسط', 'الكتاب ص 163 — «السرعة الأفقية الثابتة والتسارع الرأسي المنتظم قد أنتجا معًا مسارًا يتخذ شكل القطع المكافئ»'),
('mcq', 4, 'قُذفت كرة أفقيًا من فوق جرف مرتفع. بإهمال مقاومة الهواء، أيّ المسارات في الشكل الآتي يمثل حركتها حتى تصل إلى الأرض؟', null, '[{"src":"qimg/phys1/c6l1-o04-paths-cliff.svg","alt":"أربعة مسارات مرقمة لكرة تنطلق من قمة جرف مرتفع. (1): خط مستقيم مائل من قمة الجرف إلى الأرض. (2): خط أفقي من قمة الجرف ثم خط رأسي إلى الأرض بزاوية قائمة. (3): منحنى يبدأ أفقيًا من قمة الجرف ثم ينحني تدريجيًا إلى أسفل حتى الأرض. (4): منحنى يرتفع أولًا فوق مستوى الجرف ثم يهبط إلى الأرض."}]'::jsonb, '["المسار (3)","المسار (1)","المسار (4)","المسار (2)"]'::jsonb, 'فهم', 'تعرّف المسار من شكل', 'متوسط', 'الكتاب ص 162–163 — الكرة المقذوفة أفقيًا'),
('mcq', 5, 'لو أمكن إيقاف تأثير الجاذبية الأرضية في كرة لحظة قذفها بزاوية فوق الأفق (مع إهمال مقاومة الهواء)، فكيف سيكون مسارها؟', null, null, '["قطعًا مكافئًا أوسع من مسارها المعتاد","قطعًا مكافئًا أضيق من مسارها المعتاد","خطًا مستقيمًا في اتجاه سرعتها الابتدائية","خطًا رأسيًا إلى أعلى مهما كانت الزاوية"]'::jsonb, 'فهم', 'استنتاج دور الجاذبية', 'متوسط', 'الكتاب ص 161 — «وهذه القوة هي التي تجعله يتحرك في مسار منحنٍ»'),
('mcq', 6, 'صُوّرت كرة قُذفت أفقيًا كل 0.1 s، وسُجلت مواقعها في الجدول الآتي (الموقع الرأسي سالب لأن +y إلى أعلى ونقطة الإطلاق هي الأصل). ماذا تدل عليه هذه البيانات بشأن شكل المسار؟', '{"headers":["الزمن (s)","الموقع الأفقي x (m)","الموقع الرأسي y (m)"],"rows":[["0","0","0"],["0.1","0.30","$-0.049$"],["0.2","0.60","$-0.196$"],["0.3","0.90","$-0.441$"],["0.4","1.20","$-0.784$"]]}'::jsonb, null, '["مسار مستقيم؛ لأن الموقع الأفقي يتغير بمقادير متساوية","قطع مكافئ؛ لأن تغيرات x متساوية وتغيرات y تتزايد بانتظام","مسار مستقيم؛ لأن x وy كليهما يتغيران مع الزمن","مسار دائري؛ لأن الكرة تقترب من الأرض باستمرار"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 161–163 — مسار المقذوف (القطع المكافئ)'),
('mcq', 7, 'قُذفت كرة حديدية وكرة مطاطية أخف منها بالسرعة المتجهة الابتدائية نفسها ومن النقطة نفسها. بإهمال مقاومة الهواء، كيف يقارَن مساراهما؟', null, null, '["مسار الكرة الحديدية أكثر انحناءً لأنها أثقل","مسار الكرة المطاطية أعلى وأطول لأنها أخف","المساران قطعان مكافئان متطابقان تمامًا","مسار الحديدية مستقيم ومسار المطاطية منحنٍ"]'::jsonb, 'تحليل', 'مقارنة مسارين', 'صعب', 'الكتاب ص 161 — «بغض النظر عن كتلة الجسم المقذوف»'),
('essay', 1, 'ما شكل مسار المقذوف المطلق بزاوية فوق الأفق؟ وصف مراحل حركته على هذا المسار.', null, null, null, 'فهم', 'وصف المسار', 'سهل', 'الكتاب ص 161–163 — مسار المقذوف (القطع المكافئ)'),
('essay', 2, 'فسّر لماذا يتخذ مسار المقذوف شكل القطع المكافئ، مستعينًا بما يحدث لكل من الحركة الأفقية والحركة الرأسية بإهمال مقاومة الهواء.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 163 — الشكل 6-2'),
('essay', 3, 'صُوّرت كرة قُذفت أفقيًا كل 0.1 s، وسُجلت مواقعها في الجدول الآتي (+y إلى أعلى، ونقطة الإطلاق هي الأصل). (a) صف كيف يتغير كل من x وy في الفترات الزمنية المتساوية. (b) احسب النسبة $\frac{y}{x^2}$ للنقاط الأربع الأخيرة، وماذا تستنتج؟ (c) ما شكل المسار؟', '{"headers":["الزمن (s)","الموقع الأفقي x (m)","الموقع الرأسي y (m)"],"rows":[["0","0","0"],["0.1","0.20","$-0.049$"],["0.2","0.40","$-0.196$"],["0.3","0.60","$-0.441$"],["0.4","0.80","$-0.784$"]]}'::jsonb, null, null, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 161–163 — مسار المقذوف (القطع المكافئ)')
