('mcq', 1, 2, 'يتحرك المقذوف في مسار منحنٍ يُسمى في الرياضيات القطع المكافئ.', '["الحركة على دائرة هي الحركة الدائرية، ومسار المقذوف لا يحافظ على بعد ثابت من مركز.","المسار لا يكون مستقيمًا لأن الجاذبية الأرضية تحني مسار الجسم باستمرار.","","القطع الناقص ليس الشكل الذي يسلكه المقذوف قرب سطح الأرض؛ فالمسار قطع مكافئ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-21T13:36:33.148Z"}'::jsonb),
('mcq', 2, 1, 'المقذوف يرتفع مسافة ما ثم يغيّر اتجاهه تدريجيًا ويهبط في منحنٍ أملس على شكل قطع مكافئ، وهذا هو المسار (3).', '["المسار (1) خط مستقيم، وهو مسار جسم لا تؤثر فيه الجاذبية الأرضية.","","المسار (2) مكوّن من خطين مستقيمين يلتقيان عند رأس حاد، كأن الاتجاه يتغير فجأة عند القمة، والجاذبية تغيّر الاتجاه تدريجيًا.","المسار (4) يجعل الكرة تتحرك أفقيًا ثم تسقط رأسيًا فجأة، وهذا يعني توقف حركتها الأفقية، والسرعة الأفقية تبقى ثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-21T13:36:33.148Z"}'::jsonb),
('mcq', 3, 3, 'تتحد حركتان مستقلتان: حركة أفقية بسرعة ثابتة (لا قوة أفقية)، وحركة رأسية بتسارع منتظم بسبب الجاذبية؛ والسرعة الأفقية الثابتة والتسارع الرأسي المنتظم معًا ينتجان مسارًا على شكل القطع المكافئ.', '["هذا عكس الصحيح؛ فلا تسارع أفقي للمقذوف، والسرعة الرأسية هي التي تتغير.","السرعة الأفقية لا تتناقص؛ فهي ثابتة لعدم وجود قوة أفقية.","مقدار سرعة المقذوف يتغير (يقل في الصعود ويزيد في النزول) لأن مركّبتها الرأسية تتغير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.148Z"}'::jsonb),
('mcq', 4, 0, 'الكرة المقذوفة أفقيًا تبدأ حركتها أفقيًا، ثم يزداد انحناء مسارها إلى أسفل تدريجيًا لأن سرعتها الرأسية تتزايد بانتظام بينما تبقى سرعتها الأفقية ثابتة؛ فيكون المسار نصف قطع مكافئ، وهو المسار (3).', '["","المسار (1) خط مستقيم مائل، ولو كان كذلك لكانت السرعة الرأسية ثابتة، وهي تتزايد بسبب الجاذبية.","المسار (4) يرتفع أولًا، وهذا يحتاج إلى سرعة ابتدائية رأسية إلى أعلى، والكرة قُذفت أفقيًا.","المسار (2) يفترض أن الكرة تتحرك أفقيًا دون سقوط ثم تسقط رأسيًا، والحركتان تحدثان معًا في الوقت نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-21T13:36:33.149Z"}'::jsonb),
('mcq', 5, 2, 'الجاذبية الأرضية هي القوة التي تحني مسار المقذوف؛ فإذا انعدمت لم تؤثر في الكرة أيّ قوة، فتتحرك بسرعة متجهة ثابتة في خط مستقيم في اتجاه سرعتها الابتدائية.', '["لا يتكون قطع مكافئ دون تسارع رأسي؛ فالانحناء سببه الجاذبية.","الانحناء يحتاج إلى قوة تؤثر في الكرة، ولا قوة هنا.","","الكرة لها سرعة أفقية ابتدائية، فلا تتحرك رأسيًا فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-21T13:36:33.149Z"}'::jsonb),
('mcq', 6, 1, 'التغير في x ثابت (0.30 m كل 0.1 s) أي سرعة أفقية ثابتة، بينما التغيرات في y هي 0.049 و0.147 و0.245 و0.343 m أي تتزايد بمقدار ثابت (0.098 m) بسبب التسارع الرأسي المنتظم؛ والسرعة الأفقية الثابتة مع التسارع الرأسي المنتظم تنتجان معًا مسارًا على شكل قطع مكافئ.', '["ثبات تغير x وحده لا يكفي لاستقامة المسار؛ فالمسار المستقيم يتطلب أن يتغير y أيضًا بمقادير متساوية، وتغيراته متزايدة.","","تغير الإحداثيين لا يعني الاستقامة؛ فالشرط أن تكون نسبة التغيرين ثابتة، وهي هنا متزايدة.","الاقتراب من الأرض لا يعني مسارًا دائريًا؛ فالسرعة الأفقية الثابتة مع التسارع الرأسي المنتظم تنتجان قطعًا مكافئًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-21T13:36:33.149Z"}'::jsonb),
('mcq', 7, 2, 'المساران قطعان مكافئان متطابقان: فبإهمال مقاومة الهواء يتسارع كل جسم في الهواء بتسارع الجاذبية $g$ نفسه مهما كانت كتلته، ولأن السرعة الابتدائية واحدة تكون المركّبتان الأفقية والرأسية متماثلتين في كل لحظة، فيتطابق المساران.', '["الوزن الأكبر يقابله قصور ذاتي أكبر، فيبقى التسارع $g$ نفسه ولا يزداد الانحناء.","خفة الكتلة لا تزيد الارتفاع ولا المدى عند إهمال مقاومة الهواء؛ فالتسارع $g$ للجسمين.","","كلا الجسمين تؤثر فيه الجاذبية فيتحرك في قطع مكافئ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-21T13:36:33.150Z"}'::jsonb),
('essay', 1, null::int, null, null, 'مسار المقذوف منحنٍ على شكل قطع مكافئ. يرتفع الجسم فيه أولًا إلى أعلى مسافة ما بينما يتقدم أفقيًا، ثم يغير اتجاهه تدريجيًا عند أعلى نقطة، ثم يتحرك إلى أسفل وهو مستمر في التقدم أفقيًا حتى يصل إلى الأرض.', '["الشكل: قطع مكافئ (منحنٍ)","يرتفع إلى أعلى مع التقدم أفقيًا","يغير اتجاهه تدريجيًا عند أعلى نقطة","يتحرك إلى أسفل مع استمرار التقدم أفقيًا"]'::jsonb, '[]'::jsonb, '[{"element":"الشكل","marks":1},{"element":"مرحلة الصعود","marks":1},{"element":"تغير الاتجاه","marks":1},{"element":"مرحلة النزول","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تسمية الشكل ووصف المراحل كاملة"},{"level":"2–3 درجات","description":"تسمية الشكل مع وصف ناقص"},{"level":"درجة واحدة","description":"تسمية الشكل فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف المسار بأنه دائري أو مستقيم","القول إن الجسم يتوقف أفقيًا عند أعلى نقطة ثم يسقط رأسيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.150Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تُحلَّل حركة المقذوف إلى حركتين مستقلتين: (1) أفقية: لا تؤثر قوة أفقية في المقذوف، فلا تسارع أفقي، فيقطع مسافات أفقية متساوية في فترات زمنية متساوية (سرعة أفقية ثابتة). (2) رأسية: تؤثر الجاذبية الأرضية إلى أسفل فيتسارع رأسيًا بتسارع منتظم $g$، فتتغير المسافات الرأسية المقطوعة في فترات متساوية بمقادير متزايدة. واتحاد الحركة الأفقية المنتظمة مع الحركة الرأسية المتسارعة بانتظام يجعل الإزاحة الرأسية تتناسب مع مربع الإزاحة الأفقية، فينتج مسار على شكل القطع المكافئ.', '["الحركة الأفقية: لا قوة أفقية فالسرعة الأفقية ثابتة","الحركة الرأسية: الجاذبية تعطي تسارعًا منتظمًا","الحركتان مستقلتان وتحدثان معًا","اتحادهما ينتج قطعًا مكافئًا"]'::jsonb, '[]'::jsonb, '[{"element":"الحركة الأفقية","marks":1},{"element":"الحركة الرأسية","marks":1},{"element":"الاستقلالية والتزامن","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للحركتين واتحادهما"},{"level":"2–3 درجات","description":"تفسير إحدى الحركتين بدقة والأخرى ناقصة"},{"level":"درجة واحدة","description":"ذكر الجاذبية دون تفصيل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن للمقذوف تسارعًا أفقيًا","القول إن السرعة الأفقية تتناقص حتى تنعدم عند القمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.150Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) يزداد x بمقدار ثابت 0.20 m كل 0.1 s (سرعة أفقية ثابتة 2.0 m/s)، بينما يتغير y بمقادير متزايدة: $-0.049$ ثم $-0.147$ ثم $-0.245$ ثم $-0.343$ m (حركة رأسية متسارعة بانتظام). (b) $\frac{y}{x^2} = \frac{-0.049}{0.20^2} = \frac{-0.196}{0.40^2} = \frac{-0.441}{0.60^2} = \frac{-0.784}{0.80^2} = -1.2\ \text{m}^{-1}$ أي ثابتة؛ فالإزاحة الرأسية تتناسب طرديًا مع مربع الإزاحة الأفقية. (c) المسار قطع مكافئ.', '["x يتغير بمقادير متساوية","y يتغير بمقادير متزايدة","النسبة $\\frac{y}{x^2}$ ثابتة","الشكل قطع مكافئ"]'::jsonb, '["تغيرات x: 0.20 m في كل فترة","تغيرات y: $-0.049$، $-0.147$، $-0.245$، $-0.343$ m","$\\frac{y}{x^2} = -1.2\\ \\text{m}^{-1}$ للنقاط الأربع","$y \\propto x^2$ ← قطع مكافئ"]'::jsonb, '[{"element":"وصف x","marks":1},{"element":"وصف y","marks":1},{"element":"حساب النسبة","marks":1},{"element":"الاستنتاج والشكل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الوصف والحساب والاستنتاج صحيحة"},{"level":"2–3 درجات","description":"الوصف صحيح وخطأ في الحساب أو الاستنتاج"},{"level":"درجة واحدة","description":"وصف أحد المتغيرين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب $\\frac{y}{x}$ بدل $\\frac{y}{x^2}$ واستنتاج أن المسار مستقيم","إهمال الإشارة السالبة لـ y"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-21T13:36:33.151Z"}'::jsonb)
