('mcq', 3, 'يبين الشكل الآتي صورًا متتالية لكرة قُذفت أفقيًا، التُقطت على فترات زمنية متساوية أمام خلفية مقسمة إلى مربعات. ماذا تدل عليه المسافات الأفقية المتساوية بين الصور المتتالية؟', null, '[{"src":"qimg/phys1/c6l1-o05-strobe.svg","alt":"خلفية مقسمة إلى مربعات، وعليها ست صور لكرة صفراء التُقطت كل 0.1 s. الصور متباعدة أفقيًا بمسافات متساوية (مربعان بين كل صورتين)، بينما يزداد هبوطها الرأسي من صورة إلى التي تليها بمقادير متزايدة."}]'::jsonb, '["أن الكرة لا تسقط رأسيًا","أن تسارع الكرة الأفقي يزداد بانتظام","أن الجاذبية الأرضية تؤثر في الكرة أفقيًا","أن السرعة الأفقية للكرة ثابتة لعدم وجود قوة أفقية"]'::jsonb, 'فهم', 'تفسير صور متتالية', 'متوسط', 'الكتاب ص 162–163 — الشكلان 6-1 و6-2'),
('mcq', 4, 'قُذفت كرة أفقيًا بسرعة 6.0 m/s من فوق سطح بناية. بإهمال مقاومة الهواء، ما مقدار المركّبة الأفقية لسرعتها بعد 1.5 s من قذفها (قبل أن تصل إلى الأرض)؟ ($g = 9.80\ \text{m/s}^2$)', null, null, '["20.7 m/s","14.7 m/s","6.0 m/s","15.9 m/s"]'::jsonb, 'تطبيق', 'حساب مركّبة', 'متوسط', 'الكتاب ص 163 — ثبات السرعة الأفقية للمقذوف ($\boldsymbol{a}_x = 0$)'),
('mcq', 5, 'أيّ المنحنيات في الشكل الآتي يمثل المركّبة الأفقية لسرعة مقذوف بدلالة الزمن في أثناء طيرانه بإهمال مقاومة الهواء؟', null, '[{"src":"qimg/phys1/c6l1-o05-vx-graphs.svg","alt":"أربعة منحنيات مرقمة، المحور الرأسي في كل منها المركّبة الأفقية للسرعة المتجهة v_x (m/s) والمحور الأفقي الزمن t (s). (1): خط مستقيم يبدأ عاليًا وينحدر إلى أسفل. (2): خط أفقي عند قيمة موجبة ثابتة لا تساوي صفرًا. (3): خط مستقيم يبدأ منخفضًا ويرتفع إلى أعلى. (4): خط أفقي منطبق على محور الزمن (القيمة صفر)."}]'::jsonb, '["المنحنى (1)","المنحنى (4)","المنحنى (3)","المنحنى (2)"]'::jsonb, 'تحليل', 'قراءة منحنيات', 'متوسط', 'الكتاب ص 163 — ثبات السرعة الأفقية للمقذوف ($\boldsymbol{a}_x = 0$)'),
('mcq', 6, 'متى لا تبقى السرعة الأفقية لمقذوف ثابتة؟', null, null, '["عندما تكون كتلة المقذوف كبيرة جدًا","عندما يكون للمقذوف سرعة رأسية ابتدائية","عندما تكون مقاومة الهواء كبيرة فتؤثر فيه قوة أفقية","عندما يصل المقذوف إلى أعلى نقطة في مساره"]'::jsonb, 'فهم', 'تحديد شرط', 'صعب', 'الكتاب ص 163، 166 — مقاومة الهواء'),
('mcq', 7, 'يقول طالب: «تتناقص السرعة الأفقية لكرة مقذوفة أفقيًا تدريجيًا لأن الجاذبية الأرضية تشدّها». بإهمال مقاومة الهواء، ما التقويم الصحيح لهذه العبارة؟', null, null, '["صحيحة؛ لأن الجاذبية تبطئ كل حركة","خاطئة؛ لأن الجاذبية رأسية فتغيّر السرعة الرأسية فقط","صحيحة؛ لأن الكرة تتوقف في النهاية عند الأرض","خاطئة؛ لأن الجاذبية لا تؤثر في الكرة وهي تتحرك أفقيًا"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 163 — ثبات السرعة الأفقية للمقذوف ($\boldsymbol{a}_x = 0$)'),
('essay', 1, 'فسّر، مستعينًا بقوانين نيوتن، لماذا تبقى المركّبة الأفقية لسرعة المقذوف ثابتة عند إهمال مقاومة الهواء.', null, null, null, 'فهم', 'تفسير بقوانين نيوتن', 'سهل', 'الكتاب ص 163 — ثبات السرعة الأفقية للمقذوف ($\boldsymbol{a}_x = 0$)'),
('essay', 2, 'تتدحرج كرة على سطح طاولة أفقي بسرعة 1.40 m/s ثم تغادر حافته، فتصل إلى الأرض بعد 0.45 s. بإهمال مقاومة الهواء: (a) ما مقدار المركّبة الأفقية لسرعة الكرة لحظة وصولها إلى الأرض؟ فسّر. (b) احسب المسافة الأفقية بين حافة الطاولة ونقطة سقوط الكرة.', null, null, null, 'تطبيق', 'حساب وتفسير', 'متوسط', 'الكتاب ص 163 — ثبات السرعة الأفقية للمقذوف ($\boldsymbol{a}_x = 0$)'),
('essay', 3, 'قارن بين حالتين لكرة مقذوفة أفقيًا من الارتفاع نفسه وبالسرعة نفسها: (أ) بإهمال مقاومة الهواء، و(ب) بوجود مقاومة هواء كبيرة. بيّن في كل حالة القوى الأفقية المؤثرة، وما يحدث للمركّبة الأفقية للسرعة، وأثر ذلك في المسافة الأفقية التي تقطعها الكرة قبل وصولها إلى الأرض.', null, null, null, 'تقويم', 'مقارنة حالتين', 'صعب', 'الكتاب ص 163، 166 — مقاومة الهواء')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
