insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'عند إهمال مقاومة الهواء لا تؤثر في المقذوف أيّ قوة أفقية، فلا يكون له تسارع أفقي ($\boldsymbol{a}_x = 0$)، فتبقى سرعته الأفقية ثابتة.', '["","قوة الإطلاق تزول بعد مغادرة الجسم للقاذف؛ ولو استمرت لزادت سرعته الأفقية.","الجاذبية الأرضية قوة رأسية إلى أسفل، وليست لها مركّبة أفقية.","التسارع الرأسي لا يساوي صفرًا بل $g$ إلى أسفل؛ وثبات السرعة الأفقية سببه انعدام التسارع الأفقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-21T13:36:33.151Z"}'::jsonb),
('mcq', 2, 1, 'لا توجد قوة أفقية تؤثر في الكرة، فوفق القانون الثاني لنيوتن $\boldsymbol{a}_x = 0$ طوال الحركة.', '["هذه قيمة التسارع الرأسي $\\boldsymbol{a}_y = -\\boldsymbol{g}$، لا الأفقي؛ فالجاذبية لا تعطي تسارعًا أفقيًا.","","$9.80\\ \\text{m/s}^2$ مقدار تسارع الجاذبية وهو رأسي، ولا يؤثر أفقيًا.","التسارع الأفقي لا يتغير؛ فهو صفر من البداية لعدم وجود قوة أفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.152Z"}'::jsonb),
('mcq', 3, 3, 'تقطع الكرة مسافات أفقية متساوية في فترات زمنية متساوية، فسرعتها الأفقية ثابتة؛ وسبب ذلك عدم وجود قوة أفقية تؤثر فيها ($\boldsymbol{a}_x = 0$).', '["الصور تبين أن الكرة تهبط رأسيًا بمسافات متزايدة، فهي تسقط.","لو ازداد التسارع الأفقي لتزايدت المسافات الأفقية، وهي متساوية.","الجاذبية رأسية؛ ولو أثرت أفقيًا لتغيرت المسافات الأفقية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-21T13:36:33.152Z"}'::jsonb),
('mcq', 4, 2, 'لا قوة أفقية، فالتسارع الأفقي صفر، وتبقى المركّبة الأفقية للسرعة مساوية لقيمتها الابتدائية: $v_x = 6.0\ \text{m/s}$.', '["جُمع $gt = 14.7\\ \\text{m/s}$ إلى السرعة الأفقية، كأن الجاذبية تزيد السرعة الأفقية.","هذا مقدار المركّبة الرأسية $gt$ بعد 1.5 s، لا الأفقية.","","هذا مقدار السرعة المحصلة $\\sqrt{6.0^2 + 14.7^2}$، والمطلوب المركّبة الأفقية فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.153Z"}'::jsonb),
('mcq', 5, 3, 'المركّبة الأفقية للسرعة ثابتة (لا يوجد تسارع أفقي)، فيكون منحنى (السرعة المتجهة الأفقية – الزمن) خطًا أفقيًا عند قيمة لا تساوي صفرًا، وهو المنحنى (2).', '["المنحنى (1) يمثل سرعة أفقية متناقصة، أي تسارعًا أفقيًا معاكسًا، ولا توجد قوة أفقية.","المنحنى (4) يمثل سرعة أفقية صفرية، أي جسمًا يسقط رأسيًا فقط، والمقذوف يتقدم أفقيًا.","المنحنى (3) يمثل سرعة أفقية متزايدة، وهذا يتطلب قوة أفقية في اتجاه الحركة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-21T13:36:33.153Z"}'::jsonb),
('mcq', 6, 2, 'تبقى السرعة الأفقية ثابتة فقط عند عدم وجود قوة أفقية؛ فإذا كانت مقاومة الهواء مهمة أثرت في المقذوف قوة معيقة تعاكس حركته ولها مركّبة أفقية، فتتناقص سرعته الأفقية.', '["الكتلة لا تولّد قوة أفقية؛ فالوزن رأسي مهما كانت الكتلة.","السرعة الرأسية الابتدائية لا تؤثر في الحركة الأفقية؛ فالحركتان مستقلتان.","","عند أعلى نقطة تنعدم المركّبة الرأسية فقط، وتبقى الأفقية كما هي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-21T13:36:33.154Z"}'::jsonb),
('mcq', 7, 1, 'الجاذبية الأرضية قوة رأسية إلى أسفل، فلا مركّبة أفقية لها، ولذلك تغيّر المركّبة الرأسية للسرعة فقط، بينما تبقى المركّبة الأفقية ثابتة ($\boldsymbol{a}_x = 0$).', '["الجاذبية لا تبطئ كل حركة؛ فهي تؤثر رأسيًا فقط، بل تزيد سرعة الجسم الهابط.","","توقف الكرة عند الأرض سببه قوة التلامس مع الأرض، لا الجاذبية في أثناء الطيران.","الجاذبية تؤثر في الكرة دائمًا؛ والصحيح أنها تؤثر رأسيًا لا أنها لا تؤثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-21T13:36:33.154Z"}'::jsonb),
('essay', 1, null::int, null, null, 'القوة الوحيدة المؤثرة في المقذوف بعد إطلاقه هي قوة الجاذبية الأرضية، وهي رأسية إلى أسفل، فلا توجد قوة تؤثر فيه في الاتجاه الأفقي؛ أي إن القوة المحصلة الأفقية صفر. ووفق القانون الثاني لنيوتن ($\boldsymbol{a} = \frac{\boldsymbol{F}_{\text{المحصلة}}}{m}$) يكون التسارع الأفقي صفرًا ($\boldsymbol{a}_x = 0$)، ووفق القانون الأول يحافظ الجسم على سرعته الأفقية، فتبقى المركّبة الأفقية لسرعته ثابتة طوال طيرانه.', '["القوة الوحيدة هي الجاذبية وهي رأسية","المحصلة الأفقية صفر","$\\boldsymbol{a}_x = 0$ (القانون الثاني)","السرعة الأفقية ثابتة"]'::jsonb, '[]'::jsonb, '[{"element":"الجاذبية رأسية","marks":1},{"element":"المحصلة الأفقية صفر","marks":1},{"element":"التسارع الأفقي صفر","marks":1},{"element":"ثبات السرعة الأفقية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير متسلسل كامل"},{"level":"2–3 درجات","description":"تفسير صحيح ناقص خطوة"},{"level":"درجة واحدة","description":"ذكر النتيجة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن قوة الإطلاق تحافظ على السرعة الأفقية","الخلط بين ثبات السرعة الأفقية وثبات مقدار السرعة الكلية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-21T13:36:33.154Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $v_x = 1.40\ \text{m/s}$؛ لأنه لا توجد قوة أفقية تؤثر في الكرة بعد مغادرتها الطاولة، فالتسارع الأفقي صفر وتبقى المركّبة الأفقية كما كانت لحظة المغادرة. (b) الحركة الأفقية منتظمة: $x = v_x t = (1.40\ \text{m/s})(0.45\ \text{s}) = 0.63\ \text{m}$.', '["$v_x = 1.40\\ \\text{m/s}$","التفسير: لا قوة أفقية فـ $\\boldsymbol{a}_x = 0$","$x = v_x t$","$x = 0.63\\ \\text{m}$"]'::jsonb, '["$\\boldsymbol{a}_x = 0$ ⇐ $v_x = 1.40\\ \\text{m/s}$ عند الأرض","$x = v_x t = (1.40)(0.45)$","$x = 0.63\\ \\text{m}$"]'::jsonb, '[{"element":"قيمة $v_x$","marks":1},{"element":"التفسير","marks":1},{"element":"العلاقة","marks":1},{"element":"الناتج بالوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"2–3 درجات","description":"خطأ في التفسير أو في الحساب"},{"level":"درجة واحدة","description":"قيمة $v_x$ فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال $x = \\frac{1}{2}at^2$ للحركة الأفقية","القول إن المركّبة الأفقية تزداد بسبب السقوط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.155Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) بإهمال مقاومة الهواء: لا توجد قوة أفقية، فـ $\boldsymbol{a}_x = 0$ وتبقى المركّبة الأفقية للسرعة ثابتة، فتقطع الكرة مسافات أفقية متساوية في فترات زمنية متساوية. (ب) بوجود مقاومة هواء كبيرة: تؤثر قوة معيقة تعاكس اتجاه الحركة ولها مركّبة أفقية معاكسة للسرعة الأفقية، فيصبح للكرة تسارع أفقي معاكس وتتناقص مركّبتها الأفقية مع الزمن. لذا تكون المسافة الأفقية في الحالة (ب) أقل منها في الحالة (أ). ويُستنتج أن ثبات السرعة الأفقية مشروط بانعدام القوة الأفقية.', '["(أ) لا قوة أفقية و$\\boldsymbol{a}_x = 0$","(أ) المركّبة الأفقية ثابتة","(ب) قوة معيقة لها مركّبة أفقية معاكسة فتتناقص المركّبة الأفقية","المسافة الأفقية في (ب) أقل"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة أ: القوى","marks":1},{"element":"الحالة أ: السرعة","marks":1},{"element":"الحالة ب: القوى والسرعة","marks":1},{"element":"المقارنة في المسافة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة مع التبرير"},{"level":"2–3 درجات","description":"وصف صحيح لحالة واحدة مع مقارنة ناقصة"},{"level":"درجة واحدة","description":"عبارة صحيحة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن مقاومة الهواء تزيد السرعة الأفقية","القول إن السرعة الأفقية تتناقص حتى في غياب مقاومة الهواء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-21T13:36:33.155Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C6-L1-O05') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L1-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'قُذفت كرة أفقيًا من قمة جرف ارتفاعه 44.1 m كما في الشكل الآتي. بإهمال مقاومة الهواء، ما الزمن الذي تستغرقه الكرة لتصل إلى الأرض؟ ($g = 9.80\ \text{m/s}^2$)', null, '[{"src":"qimg/phys1/c6l1-o06-cliff.svg","alt":"جرف ارتفاعه 44.1 m مكتوب بجانب سهم بُعد رأسي. على حافة قمته كرة، وفوقها سهم أحمر أفقي إلى اليمين مكتوب عنده 7.0 m/s. من الكرة مسار منحنٍ متقطع يهبط إلى الأرض. في الأعلى مؤشر الاتجاهين الموجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, '["2.12 s","3.00 s","4.50 s","9.00 s"]'::jsonb, 'تطبيق', 'حساب زمن السقوط', 'سهل', 'الكتاب ص 163–164 — المقذوفات التي تُطلق أفقيًا (مسائل تدريبية 1–2)'),
('mcq', 2, 'قُذف حجر أفقيًا بسرعة 12.0 m/s من ارتفاع 19.6 m فوق أرض مستوية. بإهمال مقاومة الهواء، على أيّ بعد أفقي من نقطة القذف يصطدم الحجر بالأرض؟ ($g = 9.80\ \text{m/s}^2$)', null, null, '["17.0 m","48.0 m","19.6 m","24.0 m"]'::jsonb, 'تطبيق', 'حساب المدى الأفقي', 'سهل', 'الكتاب ص 163–164 — المقذوفات التي تُطلق أفقيًا (مسائل تدريبية 1–2)'),
('mcq', 3, 'تتحرك سيارة لعبة على سطح طاولة ارتفاعها 0.784 m، ثم تغادر حافتها أفقيًا كما في الشكل الآتي. ما المركّبة الرأسية لسرعة السيارة لحظة اصطدامها بالأرض؟ (اعتبر +y إلى أعلى، وأهمل مقاومة الهواء، $g = 9.80\ \text{m/s}^2$)', null, '[{"src":"qimg/phys1/c6l1-o06-table-fall.svg","alt":"طاولة ارتفاعها 0.784 m مكتوب بجانب سهم بُعد رأسي. على حافة سطحها سيارة لعبة، وفوقها سهم أحمر أفقي إلى اليمين مكتوب عنده v. من حافة الطاولة مسار منحنٍ متقطع يهبط إلى الأرض. في الأعلى مؤشر الاتجاهين الموجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, '["$+3.92\\ \\text{m/s}$","$-1.96\\ \\text{m/s}$","$-3.92\\ \\text{m/s}$","$0\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'حساب مركّبة السرعة الرأسية', 'متوسط', 'الكتاب ص 181 — التقويم 38–40'),
('mcq', 4, 'تنطلق قطع خشبية أفقيًا من حافة حزام ناقل، فتسقط داخل صندوق يقع على بعد رأسي 1.80 m أسفل الحزام وعلى بعد أفقي 3.0 m من حافته. ما مقدار السرعة الأفقية للقطع لحظة مغادرتها الحزام؟ (أهمل مقاومة الهواء، $g = 9.80\ \text{m/s}^2$)', null, null, '["7.0 m/s","5.0 m/s","1.8 m/s","8.2 m/s"]'::jsonb, 'تطبيق', 'حساب السرعة الابتدائية', 'صعب', 'الكتاب ص 164 — المسألة التدريبية 2'),
('mcq', 5, 'قُذفت كرة أفقيًا بسرعة 15.0 m/s من ارتفاع 20.0 m فوق أرض مستوية. بإهمال مقاومة الهواء، ما مقدار سرعتها المتجهة لحظة اصطدامها بالأرض؟ ($g = 9.80\ \text{m/s}^2$)', null, null, '["34.8 m/s","24.8 m/s","19.8 m/s","15.0 m/s"]'::jsonb, 'تطبيق', 'حساب مقدار السرعة النهائية', 'صعب', 'الكتاب ص 164 — المسألة التدريبية 1c'),
('mcq', 6, 'قُذف حجر أفقيًا بسرعة 8.00 m/s من سطح بناية ارتفاعها 45.0 m كما في الشكل الآتي. بإهمال مقاومة الهواء، ما المسافة الأفقية $x$ بين قاعدة البناية ونقطة سقوط الحجر؟ ($g = 9.80\ \text{m/s}^2$)', null, '[{"src":"qimg/phys1/c6l1-o06-building.svg","alt":"بناية ارتفاعها 45.0 m مكتوب بجانب سهم بُعد رأسي. على حافة سطحها حجر، وفوقه سهم أحمر أفقي إلى اليمين مكتوب عنده 8.00 m/s. من الحجر مسار منحنٍ متقطع يهبط إلى الأرض، والمسافة الأفقية من قاعدة البناية إلى نقطة السقوط مبينة بسهم بُعد مكتوب تحته x. في الأعلى مؤشر الاتجاهين الموجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, '["48.5 m","17.1 m","73.5 m","24.2 m"]'::jsonb, 'تطبيق', 'حساب المدى الأفقي من شكل', 'متوسط', 'الكتاب ص 181 — التقويم 38–40'),
('mcq', 7, 'قُذف حجران أفقيًا من سطح البناية نفسها في اللحظة نفسها؛ الأول بسرعة 10 m/s والثاني بسرعة 20 m/s. بإهمال مقاومة الهواء، أيّ العبارات الآتية صحيحة؟', null, null, '["يصل الحجران إلى الأرض معًا، والمسافة الأفقية للثاني مثلا مسافة الأول","يصل الثاني أولًا، ويقطعان المسافة الأفقية نفسها","يصل الأول أولًا، والمسافة الأفقية للثاني مثلا مسافة الأول","يصل الحجران معًا، ويقطعان المسافة الأفقية نفسها"]'::jsonb, 'فهم', 'مقارنة مقذوفين', 'سهل', 'الكتاب ص 163–164 — المقذوفات التي تُطلق أفقيًا (مسائل تدريبية 1–2)'),
('essay', 1, 'دُحرجت كرة عن حافة جرف ارتفاعه 30.0 m بسرعة أفقية 6.00 m/s. (اعتبر +y إلى أعلى، وأهمل مقاومة الهواء، $g = 9.80\ \text{m/s}^2$) احسب: (a) زمن وصول الكرة إلى الأرض. (b) المسافة الأفقية بين قاعدة الجرف ونقطة سقوطها. (c) المركّبتين الأفقية والرأسية لسرعتها قبيل اصطدامها بالأرض، ومقدار سرعتها.', null, null, null, 'تطبيق', 'مسألة متعددة الخطوات', 'متوسط', 'الكتاب ص 163–164 — المقذوفات التي تُطلق أفقيًا (مسائل تدريبية 1–2)'),
('essay', 2, 'يبين الشكل الآتي سيارة لعبة تغادر حافة طاولة ارتفاعها 1.10 m أفقيًا، فتصطدم بالأرض على بعد 0.500 m من قاعدة الطاولة. بإهمال مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$: (a) ما الزمن الذي تستغرقه السيارة في الهواء؟ (b) ما مقدار سرعتها لحظة مغادرتها سطح الطاولة؟ (c) لو غادرت السيارة الحافة بمثلي هذه السرعة، فما الذي يتغير وما الذي لا يتغير؟', null, '[{"src":"qimg/phys1/c6l1-o06-table-car.svg","alt":"طاولة ارتفاعها 1.10 m مكتوب بجانب سهم بُعد رأسي، وعلى حافة سطحها سيارة لعبة. من حافة الطاولة مسار منحنٍ متقطع يهبط إلى الأرض، والمسافة الأفقية من قاعدة الطاولة إلى نقطة الاصطدام مبينة بسهم بُعد مكتوب تحته 0.500 m. مؤشر الاتجاهين الموجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, null, 'تطبيق', 'مسألة من شكل', 'متوسط', 'الكتاب ص 181 — التقويم 39'),
('essay', 3, 'تُقذف كرة أفقيًا بسرعة 18.0 m/s من سطح منصة ارتفاعها 40.0 m، وأمام المنصة حوض ماء تبدأ حافته القريبة على بعد 30.0 m من قاعدة المنصة وتنتهي حافته البعيدة على بعد 50.0 m منها، كما في الشكل الآتي. بإهمال مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$: هل تسقط الكرة داخل الحوض أم تتجاوزه؟ وضّح حساباتك، واقترح سرعة أفقية تجعل الكرة تسقط في منتصف الحوض.', null, '[{"src":"qimg/phys1/c6l1-o06-pool.svg","alt":"منصة (بناية) ارتفاعها 40.0 m مكتوب بجانب سهم بُعد رأسي. على حافة سطحها كرة، وفوقها سهم أحمر أفقي إلى اليمين مكتوب عنده 18.0 m/s، ومنها جزء من مسار منحنٍ متقطع يتوقف في الهواء قبل أن يصل إلى الأرض. على الأرض أمام المنصة حوض ماء أزرق بيضاوي. سهما بُعد أفقيان من قاعدة المنصة: الأول إلى الحافة القريبة للحوض مكتوب تحته 30.0 m، والثاني إلى الحافة البعيدة مكتوب تحته 50.0 m. مؤشر الاتجاهين الموجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, null, 'تقويم', 'اتخاذ قرار بالحساب', 'صعب', 'الكتاب ص 183 — الأسئلة الممتدة 8')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L1-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الحركة الرأسية تبدأ بسرعة رأسية صفرية: $\Delta y = -\frac{1}{2}gt^2$، فإن $t = \sqrt{\frac{2h}{g}} = \sqrt{\frac{2(44.1\ \text{m})}{9.80\ \text{m/s}^2}} = 3.00\ \text{s}$. والسرعة الأفقية لا تؤثر في زمن السقوط.', '["نُسي العدد 2 (أو العامل $\\frac{1}{2}$): $\\sqrt{\\frac{h}{g}} = 2.12\\ \\text{s}$.","","قُسم الارتفاع على $g$ مباشرة: $\\frac{h}{g} = 4.50$، والوحدة لا تكون ثانية.","نُسي الجذر التربيعي: $\\frac{2h}{g} = 9.00$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-21T13:36:33.157Z"}'::jsonb),
('mcq', 2, 3, 'زمن السقوط من الحركة الرأسية: $t = \sqrt{\frac{2(19.6)}{9.80}} = 2.00\ \text{s}$، ثم من الحركة الأفقية المنتظمة: $x = v_x t = (12.0\ \text{m/s})(2.00\ \text{s}) = 24.0\ \text{m}$.', '["حُسب الزمن دون العدد 2: $t = \\sqrt{\\frac{19.6}{9.80}} = 1.41\\ \\text{s}$، فنتج $17.0\\ \\text{m}$.","نُسي الجذر عند حساب الزمن: $t = \\frac{2(19.6)}{9.80} = 4.00$، فنتج $48.0\\ \\text{m}$.","خُلط بين الإزاحة الرأسية (الارتفاع) والمسافة الأفقية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-21T13:36:33.157Z"}'::jsonb),
('mcq', 3, 2, 'زمن السقوط $t = \sqrt{\frac{2(0.784)}{9.80}} = 0.400\ \text{s}$، والمركّبة الرأسية تبدأ من الصفر: $v_y = v_{yi} + a_y t = 0 + (-9.80\ \text{m/s}^2)(0.400\ \text{s}) = -3.92\ \text{m/s}$، والإشارة السالبة تعني أنها إلى أسفل.', '["أُهملت إشارة $\\boldsymbol{a}_y = -\\boldsymbol{g}$، فخرجت السرعة الرأسية موجبة (إلى أعلى) مع أن السيارة تتحرك إلى أسفل.","استُعمل $\\frac{1}{2}gt$ بدل $gt$، أي خُلطت معادلة السرعة بمعادلة الإزاحة.","","افتُرض أن المركّبة الرأسية تبقى صفرًا كما كانت لحظة المغادرة، مع أن الجاذبية تزيدها إلى أسفل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-21T13:36:33.158Z"}'::jsonb),
('mcq', 4, 1, 'زمن السقوط $t = \sqrt{\frac{2(1.80)}{9.80}} = 0.606\ \text{s}$، والزمن نفسه للحركة الأفقية: $v_x = \frac{x}{t} = \frac{3.0\ \text{m}}{0.606\ \text{s}} = 5.0\ \text{m/s}$.', '["حُسب الزمن دون العدد 2: $t = \\sqrt{\\frac{1.80}{9.80}} = 0.429\\ \\text{s}$، فنتج 7.0 m/s.","","ضُربت المسافة في الزمن بدل القسمة عليه: $(3.0)(0.606) = 1.8$.","نُسي الجذر: $t = \\frac{2(1.80)}{9.80} = 0.367$، فنتج 8.2 m/s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.159Z"}'::jsonb),
('mcq', 5, 1, 'المركّبة الرأسية عند الأرض: $v_y^2 = 2gh$ ⇐ $|v_y| = \sqrt{2(9.80)(20.0)} = 19.8\ \text{m/s}$، والأفقية ثابتة 15.0 m/s؛ فالمقدار $v = \sqrt{v_x^2 + v_y^2} = \sqrt{15.0^2 + 19.8^2} = 24.8\ \text{m/s}$.', '["جُمعت المركّبتان جمعًا عدديًا $15.0 + 19.8$، وهما متعامدتان فتُجمعان بنظرية فيثاغورس.","","هذه المركّبة الرأسية وحدها، ولم تُضف إليها المركّبة الأفقية.","هذه المركّبة الأفقية وحدها، وقد أُهمل تزايد المركّبة الرأسية في أثناء السقوط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-21T13:36:33.160Z"}'::jsonb),
('mcq', 6, 3, '$t = \sqrt{\frac{2(45.0)}{9.80}} = 3.03\ \text{s}$، ثم $x = v_x t = (8.00\ \text{m/s})(3.03\ \text{s}) = 24.2\ \text{m}$.', '["ضوعف زمن السقوط كأنه زمن صعود ونزول، والحجر المقذوف أفقيًا لا يصعد.","حُسب الزمن دون العدد 2: $t = \\sqrt{\\frac{45.0}{9.80}} = 2.14\\ \\text{s}$.","نُسي الجذر: $t = \\frac{2(45.0)}{9.80} = 9.18$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-21T13:36:33.160Z"}'::jsonb),
('mcq', 7, 0, 'زمن السقوط يتحدد بالحركة الرأسية فقط ($t = \sqrt{\frac{2h}{g}}$) وهو متساوٍ للحجرين، فيصلان معًا؛ أما المسافة الأفقية $x = v_x t$ فتتناسب مع السرعة الأفقية، فتكون للثاني مثلي الأول.', '["","السرعة الأفقية الأكبر لا تقلل زمن السقوط؛ فالحركتان مستقلتان.","السرعة الأفقية الأصغر لا تجعل السقوط أسرع؛ فالزمن يعتمد على الارتفاع فقط.","تساوي الزمن صحيح، لكن المسافة الأفقية تعتمد على السرعة الأفقية فلا تتساوى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.161Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $\Delta y = -\frac{1}{2}gt^2$ ⇐ $t = \sqrt{\frac{2(30.0)}{9.80}} = 2.47\ \text{s}$. (b) $x = v_x t = (6.00)(2.47) = 14.8\ \text{m}$. (c) $v_x = 6.00\ \text{m/s}$ (ثابتة)، و$v_y = -gt = -(9.80)(2.47) = -24.2\ \text{m/s}$ (إلى أسفل)، ومقدار السرعة $v = \sqrt{6.00^2 + 24.2^2} = 25.0\ \text{m/s}$.', '["$t = 2.47\\ \\text{s}$","$x = 14.8\\ \\text{m}$","$v_x = 6.00\\ \\text{m/s}$ و$v_y = -24.2\\ \\text{m/s}$","$v = 25.0\\ \\text{m/s}$"]'::jsonb, '["$-30.0 = -\\frac{1}{2}(9.80)t^2$ ⇐ $t = 2.47\\ \\text{s}$","$x = v_x t = (6.00)(2.47) = 14.8\\ \\text{m}$","$v_x = 6.00\\ \\text{m/s}$","$v_y = v_{yi} + a_y t = 0 + (-9.80)(2.47) = -24.2\\ \\text{m/s}$","$v = \\sqrt{v_x^2 + v_y^2} = 25.0\\ \\text{m/s}$"]'::jsonb, '[{"element":"الزمن","marks":1},{"element":"المسافة الأفقية","marks":1},{"element":"المركّبتان","marks":1},{"element":"مقدار السرعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الحسابات صحيحة بالوحدات والأرقام المعنوية"},{"level":"2–3 درجات","description":"خطأ في جزء واحد أو إشارة"},{"level":"درجة واحدة","description":"حساب الزمن فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان $\\frac{1}{2}$ في معادلة الإزاحة الرأسية","جعل $v_y$ موجبة","جمع المركّبتين جمعًا عدديًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-21T13:36:33.161Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $t = \sqrt{\frac{2h}{g}} = \sqrt{\frac{2(1.10)}{9.80}} = 0.474\ \text{s}$. (b) $v_x = \frac{x}{t} = \frac{0.500\ \text{m}}{0.474\ \text{s}} = 1.06\ \text{m/s}$. (c) لا يتغير زمن السقوط (0.474 s) لأنه يعتمد على الارتفاع والحركة الرأسية فقط، بينما تتضاعف المسافة الأفقية لتصبح 1.00 m لأن $x = v_x t$.', '["$t = 0.474\\ \\text{s}$","$v_x = 1.06\\ \\text{m/s}$","الزمن لا يتغير","المسافة الأفقية تتضاعف إلى 1.00 m"]'::jsonb, '["$t = \\sqrt{\\frac{2(1.10)}{9.80}} = 0.474\\ \\text{s}$","$v_x = \\frac{x}{t} = \\frac{0.500}{0.474} = 1.06\\ \\text{m/s}$","عند $2v_x$: $t$ نفسه، و$x = (2)(1.06)(0.474) = 1.00\\ \\text{m}$"]'::jsonb, '[{"element":"الزمن","marks":1},{"element":"السرعة","marks":1},{"element":"ثبات الزمن","marks":1},{"element":"تضاعف المسافة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"2–3 درجات","description":"الحسابان صحيحان والتحليل ناقص"},{"level":"درجة واحدة","description":"حساب الزمن فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال المسافة الأفقية في حساب الزمن","القول إن السرعة الأكبر تقلل زمن السقوط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-21T13:36:33.162Z"}'::jsonb),
('essay', 3, null::int, null, null, 'زمن السقوط: $t = \sqrt{\frac{2(40.0)}{9.80}} = 2.86\ \text{s}$. المسافة الأفقية: $x = (18.0)(2.86) = 51.4\ \text{m}$؛ وهي أكبر من 50.0 m، فتتجاوز الكرة الحافة البعيدة للحوض وتسقط خارجه. منتصف الحوض على بعد 40.0 m، فالسرعة المطلوبة $v_x = \frac{40.0\ \text{m}}{2.86\ \text{s}} = 14.0\ \text{m/s}$ (الزمن لا يتغير لأن الارتفاع نفسه).', '["$t = 2.86\\ \\text{s}$","$x = 51.4\\ \\text{m}$","المقارنة: $51.4 > 50.0$ فتتجاوز الحوض","$v_x = 14.0\\ \\text{m/s}$ للمنتصف"]'::jsonb, '["$t = \\sqrt{\\frac{2h}{g}} = \\sqrt{\\frac{2(40.0)}{9.80}} = 2.86\\ \\text{s}$","$x = v_x t = (18.0)(2.86) = 51.4\\ \\text{m}$","$51.4\\ \\text{m} > 50.0\\ \\text{m}$ ← خارج الحوض","$v_x = \\frac{40.0}{2.86} = 14.0\\ \\text{m/s}$"]'::jsonb, '[{"element":"الزمن","marks":1},{"element":"المسافة","marks":1},{"element":"الحكم","marks":1},{"element":"السرعة المقترحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحساب والحكم والاقتراح صحيحة"},{"level":"2–3 درجات","description":"حكم صحيح مع خطأ في الاقتراح"},{"level":"درجة واحدة","description":"حساب الزمن فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["مقارنة المسافة بقطر الحوض (20.0 m) بدل بعد حافته","تغيير الزمن عند تغيير السرعة الأفقية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.163Z"}'::jsonb)
