from (values
('mcq', 1, 'قُذفت كرة بزاوية فوق الأفق، ورُسم مخطط الحركة لحركتها الأفقية وحدها (صور على فترات زمنية متساوية مع متجهات السرعة الأفقية). أيّ الصفوف في الشكل الآتي يمثل هذه الحركة بإهمال مقاومة الهواء؟', null, '[{"src":"qimg/phys1/c6l1-o07-horiz-rows.svg","alt":"أربعة صفوف مرقمة من النقاط مع أسهم سرعة حمراء أفقية إلى اليمين، والصور على فترات زمنية متساوية. (1): المسافات بين النقاط تتناقص والأسهم تقصر تدريجيًا. (2): المسافات تتزايد والأسهم تطول تدريجيًا. (3): المسافات متساوية والأسهم متساوية الطول. (4): الأسهم تقصر حتى تنعدم عند نقطة في المنتصف ثم تطول من جديد، والمسافات تتغير تبعًا لذلك."}]'::jsonb, '["الصف (1)","الصف (2)","الصف (3)","الصف (4)"]'::jsonb, 'فهم', 'اختيار مخطط حركة', 'متوسط', 'الكتاب ص 164 — المقذوفات التي تُطلق بزاوية، الشكل 6-3'),
('mcq', 2, 'رُسم مخطط الحركة الرأسية لكرة قُذفت بزاوية فوق الأفق؛ نقاط الصعود في عمود (أسهمها إلى أعلى)، وبجانبها نقاط النزول في عمود آخر (أسهمها إلى أسفل)، والصور على فترات زمنية متساوية. أيّ المخططات في الشكل الآتي صحيح بإهمال مقاومة الهواء؟', null, '[{"src":"qimg/phys1/c6l1-o07-vert-cols.svg","alt":"أربعة مخططات مرقمة، في كل منها عمود نقاط صعود بأسهم حمراء إلى أعلى، وبجانبه عمود نقاط نزول بأسهم حمراء إلى أسفل. (1): نقاط متباعدة بمسافات متساوية وأسهم متساوية الطول صعودًا ونزولًا. (2): أسهم الصعود تقصر تدريجيًا حتى تنعدم عند القمة، وأسهم النزول قصيرة ومتساوية عند كل النقاط. (3): أسهم الصعود تطول كلما ارتفعت الكرة، وأسهم النزول تقصر كلما نزلت. (4): أسهم الصعود تقصر تدريجيًا والنقاط تتقارب حتى تنعدم السرعة عند القمة، وأسهم النزول تطول تدريجيًا، وعند كل ارتفاع يتساوى طول سهم الصعود وسهم النزول."}]'::jsonb, '["المخطط (4)","المخطط (1)","المخطط (2)","المخطط (3)"]'::jsonb, 'تحليل', 'اختيار مخطط حركة', 'صعب', 'الكتاب ص 164 — المقذوفات التي تُطلق بزاوية، الشكل 6-3'),
('mcq', 3, 'في مخطط الحركة الرأسية لمقذوف أُطلق بزاوية فوق الأفق، كيف تتغير المسافات بين الصور المتتالية (الملتقطة على فترات زمنية متساوية) في أثناء الصعود؟', null, null, '["تبقى متساوية","تتناقص تدريجيًا","تتزايد تدريجيًا","تنعدم من البداية"]'::jsonb, 'فهم', 'وصف مخطط الحركة الرأسية', 'سهل', 'الكتاب ص 164 — المقذوفات التي تُطلق بزاوية، الشكل 6-3'),
('mcq', 4, 'بمَ تشبه الحركة الأفقية لمقذوف أُطلق بزاوية فوق الأفق؟', null, null, '["حركة قرص ينزلق على جليد أملس بسرعة ثابتة","حركة جسم يسقط رأسيًا من السكون","حركة جسم يتباطأ أفقيًا تدريجيًا حتى يتوقف","حركة جسم يدور في مسار دائري منتظم"]'::jsonb, 'فهم', 'تشبيه الحركة', 'سهل', 'الكتاب ص 162–163 — «مثل حركة قرص مطاطي على جليد ناعم»'),
('mcq', 5, 'ترتفع كرة رُكلت بزاوية فوق الأفق وتتناقص سرعتها الرأسية حتى تنعدم، ثم تهبط بسرعة رأسية متزايدة. أيّ الحركات الآتية تماثل حركتها الرأسية تمامًا؟', null, null, '["حركة جسم يتحرك رأسيًا بسرعة ثابتة","حركة جسم يتحرك أفقيًا على سطح أملس","حركة جسم قُذف رأسيًا إلى أعلى ثم عاد","حركة جسم يسقط من السكون فقط"]'::jsonb, 'تذكر', 'تشبيه الحركة', 'سهل', 'الكتاب ص 163–164 — استراتيجيات حل المسألة'),
('mcq', 6, 'يبين الشكل الآتي جزءًا من مسار كرة قُذفت بزاوية، ورُسم عند ثلاث نقاط عليه متجها المركّبتين $\boldsymbol{v}_x$ و$\boldsymbol{v}_y$ (سهمان متصلان) وسهم ثالث متقطع. ماذا يمثل السهم المتقطع؟', null, '[{"src":"qimg/phys1/c6l1-o07-combined.svg","alt":"مسار منحنٍ متقطع لكرة قُذفت من الأرض بزاوية. عند نقطة الإطلاق ونقطتين أخريين على الجزء الصاعد رُسم سهم أحمر أفقي إلى اليمين (مكتوب عند الأول v_x) متساوي الطول عند النقاط الثلاث، وسهم أحمر رأسي إلى أعلى (مكتوب عند الأول v_y) يقصر من نقطة إلى التي تليها، وسهم أحمر متقطع مائل من النقطة نفسها إلى أعلى وإلى اليمين. مؤشر الاتجاهين الموجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, '["تسارع الكرة عند تلك النقطة من المسار","إزاحة الكرة منذ لحظة إطلاقها","المدى الأفقي الذي تقطعه الكرة","السرعة المتجهة الكلية المماسية للمسار"]'::jsonb, 'فهم', 'تفسير رسم', 'متوسط', 'الكتاب ص 163–164 — الشكلان 6-2b و6-3b'),
('mcq', 7, 'عند تمثيل حركة مقذوف أُطلق بزاوية بمخططين منفصلين (أفقي ورأسي)، أيّ مما يأتي يصف متجه التسارع في المخططين؟', null, null, '["في الأفقي $\\boldsymbol{a}_x$ في اتجاه الحركة، وفي الرأسي $\\boldsymbol{a}_y$ إلى أسفل","لا سهم في الأفقي ($\\boldsymbol{a}_x = 0$)، وفي الرأسي سهم $\\boldsymbol{a}_y$ إلى أسفل","في الأفقي $\\boldsymbol{a}_x = 0$، وفي الرأسي $\\boldsymbol{a}_y$ إلى أعلى في الصعود وإلى أسفل في النزول","في المخططين سهم تسارع مماسي للمسار يتغير اتجاهه من نقطة إلى أخرى"]'::jsonb, 'فهم', 'تمثيل التسارع', 'صعب', 'الكتاب ص 164 — المقذوفات التي تُطلق بزاوية، الشكل 6-3'),
('essay', 1, 'صف كيف ترسم مخططين منفصلين يوضحان الحركة الأفقية والحركة الرأسية لكرة رُكلت بزاوية فوق الأفق (بإهمال مقاومة الهواء)، مبيّنًا ما يُرسم في كل مخطط من نقاط ومتجهات.', null, null, null, 'تطبيق', 'وصف طريقة رسم', 'متوسط', 'الكتاب ص 164 — المقذوفات التي تُطلق بزاوية، الشكل 6-3'),
('essay', 2, 'يبين الشكل الآتي مخططين منفصلين لحركة مقذوف أُطلق بزاوية: صف أفقي من النقاط وعمود رأسي من النقاط. (a) ماذا يمثل كل مخطط؟ وماذا تدل عليه أطوال الأسهم في كل منهما؟ (b) لماذا كُتب $\boldsymbol{a}_x = 0$ عند المخطط الأفقي، بينما رُسم سهم $\boldsymbol{a}_y$ إلى أسفل عند المخطط الرأسي؟ (c) كيف نحصل من المخططين على السرعة المتجهة للمقذوف عند أيّ لحظة؟', null, '[{"src":"qimg/phys1/c6l1-o07-separate.svg","alt":"في الأعلى صف أفقي من تسع نقاط متساوية التباعد، عند كل منها سهم أحمر أفقي إلى اليمين بالطول نفسه، ومكتوب تحته v_x، وتحته بالبنفسجي a_x = 0. في اليسار عمود رأسي: نقاط صعود بأسهم حمراء إلى أعلى تقصر كلما ارتفعت حتى تنعدم عند القمة، وبجانبها نقاط نزول بأسهم حمراء إلى أسفل تطول كلما نزلت، ومكتوب بجانبه v_y. بجانب العمود سهم بنفسجي رأسي إلى أسفل مكتوب عنده a_y. وفي الأسفل مؤشر الاتجاهين الموجبين: +x إلى اليمين و+y إلى أعلى."}]'::jsonb, null, 'فهم', 'تفسير مخططين', 'متوسط', 'الكتاب ص 164 — المقذوفات التي تُطلق بزاوية، الشكل 6-3'),
('essay', 3, 'تقول طالبة: «الحركة الرأسية لكرة قُذفت بزاوية فوق الأفق تماثل تمامًا حركة كرة قُذفت رأسيًا إلى أعلى بالمركّبة الرأسية نفسها لسرعتها الابتدائية، وحركتها الأفقية تماثل تمامًا حركة قرص ينزلق على جليد أملس بالمركّبة الأفقية نفسها». بإهمال مقاومة الهواء: (a) حلّل كل جزء من العبارة: هل هو صحيح؟ ولماذا؟ (b) إذا انطلقت الأجسام الثلاثة (الكرة المقذوفة بزاوية، والكرة المقذوفة رأسيًا، والقرص) من النقطة نفسها في اللحظة نفسها، فكيف يقارَن موقع الكرة المقذوفة بزاوية بموقعي الجسمين الآخرين في أيّ لحظة لاحقة؟ (c) استنتج كيف يُبنى المسار المنحني للمقذوف من مخططي الحركة الأفقية والرأسية المنفصلين.', null, null, null, 'تحليل', 'حساب وتمثيل', 'صعب', 'الكتاب ص 162–164 — استقلالية الحركة في بعدين والمقذوفات التي تطلق بزاوية (الشكلان 6-2 و6-3)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L1-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الحركة الأفقية للمقذوف منتظمة: المسافات بين الصور المتتالية متساوية، ومتجهات السرعة الأفقية $\boldsymbol{v}_x$ متساوية الطول، وهذا هو الصف (3).', '["الصف (1) يمثل سرعة أفقية متناقصة، ولا توجد قوة أفقية تبطئ المقذوف.","الصف (2) يمثل سرعة أفقية متزايدة، ولا توجد قوة أفقية تسرّعه.","","الصف (4) يجعل السرعة الأفقية صفرًا في منتصف الحركة (عند القمة)، والذي ينعدم عند القمة هو السرعة الرأسية لا الأفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-21T13:36:33.164Z"}'::jsonb),
('mcq', 2, 0, 'في الصعود تتناقص السرعة الرأسية بانتظام فتقصر الأسهم وتتقارب النقاط حتى تنعدم السرعة الرأسية عند القمة، ثم في النزول تتزايد بانتظام إلى أسفل، ويتساوى مقدار السرعة الرأسية صعودًا ونزولًا عند كل ارتفاع؛ وهذا هو المخطط (4).', '["","المخطط (1) يجعل السرعة الرأسية ثابتة المقدار، والجاذبية تغيّرها بانتظام.","المخطط (2) صحيح في الصعود لكنه يجعل سرعة النزول صغيرة ثابتة، والسرعة الرأسية تتزايد في أثناء النزول.","المخطط (3) يجعل السرعة الرأسية تزداد في أثناء الصعود، والجاذبية المتجهة إلى أسفل تُبطئ الصعود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-21T13:36:33.164Z"}'::jsonb),
('mcq', 3, 1, 'في الصعود تتناقص السرعة الرأسية بانتظام بسبب الجاذبية، فيقطع الجسم مسافات رأسية أصغر فأصغر في الفترات المتساوية حتى يصل إلى أقصى ارتفاع.', '["المسافات المتساوية تعني سرعة رأسية ثابتة، وهذا يحدث في الحركة الأفقية لا الرأسية.","","المسافات المتزايدة تمثل النزول (السقوط بسرعة متزايدة)، لا الصعود.","لو انعدمت المسافات لما ارتفع الجسم، وهو يرتفع بسرعته الرأسية الابتدائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.165Z"}'::jsonb),
('mcq', 4, 0, 'لا قوة أفقية تؤثر في المقذوف، فحركته الأفقية تشبه تمامًا حركة جسم يتحرك أفقيًا بسرعة متجهة ثابتة، مثل قرص مطاطي ينزلق على جليد ناعم.', '["","السقوط من السكون حركة رأسية، والمطلوب الحركة الأفقية.","التباطؤ الأفقي يحتاج إلى قوة أفقية معيقة، ولا توجد عند إهمال مقاومة الهواء.","الحركة الدائرية تتطلب قوة مركزية، والمقذوف لا يدور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.165Z"}'::jsonb),
('mcq', 5, 2, 'الحركة الرأسية للمقذوف هي نفسها حركة جسم قُذف رأسيًا إلى أعلى؛ إذ تتناقص سرعته الرأسية حتى تنعدم عند أقصى ارتفاع، ثم يسقط بسرعة متزايدة، بتسارع $g$ إلى أسفل.', '["السرعة الرأسية لا تكون ثابتة؛ فالجاذبية تغيرها بانتظام.","هذا وصف الحركة الأفقية لا الرأسية.","","المقذوف بزاوية له سرعة رأسية ابتدائية إلى أعلى، فلا تشبه حركته الرأسية السقوط من السكون (وهذا يصح للمقذوف أفقيًا)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-21T13:36:33.166Z"}'::jsonb),
('mcq', 6, 3, 'السهم المتقطع ناتج الجمع الاتجاهي للمركّبتين $\boldsymbol{v}_x$ و$\boldsymbol{v}_y$، أي السرعة المتجهة الكلية للكرة عند تلك النقطة، ويكون مماسيًا للمسار.', '["التسارع رأسي إلى أسفل دائمًا ($\\boldsymbol{g}$)، والسهم المتقطع مائل في اتجاه الحركة.","الإزاحة تُرسم من نقطة الإطلاق إلى موقع الكرة، لا من موقع الكرة في اتجاه حركتها.","المدى الأفقي مسافة أفقية على مستوى الإطلاق، لا سهم مائل عند كل نقطة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-21T13:36:33.166Z"}'::jsonb),
('mcq', 7, 1, 'لا تسارع أفقيًا ($\boldsymbol{a}_x = 0$) فلا يُرسم سهم تسارع في المخطط الأفقي، أما في المخطط الرأسي فيُرسم سهم تسارع واحد $\boldsymbol{a}_y$ رأسيًا إلى أسفل؛ لأن التسارع ثابت ($\boldsymbol{g}$) طوال الصعود والنزول.', '["لا توجد قوة أفقية، فلا تسارع أفقي في اتجاه الحركة.","","التسارع الرأسي إلى أسفل في الصعود والنزول؛ ففي الصعود تتناقص السرعة لأن التسارع يعاكسها.","التسارع رأسي دائمًا، ولا يكون مماسيًا للمسار؛ فالسرعة هي المماسية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-21T13:36:33.167Z"}'::jsonb),
('essay', 1, null::int, null, null, 'أختار نظام محاور: x أفقي و+y رأسي إلى أعلى. (1) المخطط الأفقي: أرسم صفًا من النقاط تمثل مواقع الكرة الأفقية على فترات زمنية متساوية، والمسافات بينها متساوية، وعند كل نقطة سهم أحمر $\boldsymbol{v}_x$ أفقي بالطول نفسه، وأكتب $\boldsymbol{a}_x = 0$. (2) المخطط الرأسي: أرسم عمود نقاط للصعود تتقارب كلما ارتفعت الكرة وأسهمها الحمراء $\boldsymbol{v}_y$ إلى أعلى تقصر حتى تنعدم عند القمة، ثم عمود نقاط للنزول تتباعد وأسهمها إلى أسفل تطول، بحيث يتساوى مقدار السرعة الرأسية عند الارتفاع نفسه صعودًا ونزولًا، وأرسم بجانبه سهمًا بنفسجيًا واحدًا $\boldsymbol{a}_y$ رأسيًا إلى أسفل.', '["نظام محاور x أفقي وy رأسي","الأفقي: نقاط متساوية التباعد وأسهم $\\boldsymbol{v}_x$ متساوية، و$\\boldsymbol{a}_x = 0$","الرأسي: أسهم $\\boldsymbol{v}_y$ تقصر في الصعود حتى الصفر ثم تطول في النزول","سهم تسارع واحد $\\boldsymbol{a}_y$ إلى أسفل"]'::jsonb, '[]'::jsonb, '[{"element":"المحاور","marks":1},{"element":"المخطط الأفقي","marks":1},{"element":"المخطط الرأسي","marks":1},{"element":"التسارع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف كامل للمخططين والتسارع"},{"level":"2–3 درجات","description":"مخطط صحيح والآخر ناقص"},{"level":"درجة واحدة","description":"وصف عام دون تفاصيل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم أسهم أفقية متناقصة","رسم سهم التسارع إلى أعلى في أثناء الصعود","جعل السرعة الأفقية صفرًا عند القمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.167Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) الصف الأفقي يمثل الحركة الأفقية: أسهم $\boldsymbol{v}_x$ متساوية والمسافات متساوية، أي سرعة أفقية ثابتة. العمود الرأسي يمثل الحركة الرأسية: أسهم $\boldsymbol{v}_y$ إلى أعلى تقصر في الصعود حتى تنعدم عند أقصى ارتفاع، ثم أسهم إلى أسفل تطول في النزول، أي سرعة رأسية تتغير بانتظام. (b) لا توجد قوة أفقية فلا تسارع أفقي ($\boldsymbol{a}_x = 0$)، أما الجاذبية الأرضية فتعطي تسارعًا ثابتًا رأسيًا إلى أسفل ($\boldsymbol{a}_y = -\boldsymbol{g}$) في الصعود والنزول. (c) نجمع متجهي $\boldsymbol{v}_x$ و$\boldsymbol{v}_y$ في اللحظة نفسها جمعًا اتجاهيًا، فينتج متجه السرعة الكلية المماسي للمسار؛ لأن الحركتين تحدثان في الزمن نفسه.', '["الصف: حركة أفقية بسرعة ثابتة","العمود: سرعة رأسية تتناقص صعودًا وتتزايد نزولًا","سبب $\\boldsymbol{a}_x = 0$ و$\\boldsymbol{a}_y$ إلى أسفل","الجمع الاتجاهي في اللحظة نفسها يعطي السرعة الكلية"]'::jsonb, '[]'::jsonb, '[{"element":"المخطط الأفقي","marks":1},{"element":"المخطط الرأسي","marks":1},{"element":"تفسير التسارعين","marks":1},{"element":"الجمع الاتجاهي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"2–3 درجات","description":"وصف المخططين صحيح مع نقص في التفسير أو الجمع"},{"level":"درجة واحدة","description":"وصف أحد المخططين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الجمع العددي للمركّبتين","القول إن التسارع الرأسي يعكس اتجاهه عند القمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-21T13:36:33.168Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) الجزءان صحيحان. الحركة الرأسية: القوة الوحيدة المؤثرة في المقذوف هي الجاذبية الأرضية وهي رأسية، فيكون تسارعه الرأسي $\boldsymbol{a}_y = -\boldsymbol{g}$ كالكرة المقذوفة رأسيًا تمامًا، ومع تساوي السرعة الرأسية الابتدائية تتطابق الحركتان الرأسيتان (تتناقص السرعة الرأسية حتى تنعدم عند أقصى ارتفاع ثم تتزايد إلى أسفل). الحركة الأفقية: لا توجد قوة أفقية فـ $\boldsymbol{a}_x = 0$، فيتحرك المقذوف أفقيًا بسرعة ثابتة كالقرص على الجليد الأملس. (b) لأن الحركتين مستقلتان وتحدثان في الزمن نفسه، تكون الكرة المقذوفة بزاوية في كل لحظة على الارتفاع نفسه للكرة المقذوفة رأسيًا، وعلى البعد الأفقي نفسه للقرص. (c) نأخذ عند كل لحظة الموقع الأفقي من المخطط الأفقي والموقع الرأسي من المخطط الرأسي فنحصل على موقع المقذوف، ونجمع $\boldsymbol{v}_x$ و$\boldsymbol{v}_y$ جمعًا اتجاهيًا فنحصل على سرعته المتجهة المماسية للمسار؛ وبوصل المواقع المتتالية نحصل على مسار على شكل قطع مكافئ، لأن السرعة الأفقية الثابتة والتسارع الرأسي المنتظم ينتجان معًا هذا الشكل.', '["الجزء الرأسي صحيح: الجاذبية وحدها رأسية فالتسارع الرأسي $\\boldsymbol{g}$ إلى أسفل كالمقذوف رأسيًا","الجزء الأفقي صحيح: لا قوة أفقية فـ $\\boldsymbol{a}_x = 0$ والسرعة الأفقية ثابتة","في كل لحظة: ارتفاع المقذوف = ارتفاع الكرة الرأسية، وبعده الأفقي = بعد القرص","بناء المسار بجمع الموقعين (والسرعتين اتجاهيًا) في اللحظة نفسها فينتج قطع مكافئ"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل الجزء الرأسي","marks":1},{"element":"تحليل الجزء الأفقي","marks":1},{"element":"مقارنة المواقع","marks":1},{"element":"بناء المسار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحليل الجزأين ومقارنة المواقع وبناء المسار صحيحة"},{"level":"2–3 درجات","description":"تحليل الجزأين صحيح مع نقص في المقارنة أو في بناء المسار"},{"level":"درجة واحدة","description":"تحليل صحيح لجزء واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الحركة الرأسية للمقذوف أبطأ بسبب حركته الأفقية","جمع السرعتين جمعًا عدديًا","القول إن القرص والمقذوف لا يتطابقان أفقيًا لأن المقذوف «يرتفع»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-21T13:36:33.169Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
