from (values
('mcq', 1, 'أيّ مما يأتي مثال على مقذوف أُطلق بزاوية فوق الأفق؟', null, null, '["حجر سقط من السكون من أعلى بناية","قذيفة مدفع أُطلقت في اتجاه مائل إلى أعلى","كرة تدحرجت عن حافة طاولة أفقية","سيارة تتحرك على منعطف دائري"]'::jsonb, 'تذكر', 'تعرّف مثال', 'سهل', 'الكتاب ص 180 — الشكل 6-11 (قذيفة مدفع)'),
('mcq', 2, 'ضفدع يقفز من الأرض إلى ورقة نبات أمامه. كيف تُصنَّف حركته في الهواء؟', null, null, '["حركة دائرية منتظمة","مقذوف أُطلق أفقيًا","سقوط حر من السكون","مقذوف أُطلق بزاوية"]'::jsonb, 'تذكر', 'تصنيف مثال', 'سهل', 'الكتاب ص 161 — «ضفدعًا يقفز»'),
('mcq', 3, 'يقفز لاعب في مسابقة الوثب الطويل. أيّ عبارة تصف حركته في الهواء بإهمال مقاومة الهواء؟', null, null, '["مقذوف أُطلق أفقيًا؛ لأنه يركض أفقيًا قبل القفز","مقذوف بزاوية؛ لأن لسرعته لحظة المغادرة مركّبتين","ليس مقذوفًا؛ لأنه يستعمل عضلاته في القفز","سقوط حر رأسي؛ لأنه يعود في النهاية إلى الأرض"]'::jsonb, 'فهم', 'تصنيف مثال', 'متوسط', 'الكتاب ص 180 — التقويم 35 (الوثب الطويل)'),
('mcq', 4, 'أيّ مما يأتي ليس مثالًا على مقذوف أُطلق بزاوية فوق الأفق؟', null, null, '["سهم أُطلق في اتجاه يصنع زاوية $30.0^\\circ$ مع الأفقي","تفاحة قُذفت بزاوية $78^\\circ$ مع الأفقي","رزمة أُلقيت من طائرة تطير أفقيًا بسرعة ثابتة","كرة ركلها حارس المرمى بزاوية $45^\\circ$ مع الأفقي"]'::jsonb, 'تذكر', 'تمييز مثال', 'متوسط', 'الكتاب ص 180–181، 183 — التقويم 29، 41، الاختبار المقنن 6'),
('mcq', 5, 'يصوّب لاعب كرة السلة الكرة نحو السلة فتنطلق من يديه إلى أعلى وإلى الأمام. ما الذي يجعل هذه الرمية مثالًا على مقذوف أُطلق بزاوية؟', null, null, '["أن للسرعة الابتدائية مركّبتين أفقية ورأسية معًا","أن الكرة تصل في النهاية إلى السلة","أن كتلة الكرة صغيرة مقارنة باللاعب","أن للسرعة الابتدائية مركّبة أفقية فقط"]'::jsonb, 'فهم', 'تبرير التصنيف', 'متوسط', 'الكتاب ص 164 — «يكون لسرعته الابتدائية مركّبتان»'),
('mcq', 6, 'يبين الشكل الآتي أربع حالات لأجسام تتحرك في الهواء، والسهم الأحمر في كل حالة يمثل اتجاه السرعة الابتدائية. أيّ الحالات يمثل مقذوفًا أُطلق بزاوية فوق الأفق؟', null, '[{"src":"qimg/phys1/c6l1-o08-paths4.svg","alt":"أربع حالات مرقمة. (1): كرة على حافة طاولة وسهم أحمر أفقي إلى اليمين، ومسار منحنٍ يبدأ أفقيًا من حافة الطاولة ويهبط إلى الأرض. (2): كرة بجانب رف مرتفع، ومسارها خط رأسي إلى الأرض، ولا يوجد سهم سرعة. (3): كرة على الأرض وسهم أحمر مائل إلى أعلى وإلى اليمين، ومسارها منحنٍ يرتفع ثم يهبط إلى الأرض. (4): كرة على الأرض وسهم أحمر رأسي إلى أعلى، ومسارها خط رأسي إلى أعلى ثم خط رأسي متقطع إلى أسفل."}]'::jsonb, '["الحالة (1)","الحالة (2)","الحالة (4)","الحالة (3)"]'::jsonb, 'فهم', 'تعرّف من شكل', 'متوسط', 'الكتاب ص 161، 164–166، 181 — أمثلة المقذوفات المطلقة بزاوية'),
('mcq', 7, 'أيّ مجموعة مما يأتي كل ما فيها أمثلة على مقذوفات تُطلق بزاوية فوق الأفق؟', null, null, '["رزمة أُلقيت من طائرة تطير أفقيًا، وسهم أُطلق بزاوية $30.0^\\circ$، وضفدع يقفز","كرة سقطت من السكون، وكرة قدم رُكلت إلى أعلى، وسهم أُطلق بزاوية $30.0^\\circ$","ضفدع يقفز، وكرة قدم رُكلت إلى أعلى، وسهم أُطلق بزاوية $30.0^\\circ$","طائرة تقلع ومحركاتها تعمل، وضفدع يقفز، وكرة قدم رُكلت إلى أعلى"]'::jsonb, 'تذكر', 'تقويم مثال', 'متوسط', 'الكتاب ص 161، 181 — أمثلة على المقذوفات (الضفدع، كرة القدم، السهم)'),
('essay', 1, 'اذكر ثلاثة أمثلة من الرياضة أو الحياة اليومية على مقذوفات تُطلق بزاوية فوق الأفق.', null, null, null, 'تذكر', 'ذكر أمثلة', 'سهل', 'الكتاب ص 161، 164–166، 181 — أمثلة المقذوفات المطلقة بزاوية'),
('essay', 2, 'صنّف كل حالة مما يأتي إلى «مقذوف أُطلق بزاوية» أو «مقذوف أُطلق أفقيًا» أو «ليس مقذوفًا»، مع ذكر السبب: (a) سهم أُطلق بزاوية $30.0^\circ$ فوق الأفق. (b) مفاتيح أُلقيت أفقيًا من سطح بناية. (c) لاعب في أثناء الوثب الطويل. (d) طائرة تقلع ومحركاتها تعمل. (e) تفاحة قُذفت بزاوية $78^\circ$ فوق الأفق.', null, null, null, 'فهم', 'تصنيف مع تبرير', 'صعب', 'الكتاب ص 161، 164–166، 181 — أمثلة المقذوفات المطلقة بزاوية'),
('essay', 3, 'اذكر مثالين على مقذوفات تُطلق بزاوية فوق الأفق، أحدهما من الرياضة والآخر من عالم الكائنات الحية، ومثالًا على مقذوف يُطلق أفقيًا، ثم بيّن الفرق بين النوعين من حيث اتجاه السرعة الابتدائية.', null, null, null, 'فهم', 'تحليل مثال', 'متوسط', 'الكتاب ص 161، 164، 181 — أمثلة على المقذوفات المطلقة بزاوية والمطلقة أفقيًا')
