('mcq', 1, 1, 'قذيفة المدفع التي تُطلق في اتجاه مائل فوق الأفق لسرعتها الابتدائية مركّبتان أفقية ورأسية، فهي مقذوف مطلق بزاوية.', '["الحجر الساقط من السكون ليس له سرعة أفقية، فهو سقوط حر رأسي.","","الكرة المتدحرجة عن الطاولة تبدأ بسرعة أفقية فقط، فهي مقذوف أُطلق أفقيًا.","السيارة على المنعطف تتحرك على الطريق ولم تُطلق في الهواء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-11-21T13:36:33.170Z"}'::jsonb),
('mcq', 2, 3, 'ينطلق الضفدع من الأرض بسرعة ابتدائية لها مركّبة أفقية ومركّبة رأسية إلى أعلى، فيتحرك في الهواء في مسار قطع مكافئ، وهو مقذوف أُطلق بزاوية.', '["الضفدع لا يدور حول مركز بسرعة ثابتة المقدار.","المقذوف الأفقي يبدأ بسرعة أفقية فقط من مكان مرتفع، والضفدع ينطلق إلى أعلى أيضًا.","الضفدع ينطلق بسرعة ابتدائية، فلا يبدأ من السكون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-21T13:36:33.170Z"}'::jsonb),
('mcq', 3, 1, 'هو مقذوف بزاوية لأن لسرعته لحظة المغادرة مركّبتين: يغادر اللاعب الأرض بسرعة ابتدائية لها مركّبة أفقية (من الركض) ومركّبة رأسية إلى أعلى (من الدفع بقدمه)، ثم لا تؤثر فيه في الهواء إلا الجاذبية؛ فهو مقذوف أُطلق بزاوية.', '["الركض الأفقي يحدث قبل القفز؛ ولحظة المغادرة تكون للسرعة مركّبة رأسية إلى أعلى أيضًا.","","قوة العضلات تؤثر في أثناء الدفع على الأرض فقط، وبعد مغادرتها يتحرك اللاعب مقذوفًا.","العودة إلى الأرض لا تجعل الحركة سقوطًا حرًا رأسيًا؛ فللاعب سرعة أفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-21T13:36:33.170Z"}'::jsonb),
('mcq', 4, 2, 'الرزمة الملقاة من طائرة تطير أفقيًا تبدأ حركتها بسرعة أفقية فقط (سرعة الطائرة) دون مركّبة رأسية، فهي مقذوف أُطلق أفقيًا لا بزاوية.', '["السهم أُطلق بزاوية فوق الأفق، فهو مقذوف مطلق بزاوية.","التفاحة قُذفت بزاوية فوق الأفق، فهي مقذوف مطلق بزاوية.","","الكرة رُكلت بزاوية فوق الأفق، فهي مقذوف مطلق بزاوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-11-21T13:36:33.171Z"}'::jsonb),
('mcq', 5, 0, 'المقذوف المطلق بزاوية تكون لسرعته الابتدائية مركّبتان: أفقية ورأسية، وهذا ما يحدث في رمية كرة السلة إلى أعلى وإلى الأمام.', '["","الوصول إلى الهدف لا يحدد نوع الإطلاق.","الكتلة لا تحدد نوع الإطلاق ولا شكل المسار.","المركّبة الأفقية وحدها تعني إطلاقًا أفقيًا، والكرة انطلقت إلى أعلى أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-21T13:36:33.171Z"}'::jsonb),
('mcq', 6, 3, 'في الحالة (3) ينطلق الجسم من الأرض بسرعة ابتدائية مائلة إلى أعلى وإلى الأمام، فيتحرك في قطع مكافئ كامل؛ وهذا هو المقذوف المطلق بزاوية.', '["الحالة (1) تمثل مقذوفًا أُطلق أفقيًا عن حافة طاولة؛ فسرعته الابتدائية أفقية فقط.","الحالة (2) تمثل سقوطًا حرًا من السكون، فلا سرعة ابتدائية.","الحالة (4) تمثل جسمًا قُذف رأسيًا إلى أعلى، فسرعته الابتدائية رأسية فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-21T13:36:33.171Z"}'::jsonb),
('mcq', 7, 2, 'الضفدع القافز وكرة القدم المركولة إلى أعلى والسهم المطلق بزاوية $30.0^\circ$ كلها أجسام أُطلقت في الهواء بسرعة ابتدائية لها مركّبتان أفقية ورأسية، فهي مقذوفات تُطلق بزاوية.', '["الرزمة الملقاة من طائرة تطير أفقيًا تبدأ بسرعة أفقية فقط، فهي مقذوف أُطلق أفقيًا لا بزاوية.","الكرة الساقطة من السكون ليست لها سرعة ابتدائية، فلا تُعدّ مقذوفًا أُطلق بزاوية.","","الطائرة التي تقلع تدفعها قوة محركاتها باستمرار، فلا تُعدّ مقذوفًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-21T13:36:33.172Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من الأمثلة: كرة قدم يركلها اللاعب من الأرض إلى أعلى وإلى الأمام، وسهم يطلقه رامٍ في اتجاه مائل إلى أعلى، وكرة سلة يصوّبها اللاعب نحو السلة، ولاعب الوثب الطويل في أثناء قفزته، وقذيفة مدفع مائل، وضفدع يقفز.', '["مثال أول صحيح","مثال ثانٍ صحيح","مثال ثالث صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1},{"element":"المثال الثالث","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاثة أمثلة صحيحة"},{"level":"درجتان","description":"مثالان صحيحان"},{"level":"درجة واحدة","description":"مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر مقذوف أفقي كالكرة المتدحرجة عن طاولة","ذكر أجسام تدفعها محركات كالطائرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-21T13:36:33.172Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) مقذوف بزاوية: لسرعته الابتدائية مركّبتان أفقية ورأسية. (b) مقذوف أفقي: سرعتها الابتدائية أفقية فقط. (c) مقذوف بزاوية: يغادر الأرض بسرعة إلى الأمام وإلى أعلى. (d) ليس مقذوفًا: تدفعها قوة المحركات باستمرار. (e) مقذوف بزاوية: لسرعتها الابتدائية مركّبة أفقية (صغيرة) ورأسية.', '["(a) بزاوية","(b) أفقي","(c) بزاوية","(d) ليس مقذوفًا","(e) بزاوية"]'::jsonb, '[]'::jsonb, '[{"element":"a","marks":1},{"element":"b","marks":1},{"element":"c","marks":1},{"element":"d","marks":1},{"element":"e","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف الحالات الخمس صحيحًا مع الأسباب"},{"level":"3–4 درجات","description":"خطأ في حالة أو حالتين"},{"level":"1–2 درجة","description":"تصنيف صحيح لحالة أو حالتين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ التفاحة المقذوفة بزاوية كبيرة مقذوفًا رأسيًا","عدّ المفاتيح الملقاة أفقيًا مقذوفًا بزاوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-21T13:36:33.173Z"}'::jsonb),
('essay', 3, null::int, null, null, 'من الرياضة: كرة قدم يركلها اللاعب إلى أعلى وإلى الأمام (أو سهم يُطلق بزاوية، أو لاعب الوثب الطويل). من الكائنات الحية: ضفدع يقفز. مثال على مقذوف أُطلق أفقيًا: مفاتيح تُلقى أفقيًا من سطح بناية (أو كرة تتدحرج عن حافة طاولة). الفرق: المقذوف المطلق بزاوية تكون لسرعته الابتدائية مركّبتان أفقية ورأسية معًا، أما المقذوف المطلق أفقيًا فسرعته الابتدائية أفقية فقط (مركّبتها الرأسية صفر).', '["مثال رياضي صحيح على مقذوف بزاوية","مثال صحيح من الكائنات الحية (كالضفدع القافز)","مثال صحيح على مقذوف أفقي","الفرق: مركّبتان للسرعة الابتدائية مقابل مركّبة أفقية فقط"]'::jsonb, '[]'::jsonb, '[{"element":"المثال الرياضي","marks":1},{"element":"مثال الكائنات الحية","marks":1},{"element":"مثال المقذوف الأفقي","marks":1},{"element":"الفرق في اتجاه السرعة الابتدائية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأمثلة الثلاثة صحيحة مع بيان الفرق"},{"level":"2–3 درجات","description":"مثالان أو ثلاثة صحيحة دون بيان الفرق، أو مع فرق ناقص"},{"level":"درجة واحدة","description":"مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر كرة تتدحرج عن طاولة مثالًا على مقذوف بزاوية","ذكر طائرة أو صاروخ محركه يعمل مثالًا على مقذوف","القول إن المقذوف الأفقي له سرعة ابتدائية رأسية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.173Z"}'::jsonb)
