from (values
('mcq', 1, 3, 'لا قوة أفقية فتبقى $\boldsymbol{v}_x$ ثابتة، بينما تغيّر الجاذبية $\boldsymbol{v}_y$ بانتظام (تتناقص في الصعود، وتنعدم عند القمة، وتتزايد إلى أسفل في النزول).', '["لو ثبتت المركّبتان لتحرك المقذوف في خط مستقيم، والجاذبية تغيّر المركّبة الرأسية.","هذا عكس الصحيح؛ فالتسارع رأسي فقط.","المركّبة الأفقية لا تتغير لعدم وجود قوة أفقية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.174Z"}'::jsonb),
('mcq', 2, 0, 'التسارع هو تسارع الجاذبية $\boldsymbol{g}$ رأسيًا إلى أسفل عند كل نقطة من المسار، ولا مركّبة أفقية له: $a_x = 0$، و$a_y = -g = -9.80\ \text{m/s}^2$ لأن +y إلى أعلى.', '["","التسارع ليس أفقيًا؛ فالقوة الوحيدة (الوزن) رأسية.","أُهملت الإشارة؛ فالتسارع إلى أسفل و+y إلى أعلى، فيكون $a_y$ سالبًا.","التسارع ليس له مركّبة أفقية؛ ولو كان كذلك لتناقصت السرعة الأفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-21T13:36:33.175Z"}'::jsonb),
('mcq', 3, 3, '$v_{yi} = v_i\sin\theta_i = (15.0\ \text{m/s})\sin 40.0^\circ = 9.64\ \text{m/s}$، وهي موجبة لأنها إلى أعلى.', '["استُعمل $\\cos\\theta_i$ بدل $\\sin\\theta_i$؛ فهذه المركّبة الأفقية $v_x$.","هذا مقدار السرعة الكلية، لا مركّبتها الرأسية.","أُعطيت المركّبة إشارة سالبة، مع أن الكرة تنطلق إلى أعلى و+y إلى أعلى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.175Z"}'::jsonb),
('mcq', 4, 1, '$v_y = v_{yi} + a_y t = 9.64\ \text{m/s} + (-9.80\ \text{m/s}^2)(0.50\ \text{s}) = 4.74\ \text{m/s}$، أي ما زالت الكرة صاعدة لكن بسرعة رأسية أقل.', '["أُخذ $a_y = +9.80\\ \\text{m/s}^2$ فزادت السرعة الرأسية، مع أن التسارع إلى أسفل.","","افتُرض أن المركّبة الرأسية ثابتة كالأفقية، والجاذبية تغيرها.","حُسب التغير $gt$ وحده ونُسيت إضافة $v_{yi}$ إليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.176Z"}'::jsonb),
('mcq', 5, 2, 'المركّبة الأفقية ثابتة طوال الحركة، فتبقى في اتجاه $+x$ كما عند الإطلاق؛ أما عند $C$ فالكرة نازلة، فتكون $\boldsymbol{v}_y$ في اتجاه $-y$ (إلى أسفل).', '["هذا وصف النقطة $A$ (الصعود)، أما عند $C$ فالكرة نازلة.","الكرة لا تعود إلى الخلف؛ فالمركّبة الأفقية ثابتة في اتجاه $+x$.","","المركّبة الأفقية لا تنعدم؛ فلا قوة أفقية تغيّرها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-21T13:36:33.176Z"}'::jsonb),
('mcq', 6, 0, 'تسارع المقذوف هو $\boldsymbol{g}$ عند كل نقطة: رأسي إلى أسفل وبالمقدار نفسه، بلا مركّبة أفقية ($\boldsymbol{a}_x = 0$)، حتى عند أعلى نقطة؛ وهذا هو الرسم (1).', '["","الرسم (2) يجعل التسارع مماسيًا للمسار، وهذا اتجاه السرعة لا التسارع.","الرسم (3) يعطي التسارع مركّبة أفقية إلى الأمام، والتسارع رأسي فقط ($\\boldsymbol{a}_x = 0$).","الرسم (4) يجعل التسارع إلى أعلى في الصعود وصفرًا عند القمة، والتسارع إلى أسفل دائمًا ولا ينعدم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-21T13:36:33.176Z"}'::jsonb),
('mcq', 7, 1, 'المركّبة الأفقية $\boldsymbol{v}_x$ ثابتة لانعدام القوة الأفقية، والتسارع $\boldsymbol{a}$ ثابت يساوي $\boldsymbol{g}$ إلى أسفل لأن الوزن ثابت؛ أما $\boldsymbol{v}_y$ ومقدار السرعة فيتغيران.', '["$\\boldsymbol{v}_y$ تتغير بانتظام بسبب التسارع الرأسي.","","$\\boldsymbol{v}_y$ ليست ثابتة؛ فهي تتناقص صعودًا وتتزايد نزولًا.","مقدار السرعة يتغير لأن المركّبة الرأسية تتغير؛ فهو أصغر ما يمكن عند القمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-21T13:36:33.177Z"}'::jsonb),
('essay', 1, null::int, null, null, '$\boldsymbol{v}_x$ ثابتة طوال الحركة لأنه لا توجد قوة أفقية. $\boldsymbol{v}_y$ تبدأ موجبة (إلى أعلى) وتتناقص بانتظام حتى تنعدم عند أقصى ارتفاع، ثم تصبح سالبة (إلى أسفل) ويتزايد مقدارها، بسبب الجاذبية. $\boldsymbol{a}_x = 0$ لانعدام القوة الأفقية. $\boldsymbol{a}_y = -\boldsymbol{g}$ ثابت ($-9.80\ \text{m/s}^2$) عند كل نقطة بما فيها أعلى نقطة، لأن الوزن هو القوة الوحيدة وهو رأسي إلى أسفل؛ فتسارع المقذوف رأسي فقط ولا مركّبة أفقية له.', '["$\\boldsymbol{v}_x$ ثابتة: لا قوة أفقية","$\\boldsymbol{v}_y$ تتناقص ثم تنعدم عند القمة ثم تتزايد إلى أسفل","$\\boldsymbol{a}_x = 0$","$\\boldsymbol{a}_y = -\\boldsymbol{g}$ ثابت عند كل نقطة"]'::jsonb, '[]'::jsonb, '[{"element":"$\\boldsymbol{v}_x$","marks":1},{"element":"$\\boldsymbol{v}_y$","marks":1},{"element":"$\\boldsymbol{a}_x$","marks":1},{"element":"$\\boldsymbol{a}_y$","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف الكميات الأربع مع أسبابها"},{"level":"2–3 درجات","description":"وصف صحيح لكميتين أو ثلاث"},{"level":"درجة واحدة","description":"وصف كمية واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التسارع ينعدم عند القمة","إعطاء التسارع مركّبة أفقية","القول إن السرعة الكلية تنعدم عند القمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.177Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $v_x = v_i\cos\theta_i = (18.0)\cos 35.0^\circ = 14.7\ \text{m/s}$، و$v_{yi} = v_i\sin\theta_i = (18.0)\sin 35.0^\circ = 10.3\ \text{m/s}$. (b) $v_y = v_{yi} + a_y t = 10.3 - 9.80t$: عند 0.80 s: $v_y = 2.5\ \text{m/s}$؛ وعند 1.60 s: $v_y = -5.4\ \text{m/s}$. (c) القيمة الموجبة عند 0.80 s تعني أن الكرة ما زالت صاعدة، والسالبة عند 1.60 s تعني أنها تجاوزت أقصى ارتفاع وأصبحت نازلة. أما $v_x$ فتبقى 14.7 m/s عند اللحظتين لأن $\boldsymbol{a}_x = 0$.', '["$v_x = 14.7\\ \\text{m/s}$ و$v_{yi} = 10.3\\ \\text{m/s}$","$v_y = 2.5\\ \\text{m/s}$ عند 0.80 s","$v_y = -5.4\\ \\text{m/s}$ عند 1.60 s","تفسير الإشارتين وثبات $v_x$"]'::jsonb, '["$v_x = 18.0\\cos 35.0^\\circ = 14.7\\ \\text{m/s}$","$v_{yi} = 18.0\\sin 35.0^\\circ = 10.3\\ \\text{m/s}$","$v_y = 10.3 - (9.80)(0.80) = 2.5\\ \\text{m/s}$","$v_y = 10.3 - (9.80)(1.60) = -5.4\\ \\text{m/s}$","$v_x = 14.7\\ \\text{m/s}$ عند اللحظتين"]'::jsonb, '[{"element":"المركّبتان الابتدائيتان","marks":1},{"element":"$v_y$ عند 0.80 s","marks":1},{"element":"$v_y$ عند 1.60 s","marks":1},{"element":"التفسير وثبات $v_x$","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات وتفسير صحيحة"},{"level":"2–3 درجات","description":"خطأ في حساب واحد أو في الإشارة"},{"level":"درجة واحدة","description":"المركّبتان الابتدائيتان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل sin وcos","استعمال $a_y = +9.80\\ \\text{m/s}^2$","إنقاص $v_x$ مع الزمن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.178Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $a_x = \frac{\Delta v_x}{\Delta t} = \frac{12.0 - 12.0}{2.00} = 0$؛ و$a_y = \frac{\Delta v_y}{\Delta t} = \frac{-9.80 - 9.80}{2.00} = -9.80\ \text{m/s}^2$، وهو ثابت في كل فترة (تتغير $v_y$ بمقدار $-4.90\ \text{m/s}$ كل 0.50 s)؛ أي إن التسارع $\boldsymbol{g}$ رأسيًا إلى أسفل ولا مركّبة أفقية له. (b) $v_y$ موجبة في الصعود لأن الكرة تتحرك إلى أعلى (+y)، وتتناقص حتى تنعدم عند أقصى ارتفاع ($t = 1.00\ \text{s}$)، ثم تصبح سالبة في النزول لأن الكرة تتحرك إلى أسفل، ويتزايد مقدارها. (c) قوله خاطئ: انعدام $v_y$ لحظيًا لا يعني انعدام التسارع؛ فالتغير في $v_y$ من $t = 0.50\ \text{s}$ إلى $t = 1.50\ \text{s}$ يساوي $-9.80\ \text{m/s}$ خلال 1.00 s، أي إن $a_y = -9.80\ \text{m/s}^2$ عند هذه اللحظة أيضًا، لأن الجاذبية الأرضية تؤثر في الكرة دائمًا؛ ولولا هذا التسارع لما بدأت الكرة بالنزول.', '["$a_x = 0$ من ثبات $v_x$","$a_y = -9.80\\ \\text{m/s}^2$ ثابت من تغيرات $v_y$","تفسير إشارة $v_y$ (موجبة صعودًا، صفر عند القمة، سالبة نزولًا)","تقويم القول: التسارع لا ينعدم عند القمة مع الدليل من الجدول"]'::jsonb, '["$a_x = \\frac{12.0 - 12.0}{2.00} = 0$","$a_y = \\frac{-9.80 - 9.80}{2.00} = -9.80\\ \\text{m/s}^2$","في كل فترة 0.50 s: $\\Delta v_y = -4.90\\ \\text{m/s}$ ⇐ $a_y$ ثابت","حول $t = 1.00\\ \\text{s}$: $\\frac{-4.90 - 4.90}{1.00} = -9.80\\ \\text{m/s}^2 \\neq 0$"]'::jsonb, '[{"element":"حساب $a_x$","marks":1},{"element":"حساب $a_y$ وثباته","marks":1},{"element":"تفسير إشارة $v_y$","marks":1},{"element":"تقويم قول الطالب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان صحيحان والتفسير والتقويم مدعومان بالبيانات"},{"level":"2–3 درجات","description":"الحسابان صحيحان مع نقص في التفسير أو التقويم"},{"level":"درجة واحدة","description":"حساب أحد التسارعين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب $a_y$ موجبًا بإهمال إشارة $v_y$ في النزول","القول إن التسارع ينعدم عند القمة","إعطاء الكرة تسارعًا أفقيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-21T13:36:33.178Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C6-L1-O09') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L1-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبين الشكل الآتي مسار كرة قُذفت بزاوية فوق سطح أفقي، ومركّبتي سرعتها المتجهة عند عدة نقاط. أيّ مما يأتي يصف السرعة المتجهة للكرة عند أعلى نقطة C؟ (أهمل مقاومة الهواء)', null, '[{"src":"qimg/phys1/c6l1-o10-components.svg","alt":"مسار منحنٍ متقطع لكرة قُذفت بزاوية من سطح أفقي نحو اليمين، وعليه خمس نقاط: A نقطة الإطلاق على الأرض، وB في أثناء الصعود، وC أعلى نقطة في المسار، وD في أثناء النزول، وE نقطة السقوط على الأرض. عند A وB وD وE سهمان أحمران: سهم أفقي نحو اليمين (المركّبة الأفقية للسرعة) طوله متساوٍ عند النقاط الأربع، وسهم رأسي (المركّبة الرأسية): إلى أعلى وطويل عند A، وإلى أعلى وأقصر عند B، وإلى أسفل وقصير عند D، وإلى أسفل وطويل عند E. عند A كُتب v_x بجانب السهم الأفقي وv_y بجانب السهم الرأسي. أما عند C فلا توجد أسهم، وكُتب بجانبها «C ؟». وفي الزاوية العليا سهما المحورين +x نحو اليمين و+y إلى أعلى."}]'::jsonb, '["أفقية فقط، وتساوي المركّبة الأفقية عند بقية النقاط","صفر؛ لأن الكرة تتوقف لحظيًّا عند أعلى نقطة","رأسية فقط إلى أسفل؛ لأن الكرة تبدأ النزول عندها","أفقية فقط، ومقدارها يساوي مقدار السرعة الابتدائية"]'::jsonb, 'فهم', 'تفسير رسم', 'سهل', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('mcq', 2, 'قُذفت كرة بسرعة ابتدائية مقدارها 20.0 m/s في اتجاه يصنع زاوية $30.0^\circ$ فوق الأفقي. ما مقدار سرعتها عند أقصى ارتفاع تصل إليه؟ (أهمل مقاومة الهواء)', null, null, '["0 m/s","10.0 m/s","20.0 m/s","17.3 m/s"]'::jsonb, 'تطبيق', 'حساب السرعة عند القمة', 'متوسط', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('mcq', 3, 'يبين الشكل الآتي خمس نقاط على مسار كرة قُذفت بزاوية فوق سطح أفقي. عند أيّ نقطة تكون المركّبة الرأسية للسرعة المتجهة صفرًا؟ (أهمل مقاومة الهواء)', null, '[{"src":"qimg/phys1/c6l1-o10-points.svg","alt":"مسار منحنٍ متقطع لكرة قُذفت بزاوية من سطح أفقي نحو اليمين، وعليه خمس نقاط: A نقطة الإطلاق على الأرض، وB على الجزء الصاعد، وC أعلى نقطة في المسار، وD على الجزء النازل، وE نقطة السقوط على الأرض. لا توجد أي أسهم على المسار. وفي الزاوية العليا سهما المحورين +x نحو اليمين و+y إلى أعلى."}]'::jsonb, '["النقطة A","النقطة B","النقطة C","النقطة E"]'::jsonb, 'فهم', 'قراءة رسم', 'سهل', 'الكتاب ص 180 — السؤال 28c'),
('mcq', 4, 'يبين الشكل الآتي متجه سرعة كرة مقذوفة عند أعلى نقطة C من مسارها، وله مركّبة أفقية فقط. ما سبب انعدام المركّبة الرأسية للسرعة عند هذه النقطة؟', null, '[{"src":"qimg/phys1/c6l1-o10-top.svg","alt":"مسار منحنٍ متقطع لكرة قُذفت بزاوية من سطح أفقي نحو اليمين، وعند أعلى نقطة في المسار C سهم أحمر واحد أفقي نحو اليمين مكتوب عنده v_x، ولا يوجد عندها سهم رأسي. وفي الزاوية العليا سهما المحورين +x نحو اليمين و+y إلى أعلى."}]'::jsonb, '["تنعدم قوة الجاذبية الأرضية عند أعلى نقطة فتتوقف الحركة الرأسية","تتناقص المركّبة الرأسية بانتظام بفعل تسارع الجاذبية حتى تصبح صفرًا ثم تنعكس","تتحوّل المركّبة الرأسية إلى مركّبة أفقية فتزداد السرعة الأفقية عند القمة","تتساوى قوة الجاذبية الأرضية مع قوة تدفع الكرة إلى أعلى عند هذه النقطة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('mcq', 5, 'قُذفت كرة بزاوية فوق سطح أفقي. أيّ العبارات الآتية صحيحة لحظة وصولها إلى أقصى ارتفاع؟ (أهمل مقاومة الهواء)', null, null, '["سرعتها أفقية فقط، وتسارعها صفر","سرعتها صفر، وتسارعها $\\boldsymbol{g}$ رأسيًّا إلى أسفل","سرعتها أفقية، وتسارعها $\\boldsymbol{g}$ رأسيًّا إلى أسفل","سرعتها رأسية فقط إلى أسفل، وتسارعها $\\boldsymbol{g}$ أفقيًّا"]'::jsonb, 'تحليل', 'مقارنة السرعة والتسارع', 'متوسط', 'الكتاب ص 164، 180 — المقذوفات التي تطلق بزاوية؛ السؤال 28d'),
('mcq', 6, 'بلغ مقدار سرعة كرة عند أقصى ارتفاع وصلت إليه 12.0 m/s، وكانت قد قُذفت في اتجاه يصنع زاوية $37.0^\circ$ فوق الأفقي. ما مقدار سرعتها الابتدائية؟ (أهمل مقاومة الهواء)', null, null, '["12.0 m/s","15.0 m/s","9.58 m/s","19.9 m/s"]'::jsonb, 'تحليل', 'استنتاج عكسي', 'صعب', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('mcq', 7, 'قُذفت كرتان بمقدار السرعة الابتدائية نفسه: الأولى رأسيًّا إلى أعلى، والثانية في اتجاه يصنع زاوية $50.0^\circ$ فوق الأفقي. ما سرعة كل منهما لحظة وصولها إلى أقصى ارتفاع؟ (أهمل مقاومة الهواء)', null, null, '["سرعة الأولى صفر، وسرعة الثانية أفقية لا تساوي صفرًا","سرعة كل منهما صفر لحظة وصولها إلى أقصى ارتفاع","سرعة الأولى أفقية، وسرعة الثانية تساوي صفرًا","سرعة كل منهما أفقية، والسرعتان متساويتان مقدارًا"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('essay', 1, 'فسّر لماذا تكون سرعة المقذوف المُطلق بزاوية فوق الأفقي عند أقصى ارتفاع أفقية فقط، وبيّن لماذا لا تساوي صفرًا، ثم اكتب علاقة مقدارها بدلالة $v_i$ و$\theta_i$. (أهمل مقاومة الهواء)', null, null, null, 'فهم', 'تفسير وكتابة علاقة', 'سهل', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('essay', 2, 'قُذفت كرة بسرعة ابتدائية مقدارها 15.0 m/s في اتجاه يصنع زاوية $53.0^\circ$ فوق الأفقي. (أهمل مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$) احسب: (a) المركّبتين الأفقية والرأسية للسرعة الابتدائية. (b) الزمن اللازم لتصل الكرة إلى أقصى ارتفاع. (c) مقدار سرعة الكرة واتجاهها عند أقصى ارتفاع.', null, null, null, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 165 — مثال 1: تحليل كرة'),
('essay', 3, 'يبين الشكل الآتي مساري كرتين قُذفتا بمقدار السرعة الابتدائية نفسه 20.0 m/s، الأولى بزاوية $30.0^\circ$ والثانية بزاوية $60.0^\circ$ فوق الأفقي. (a) احسب مقدار سرعة كل كرة عند أقصى ارتفاع تصل إليه. (b) أيّ الكرتين تكون سرعتها أصغر عند القمة؟ فسّر ذلك. (c) ما قيمة المركّبة الرأسية لسرعة كل منهما عند القمة؟ (أهمل مقاومة الهواء)', null, '[{"src":"qimg/phys1/c6l1-o10-two-angles.svg","alt":"مساران متقطعان لكرتين قُذفتا من النقطة نفسها على سطح أفقي، ويبدأ المساران وينتهيان عند النقطتين نفسيهما على الأرض. المسار (1) داكن متقطع منخفض زاوية إطلاقه 30.0°، والمسار (2) برتقالي منقّط مرتفع زاوية إطلاقه 60.0°. ومكتوب أسفل الشكل: مقدار السرعة الابتدائية في المسارين 20.0 m/s."}]'::jsonb, null, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L1-O10') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'عند أقصى ارتفاع تكون المركّبة الرأسية للسرعة صفرًا، فتبقى المركّبة الأفقية وحدها، وهي ثابتة على امتداد المسار؛ لعدم وجود قوة أفقية تؤثر في الكرة. لذا تكون السرعة عند C أفقية فقط، ومقدارها يساوي طول السهم الأفقي عند بقية النقاط.', '["","المركّبة الرأسية وحدها تساوي صفرًا عند القمة، أما المركّبة الأفقية فتبقى، فالكرة لا تتوقف.","عند C تنعدم المركّبة الرأسية تمامًا، ولا تصبح إلى أسفل إلا بعد تجاوز القمة.","السرعة الابتدائية لها مركّبتان، وعند القمة تبقى المركّبة الأفقية فقط، وهي أصغر من السرعة الابتدائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-21T13:36:33.179Z"}'::jsonb),
('mcq', 2, 3, 'عند أقصى ارتفاع تكون $v_y = 0$، فتبقى المركّبة الأفقية فقط: $v_x = v_i\cos\theta_i = (20.0\ \text{m/s})\cos 30.0^\circ = 17.3\ \text{m/s}$.', '["هذا يفترض أن السرعة كلها تنعدم عند القمة، مع أن المركّبة الأفقية لا تتغير.","هذه المركّبة الرأسية الابتدائية $v_i\\sin\\theta_i$؛ استُعمل الجيب بدل جيب التمام.","هذا مقدار السرعة الابتدائية، والسرعة عند القمة هي المركّبة الأفقية فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-11-21T13:36:33.180Z"}'::jsonb),
('mcq', 3, 2, 'المركّبة الرأسية للسرعة تتناقص في أثناء الصعود حتى تصبح صفرًا عند أقصى ارتفاع، وهو النقطة C، ثم تنعكس إلى أسفل وتتزايد في أثناء النزول.', '["عند A تكون المركّبة الرأسية أكبر ما يمكن إلى أعلى؛ فهي نقطة الإطلاق.","عند B ما زالت الكرة تصعد، فمركّبتها الرأسية إلى أعلى ولم تصل إلى الصفر بعد.","","عند E تكون المركّبة الرأسية أكبر ما يمكن إلى أسفل لحظة السقوط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-21T13:36:33.180Z"}'::jsonb),
('mcq', 4, 1, 'تسارع الكرة ثابت ومقداره $g$ رأسيًّا إلى أسفل؛ فتتناقص المركّبة الرأسية لسرعتها في أثناء الصعود بمعدل ثابت حتى تصبح صفرًا عند أقصى ارتفاع، ثم تتزايد إلى أسفل. أما المركّبة الأفقية فلا تتغير.', '["قوة الجاذبية الأرضية تؤثر في الكرة في جميع نقاط المسار، ومنها القمة.","","المركّبتان مستقلتان؛ فالمركّبة الأفقية ثابتة ولا تكتسب شيئًا من المركّبة الرأسية.","بعد مغادرة اليد لا توجد قوة تدفع الكرة إلى أعلى؛ القوة الوحيدة هي الجاذبية الأرضية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-21T13:36:33.181Z"}'::jsonb),
('mcq', 5, 2, 'عند القمة تنعدم المركّبة الرأسية للسرعة فتبقى السرعة أفقية فقط، لكن التسارع لا ينعدم؛ فالجاذبية الأرضية تؤثر في الكرة دائمًا، وتسارعها $\boldsymbol{g}$ رأسيًّا إلى أسفل في كل نقاط المسار.', '["انعدام المركّبة الرأسية للسرعة لا يعني انعدام التسارع؛ فالتسارع يساوي $\\boldsymbol{g}$ إلى أسفل دائمًا.","المركّبة الأفقية للسرعة لا تنعدم عند القمة، فالسرعة لا تساوي صفرًا.","","عند القمة تنعدم المركّبة الرأسية للسرعة، وتسارع المقذوف رأسي دائمًا وليس أفقيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-21T13:36:33.181Z"}'::jsonb),
('mcq', 6, 1, 'السرعة عند القمة أفقية فقط وتساوي $v_x = v_i\cos\theta_i$، ومنها: $v_i = \frac{v_x}{\cos\theta_i} = \frac{12.0\ \text{m/s}}{\cos 37.0^\circ} = 15.0\ \text{m/s}$.', '["هذا يفترض أن سرعة الكرة عند القمة تساوي سرعتها الابتدائية، مع أن المركّبة الرأسية انعدمت.","","ضُربت السرعة عند القمة في $\\cos\\theta_i$ بدل القسمة عليه، فنتجت قيمة أصغر من سرعة القمة نفسها.","قُسمت على $\\sin\\theta_i$؛ أي عُدّت سرعة القمة مركّبة رأسية مع أنها المركّبة الأفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-11-21T13:36:33.181Z"}'::jsonb),
('mcq', 7, 0, 'الكرة المقذوفة رأسيًّا ليس لها مركّبة أفقية، فتنعدم سرعتها كلها عند القمة. أما المقذوفة بزاوية فلها مركّبة أفقية ثابتة $v_i\cos 50.0^\circ$، فتكون سرعتها عند القمة أفقية ولا تساوي صفرًا.', '["","الكرة الثانية تحتفظ بمركّبتها الأفقية عند القمة، فسرعتها لا تساوي صفرًا.","عُكست الحالتان: المقذوفة رأسيًّا لا مركّبة أفقية لها، فسرعتها هي التي تنعدم.","الكرة الأولى لا مركّبة أفقية لها، فسرعتها عند القمة صفر لا سرعة أفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-21T13:36:33.182Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يتحرك المقذوف بتسارع ثابت $\boldsymbol{g}$ رأسيًّا إلى أسفل، فتتناقص المركّبة الرأسية لسرعته في أثناء الصعود حتى تصبح صفرًا عند أقصى ارتفاع ثم يبدأ النزول؛ لذلك لا يبقى عند القمة إلا المركّبة الأفقية. ولا تساوي السرعة صفرًا لأنه لا توجد قوة أفقية تؤثر في المقذوف، فتبقى مركّبته الأفقية ثابتة على امتداد المسار. ومقدار السرعة عند القمة: $v = v_x = v_i\cos\theta_i$.', '["المركّبة الرأسية تتناقص بفعل الجاذبية حتى تنعدم عند القمة","المركّبة الأفقية ثابتة لعدم وجود قوة أفقية، فالسرعة لا تساوي صفرًا","كتابة العلاقة $v = v_i\\cos\\theta_i$"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير انعدام المركّبة الرأسية","marks":1},{"element":"تفسير بقاء المركّبة الأفقية","marks":1},{"element":"العلاقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل للمركّبتين مع العلاقة الصحيحة"},{"level":"درجتان","description":"تفسير صحيح لإحدى المركّبتين مع العلاقة، أو للمركّبتين دون العلاقة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن سرعة المقذوف عند القمة صفر.","كتابة $v_i\\sin\\theta_i$ بدل $v_i\\cos\\theta_i$.","القول إن الجاذبية تنعدم عند القمة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-21T13:36:33.182Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $v_{xi} = v_i\cos\theta_i = (15.0)\cos 53.0^\circ = 9.03\ \text{m/s}$، و$v_{yi} = v_i\sin\theta_i = (15.0)\sin 53.0^\circ = 12.0\ \text{m/s}$. (b) عند القمة $v_y = 0$: $t = \frac{v_{yi} - v_y}{g} = \frac{12.0 - 0}{9.80} = 1.22\ \text{s}$. (c) عند القمة تبقى المركّبة الأفقية فقط، فمقدار السرعة 9.03 m/s، واتجاهها أفقي في اتجاه الحركة.', '["حساب $v_{xi} = 9.03\\ \\text{m/s}$","حساب $v_{yi} = 12.0\\ \\text{m/s}$","حساب زمن الصعود 1.22 s باستعمال $v_y = 0$","السرعة عند القمة 9.03 m/s أفقية"]'::jsonb, '["$v_{xi} = (15.0\\ \\text{m/s})\\cos 53.0^\\circ = 9.03\\ \\text{m/s}$","$v_{yi} = (15.0\\ \\text{m/s})\\sin 53.0^\\circ = 12.0\\ \\text{m/s}$","$v_y = v_{yi} - gt = 0 \\Rightarrow t = \\frac{12.0\\ \\text{m/s}}{9.80\\ \\text{m/s}^2} = 1.22\\ \\text{s}$","عند القمة: $v = v_x = 9.03\\ \\text{m/s}$ أفقيًّا"]'::jsonb, '[{"element":"$v_{xi}$","marks":1},{"element":"$v_{yi}$","marks":1},{"element":"زمن الصعود","marks":1},{"element":"السرعة عند القمة واتجاهها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات الأربعة صحيحة بوحداتها وأرقامها المعنوية"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل $\\sin$ و$\\cos$ في المركّبتين.","كتابة السرعة عند القمة صفرًا.","حساب زمن التحليق كاملًا بدل زمن الصعود."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-21T13:36:33.183Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) السرعة عند القمة أفقية فقط وتساوي $v_i\cos\theta_i$: للأولى $(20.0)\cos 30.0^\circ = 17.3\ \text{m/s}$، وللثانية $(20.0)\cos 60.0^\circ = 10.0\ \text{m/s}$. (b) الكرة الثانية (المسار (2))؛ لأن زاوية إطلاقها أكبر فتكون مركّبتها الأفقية أصغر، والسرعة عند القمة هي المركّبة الأفقية وحدها. (c) المركّبة الرأسية صفر عند القمة لكل من الكرتين.', '["17.3 m/s للمسار (1)","10.0 m/s للمسار (2)","تفسير أن الزاوية الأكبر تعطي مركّبة أفقية أصغر","المركّبة الرأسية صفر للكرتين"]'::jsonb, '["$v_1 = (20.0\\ \\text{m/s})\\cos 30.0^\\circ = 17.3\\ \\text{m/s}$","$v_2 = (20.0\\ \\text{m/s})\\cos 60.0^\\circ = 10.0\\ \\text{m/s}$","المقارنة والتفسير","$v_y = 0$ عند القمة للكرتين"]'::jsonb, '[{"element":"سرعة القمة للمسار (1)","marks":1},{"element":"سرعة القمة للمسار (2)","marks":1},{"element":"المقارنة والتفسير","marks":1},{"element":"المركّبة الرأسية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان ومقارنة مفسَّرة والمركّبة الرأسية صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكرتين سرعتهما متساوية عند القمة لأن سرعتيهما الابتدائيتين متساويتان.","استعمال $\\sin\\theta_i$ لحساب السرعة عند القمة.","عدّ المسار الأعلى أسرع عند القمة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-21T13:36:33.184Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
