from (values
('mcq', 1, 'يبين الشكل الآتي مسار مقذوف أُطلق بزاوية فوق سطح أفقي، وعليه ثلاث كميات مرقّمة. ماذا يمثّل كلٌّ من (2) و(3)؟', null, '[{"src":"qimg/phys1/c6l1-o11-marked.svg","alt":"مسار منحنٍ متصل لكرة قُذفت من سطح أفقي نحو اليمين. عند نقطة الإطلاق سهم أحمر مائل إلى أعلى يمينًا مكتوب عنده v_i، وبينه وبين الأرض قوس زاوية مكتوب عنده (1). ومن أعلى نقطة في المسار خط رأسي متقطع إلى الأرض بجانبه سهم برأسين مكتوب عنده (2). وتحت الأرض سهم أفقي برأسين يمتد من نقطة الإطلاق إلى نقطة السقوط مكتوب عنده (3)."}]'::jsonb, '["(2) أقصى ارتفاع، و(3) المدى الأفقي","(2) المدى الأفقي، و(3) أقصى ارتفاع","(2) أقصى ارتفاع، و(3) زمن التحليق","(2) زمن التحليق، و(3) المدى الأفقي"]'::jsonb, 'فهم', 'تحديد على الرسم', 'سهل', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('mcq', 2, 'رسم طالب مركّبتي السرعة المتجهة لكرة مقذوفة عند النقاط A وB وC وD كما في الشكل الآتي. عند أيّ نقطة أخطأ الطالب في الرسم؟ (أهمل مقاومة الهواء)', null, '[{"src":"qimg/phys1/c6l1-o11-check.svg","alt":"مسار منحنٍ متقطع لكرة قُذفت بزاوية من سطح أفقي نحو اليمين، وعليه أربع نقاط رسم عندها طالب أسهمًا حمراء تمثل المركّبتين الأفقية والرأسية للسرعة: A على الجزء الصاعد: سهم أفقي نحو اليمين وسهم رأسي إلى أعلى. B أعلى نقطة في المسار: سهم أفقي نحو اليمين فقط. C على الجزء النازل: سهم أفقي نحو اليمين وسهم رأسي إلى أعلى. D قرب نقطة السقوط: سهم أفقي نحو اليمين وسهم رأسي طويل إلى أسفل. الأسهم الأفقية عند النقاط الأربع متساوية الطول. وفي الزاوية العليا سهما المحورين +x و+y."}]'::jsonb, '["النقطة A","النقطة B","النقطة C","النقطة D"]'::jsonb, 'تحليل', 'اكتشاف خطأ في رسم', 'متوسط', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('mcq', 3, 'يبين الشكل الآتي ثلاث نقاط على مسار كرة مقذوفة بزاوية. عند تمثيل متجه تسارع الكرة عند النقاط A وB وC، ما الاتجاه الصحيح؟ (أهمل مقاومة الهواء)', null, '[{"src":"qimg/phys1/c6l1-o11-accel.svg","alt":"مسار منحنٍ متقطع لكرة قُذفت بزاوية من سطح أفقي نحو اليمين، وعليه ثلاث نقاط: A على الجزء الصاعد، وB أعلى نقطة في المسار، وC على الجزء النازل. لا توجد أسهم على المسار. وفي الزاوية العليا سهما المحورين +x نحو اليمين و+y إلى أعلى."}]'::jsonb, '["مماسٌّ للمسار في اتجاه الحركة عند النقاط الثلاث","إلى أعلى عند A، وصفر عند B، وإلى أسفل عند C","رأسيًّا إلى أسفل عند A وC، وصفر عند B","رأسيًّا إلى أسفل عند النقاط الثلاث"]'::jsonb, 'فهم', 'تمثيل التسارع', 'سهل', 'الكتاب ص 164، 179 — الشكل 6-3a؛ المركّبة الرأسية لها تسارع ثابت'),
('mcq', 4, 'عند رسم سهم المركّبة الأفقية للسرعة $\boldsymbol{v}_x$ عند نقاط مختلفة من مسار مقذوف (مع إهمال مقاومة الهواء)، كيف يجب أن تكون أطوال هذه الأسهم؟', null, null, '["تتناقص حتى تصبح صفرًا عند أقصى ارتفاع","متساوية عند جميع نقاط المسار","تتزايد من نقطة الإطلاق حتى نقطة السقوط","أكبر ما يمكن عند القمة وأصغر عند الطرفين"]'::jsonb, 'فهم', 'تمثيل المركّبات', 'متوسط', 'الكتاب ص 163–164 — الشكلان 6-2 و6-3'),
('mcq', 5, 'يريد طالب رسم مركّبتي السرعة الابتدائية لكرة قُذفت بسرعة 10.0 m/s في اتجاه يصنع زاوية $30.0^\circ$ فوق الأفقي. ما القيمتان اللتان يكتبهما على السهمين؟', null, null, '["$v_{xi} = 8.66\\ \\text{m/s}$ و$v_{yi} = 5.00\\ \\text{m/s}$","$v_{xi} = 5.00\\ \\text{m/s}$ و$v_{yi} = 8.66\\ \\text{m/s}$","$v_{xi} = 10.0\\ \\text{m/s}$ و$v_{yi} = 10.0\\ \\text{m/s}$","$v_{xi} = 5.00\\ \\text{m/s}$ و$v_{yi} = 5.00\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'تحليل متجه', 'متوسط', 'الكتاب ص 165 — مثال 1: تحليل كرة'),
('mcq', 6, 'عند تحديد زاوية الإطلاق $\theta_i$ على رسم مسار مقذوف، بين أيّ اتجاهين تُقاس؟', null, null, '["بين متجه السرعة الابتدائية والاتجاه الرأسي","بين متجه السرعة عند أقصى ارتفاع والأفقي","بين متجه التسارع والاتجاه الأفقي","بين متجه السرعة الابتدائية والاتجاه الأفقي"]'::jsonb, 'تذكر', 'تحديد زاوية', 'سهل', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('mcq', 7, 'يبين الشكل الآتي مركّبتي السرعة المتجهة لكرة عند نقطة P من مسارها بعد قذفها بزاوية فوق سطح أفقي نحو اليمين. أيّ العبارات الآتية تصف النقطة P والسرعة المتجهة عندها؟', null, '[{"src":"qimg/phys1/c6l1-o11-point.svg","alt":"نقطة واحدة P تخرج منها سهمان أحمران: سهم أفقي نحو اليمين مكتوب عنده v_x، وسهم رأسي إلى أسفل أقصر منه مكتوب عنده v_y. ولا يظهر المسار. وفي الأسفل سهما المحورين +x نحو اليمين و+y إلى أعلى."}]'::jsonb, '["P قبل أقصى ارتفاع، والسرعة المتجهة عندها نحو اليمين وإلى أعلى","P بعد أقصى ارتفاع، والسرعة المتجهة عندها نحو اليمين وإلى أسفل","P عند أقصى ارتفاع، والسرعة المتجهة عندها أفقية فقط نحو اليمين","P بعد أقصى ارتفاع، والسرعة المتجهة عندها رأسية فقط إلى أسفل"]'::jsonb, 'تحليل', 'تفسير متجهات', 'صعب', 'الكتاب ص 163–164 — الشكلان 6-2b و6-3b'),
('essay', 1, 'ارسم مسار كرة قُذفت من سطح أرض أفقي بزاوية فوق الأفقي ثم عادت إلى الأرض (مع إهمال مقاومة الهواء)، وحدّد عليه: زاوية الإطلاق، وأقصى ارتفاع، والمدى الأفقي. ثم مثّل مركّبتي السرعة المتجهة $\boldsymbol{v}_x$ و$\boldsymbol{v}_y$ ومتجه التسارع عند: نقطة الإطلاق، ونقطة في أثناء الصعود، وأعلى نقطة، ونقطة في أثناء النزول.', null, null, null, 'تطبيق', 'رسم وتمثيل', 'متوسط', 'الكتاب ص 164–165 — الشكل 6-3b ورسم المثال 1'),
('essay', 2, 'قُذفت كرة من سطح أرض أفقي بسرعة ابتدائية 12.0 m/s في اتجاه يصنع زاوية $40.0^\circ$ فوق الأفقي، وعادت إلى مستوى الإطلاق نفسه. (أهمل مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$) (a) احسب المركّبتين الأفقية والرأسية لسرعتها عند نقطة الإطلاق. (b) ما قيمتا المركّبتين عند أقصى ارتفاع، ولحظة عودتها إلى الأرض؟ (c) إذا مثّلت كل 2.0 m/s بسهم طوله 1.0 cm، فما أطوال الأسهم واتجاهاتها التي ترسمها عند النقاط الثلاث؟', null, null, null, 'تطبيق', 'حساب ورسم بمقياس', 'صعب', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('essay', 3, 'رسم طالب مسار كرة مقذوفة بزاوية مع بعض المتجهات كما في الشكل الآتي. قوّم رسمه: حدّد ثلاثة أخطاء فيه، وبيّن التصحيح الفيزيائي لكل خطأ مع السبب. (أهمل مقاومة الهواء)', null, '[{"src":"qimg/phys1/c6l1-o11-student.svg","alt":"رسم طالب لمسار كرة قُذفت بزاوية من سطح أفقي نحو اليمين (منحنى متقطع) مع ثلاث نقاط: A على الجزء الصاعد: سهم أحمر أفقي نحو اليمين مكتوب عنده v_x، وسهم أحمر إلى أعلى مكتوب عنده v_y، وسهم بنفسجي مكتوب عنده a مائل إلى أعلى يمينًا مماسًّا للمسار. B أعلى نقطة: لا توجد أسهم، ومكتوب بجانبها v = 0 بالأحمر وa = 0 بالبنفسجي. C على الجزء النازل: سهم أحمر أفقي نحو اليمين أقصر من السهم الأفقي عند A بنحو النصف، وسهم أحمر إلى أسفل، وسهم بنفسجي مكتوب عنده a مائل إلى أسفل يمينًا مماسًّا للمسار. وفي الزاوية العليا سهما المحورين +x و+y."}]'::jsonb, null, 'تقويم', 'تقويم رسم', 'صعب', 'الكتاب ص 164، 179 — الشكل 6-3 ودليل مراجعة الفصل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L1-O11') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, '(2) خط رأسي من أعلى نقطة في المسار إلى مستوى الإطلاق، فهو أقصى ارتفاع؛ و(3) المسافة الأفقية بين نقطتي الإطلاق والسقوط، فهو المدى الأفقي $R$. أما (1) فهي زاوية الإطلاق.', '["","عُكست الكميتان: المدى الأفقي مسافة أفقية على الأرض، وأقصى ارتفاع مسافة رأسية.","زمن التحليق كمية زمنية لا تُمثّل بطول على الرسم؛ و(3) مسافة أفقية هي المدى الأفقي.","زمن التحليق كمية زمنية لا تُرسم طولًا رأسيًّا؛ و(2) هو أقصى ارتفاع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.185Z"}'::jsonb),
('mcq', 2, 2, 'النقطة C تقع على الجزء النازل من المسار بعد أقصى ارتفاع، فيجب أن تكون المركّبة الرأسية للسرعة عندها إلى أسفل، لكن الطالب رسمها إلى أعلى.', '["عند A (في أثناء الصعود) المركّبة الأفقية نحو اليمين والرأسية إلى أعلى، وهذا صحيح.","عند القمة B تنعدم المركّبة الرأسية وتبقى الأفقية فقط، وهذا صحيح.","","عند D قرب السقوط المركّبة الرأسية كبيرة إلى أسفل والأفقية مساوية لبقية النقاط، وهذا صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-21T13:36:33.185Z"}'::jsonb),
('mcq', 3, 3, 'القوة الوحيدة المؤثرة في المقذوف هي الجاذبية الأرضية، فتسارعه ثابت $\boldsymbol{g}$ رأسيًّا إلى أسفل عند كل نقطة من المسار، ولا مركّبة أفقية له.', '["المماس للمسار هو اتجاه السرعة المتجهة لا التسارع.","هذا وصف لاتجاه المركّبة الرأسية للسرعة، والتسارع إلى أسفل دائمًا.","التسارع لا ينعدم عند القمة؛ فالجاذبية تؤثر في الكرة هناك أيضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-21T13:36:33.186Z"}'::jsonb),
('mcq', 4, 1, 'لا توجد قوة أفقية تؤثر في المقذوف، فتسارعه الأفقي صفر ($a_x = 0$)، وتبقى المركّبة الأفقية لسرعته ثابتة؛ لذا تُرسم أسهمها متساوية الطول عند جميع النقاط.', '["المركّبة الرأسية هي التي تتناقص حتى الصفر عند القمة، لا الأفقية.","","لا يوجد تسارع أفقي يزيد المركّبة الأفقية.","المركّبة الأفقية لا تتغير من نقطة إلى أخرى، فلا تكون أكبر عند القمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-21T13:36:33.186Z"}'::jsonb),
('mcq', 5, 0, '$v_{xi} = v_i\cos\theta_i = (10.0)\cos 30.0^\circ = 8.66\ \text{m/s}$، و$v_{yi} = v_i\sin\theta_i = (10.0)\sin 30.0^\circ = 5.00\ \text{m/s}$؛ فيكون السهم الأفقي أطول من الرأسي.', '["","بُدّل الجيب وجيب التمام؛ فالمركّبة الأفقية تُحسب بـ $\\cos\\theta_i$ لأن الزاوية مقيسة من الأفقي.","لا تساوي أيٌّ من المركّبتين مقدار السرعة كلها؛ فكل منهما أصغر من الوتر.","قُسم مقدار السرعة على 2 بالتساوي، والمركّبتان لا تتساويان إلا عند زاوية $45^\\circ$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-21T13:36:33.186Z"}'::jsonb),
('mcq', 6, 3, 'زاوية الإطلاق هي الزاوية التي يصنعها متجه السرعة الابتدائية $\boldsymbol{v}_i$ مع الأفقي عند نقطة الإطلاق.', '["تُقاس زاوية الإطلاق عادة من الأفقي، والزاوية مع الرأسي هي متمّمتها.","السرعة عند القمة أفقية، فزاويتها مع الأفقي صفر دائمًا.","التسارع رأسي دائمًا، فلا يحدد زاوية الإطلاق.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-21T13:36:33.187Z"}'::jsonb),
('mcq', 7, 1, 'المركّبة الرأسية عند P إلى أسفل، فالكرة تجاوزت القمة وهي تنزل. والسرعة المتجهة هي المجموع الاتجاهي للمركّبتين، فتتجه نحو اليمين وإلى أسفل، مماسّة للمسار عند P.', '["قبل القمة تكون المركّبة الرأسية إلى أعلى، أما في الشكل فهي إلى أسفل.","","عند القمة تنعدم المركّبة الرأسية، والشكل يبين مركّبة رأسية لا تساوي صفرًا.","أُهملت المركّبة الأفقية؛ فالسرعة المتجهة هي مجموع المركّبتين معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.187Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يُرسم المسار منحنيًا متماثلًا (قطعًا مكافئًا) يبدأ من الأرض وينتهي عليها. زاوية الإطلاق $\theta_i$ بين متجه السرعة الابتدائية والأفقي عند نقطة الإطلاق؛ وأقصى ارتفاع خط رأسي من أعلى نقطة إلى مستوى الإطلاق؛ والمدى الأفقي $R$ المسافة الأفقية بين نقطتي الإطلاق والسقوط. مركّبات السرعة: $\boldsymbol{v}_x$ سهم أفقي في اتجاه الحركة بالطول نفسه عند جميع النقاط. $\boldsymbol{v}_y$: عند الإطلاق إلى أعلى وأطول ما يمكن، وفي أثناء الصعود إلى أعلى وأقصر، وعند القمة لا يُرسم (صفر)، وفي أثناء النزول إلى أسفل ويتزايد طوله. التسارع: سهم واحد $\boldsymbol{g}$ رأسي إلى أسفل وبالطول نفسه عند كل النقاط، بلا مركّبة أفقية.', '["مسار منحنٍ متماثل يبدأ وينتهي عند مستوى الإطلاق","تحديد الزاوية وأقصى ارتفاع والمدى الأفقي صحيحًا","$\\boldsymbol{v}_x$ أفقي ثابت الطول عند جميع النقاط","$\\boldsymbol{v}_y$ إلى أعلى ثم صفر عند القمة ثم إلى أسفل","التسارع رأسي إلى أسفل وثابت عند كل النقاط"]'::jsonb, '[]'::jsonb, '[{"element":"المسار","marks":1},{"element":"الكميات الثلاث على الرسم","marks":1},{"element":"المركّبة الأفقية","marks":1},{"element":"المركّبة الرأسية","marks":1},{"element":"التسارع","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"رسم كامل صحيح بجميع عناصره"},{"level":"4 درجات","description":"خطأ في عنصر واحد"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم التسارع مماسًّا للمسار.","إنقاص طول $\\boldsymbol{v}_x$ نحو القمة.","رسم السرعة عند القمة صفرًا كاملًا.","محاولة تمثيل زمن التحليق بطول على الرسم."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-21T13:36:33.188Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $v_{xi} = (12.0)\cos 40.0^\circ = 9.19\ \text{m/s}$، $v_{yi} = (12.0)\sin 40.0^\circ = 7.71\ \text{m/s}$. (b) عند القمة: $v_x = 9.19\ \text{m/s}$، $v_y = 0$. لحظة العودة: $v_x = 9.19\ \text{m/s}$، و$v_y = 7.71\ \text{m/s}$ إلى أسفل (بالتماثل). (c) سهم $\boldsymbol{v}_x$ طوله 4.6 cm أفقيًّا في اتجاه الحركة عند النقاط الثلاث؛ وسهم $\boldsymbol{v}_y$ طوله 3.9 cm إلى أعلى عند الإطلاق، ولا يُرسم عند القمة، وطوله 3.9 cm إلى أسفل لحظة العودة. ويُرسم عند كل نقطة متجه التسارع $\boldsymbol{g}$ رأسيًّا إلى أسفل.', '["حساب المركّبتين الابتدائيتين","المركّبتان عند القمة","المركّبتان لحظة العودة","أطوال الأسهم واتجاهاتها بمقياس الرسم"]'::jsonb, '["$v_{xi} = (12.0\\ \\text{m/s})\\cos 40.0^\\circ = 9.19\\ \\text{m/s}$","$v_{yi} = (12.0\\ \\text{m/s})\\sin 40.0^\\circ = 7.71\\ \\text{m/s}$","القمة: $v_y = 0$، و$v_x$ ثابتة","العودة: $v_y = -7.71\\ \\text{m/s}$ (إلى أسفل)","الأطوال: $\\frac{9.19}{2.0} = 4.6\\ \\text{cm}$ و$\\frac{7.71}{2.0} = 3.9\\ \\text{cm}$"]'::jsonb, '[{"element":"المركّبتان الابتدائيتان","marks":1},{"element":"عند القمة","marks":1},{"element":"لحظة العودة","marks":1},{"element":"أطوال الأسهم واتجاهاتها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع القيم والأطوال والاتجاهات صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل $v_x$ صفرًا عند القمة.","رسم $\\boldsymbol{v}_y$ لحظة العودة إلى أعلى.","الخطأ في مقياس الرسم (الضرب في 2.0 بدل القسمة)."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-21T13:36:33.188Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخطأ الأول: رسم التسارع $\boldsymbol{a}$ عند A وC مماسًّا للمسار؛ والصحيح أنه $\boldsymbol{g}$ رأسي إلى أسفل عند كل النقاط لأن القوة الوحيدة المؤثرة هي الجاذبية الأرضية، ولا مركّبة أفقية له. الخطأ الثاني: كتابة $v = 0$ عند القمة B؛ والصحيح أن المركّبة الرأسية وحدها صفر، وتبقى $\boldsymbol{v}_x$ أفقية بالطول نفسه. الخطأ الثالث: كتابة $a = 0$ عند B؛ والصحيح أن التسارع $\boldsymbol{g}$ إلى أسفل حتى عند القمة. الخطأ الرابع: رسم $\boldsymbol{v}_x$ عند C أقصر منه عند A؛ والصحيح أنه بالطول نفسه لعدم وجود قوة أفقية.', '["تصحيح اتجاه التسارع إلى رأسي إلى أسفل مع السبب","تصحيح السرعة عند القمة إلى أفقية لا صفر","تصحيح التسارع عند القمة إلى g لا صفر","تصحيح طول $\\boldsymbol{v}_x$ عند C ليساوي طوله عند A"]'::jsonb, '[]'::jsonb, '[{"element":"الخطأ الأول وتصحيحه","marks":1},{"element":"الخطأ الثاني وتصحيحه","marks":1},{"element":"الخطأ الثالث وتصحيحه","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاثة أخطاء صحيحة (من الأربعة) مع التصحيح والسبب"},{"level":"درجتان","description":"خطآن صحيحان مع التصحيح"},{"level":"درجة واحدة","description":"خطأ واحد صحيح مع تصحيحه"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول رسم التسارع مماسًّا للمسار.","تصحيح $v = 0$ إلى «سرعة رأسية فقط».","عدم ملاحظة اختلاف طول $\\boldsymbol{v}_x$."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.189Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
