from (values
('mcq', 1, 2, '$v_{yi} = (18.0)\sin 55.0^\circ = 14.7\ \text{m/s}$؛ وعند القمة $v_y = 0$: $y_{\text{max}} = \frac{v_{yi}^2}{2g} = \frac{(14.74\ \text{m/s})^2}{2(9.80\ \text{m/s}^2)} = 11.1\ \text{m}$.', '["استُعمل مقدار السرعة الابتدائية كاملًا بدل مركّبتها الرأسية.","استُعملت المركّبة الأفقية $v_i\\cos\\theta_i$ بدل الرأسية.","","نُسي العدد 2 في المقام $2g$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-21T13:36:33.190Z"}'::jsonb),
('mcq', 2, 0, '$v_{yi} = (24.0)\sin 45.0^\circ = 16.97\ \text{m/s}$؛ زمن الصعود $t = \frac{v_{yi}}{g} = 1.73\ \text{s}$؛ وزمن التحليق ضعفه: $2t = 3.46\ \text{s}$.', '["","هذا زمن الصعود إلى أقصى ارتفاع فقط، وزمن التحليق يساوي ضعفه.","استُعمل مقدار السرعة كاملًا $\\frac{2v_i}{g}$ بدل مركّبتها الرأسية.","قُسم مقدار السرعة كاملًا على $g$ دون تحليلها ودون مضاعفة الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-21T13:36:33.190Z"}'::jsonb),
('mcq', 3, 3, '$v_{yi} = (30.0)\sin 40.0^\circ = 19.28\ \text{m/s}$، فزمن التحليق $\frac{2v_{yi}}{g} = 3.935\ \text{s}$. و$v_x = (30.0)\cos 40.0^\circ = 22.98\ \text{m/s}$، فالمدى الأفقي $R = v_x t = (22.98)(3.935) = 90.4\ \text{m}$.', '["استُعمل زمن الصعود وحده بدل زمن التحليق كاملًا.","ضُرب زمن التحليق في المركّبة الرأسية بدل الأفقية.","ضُرب زمن التحليق في مقدار السرعة الابتدائية كاملًا بدل مركّبتها الأفقية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-21T13:36:33.191Z"}'::jsonb),
('mcq', 4, 1, '$v_{yi} = (15.0)\sin 30.0^\circ = 7.50\ \text{m/s}$، وزمن التحليق $\frac{2(7.50)}{9.80} = 1.531\ \text{s}$؛ و$v_x = (15.0)\cos 30.0^\circ = 12.99\ \text{m/s}$؛ فالمدى $R = (12.99)(1.531) = 19.9\ \text{m}$.', '["استُعمل زمن الصعود وحده، فنتج نصف المدى الأفقي.","","ضُرب زمن التحليق في المركّبة الرأسية $7.50\\ \\text{m/s}$ بدل الأفقية.","هذا أقصى ارتفاع $\\frac{v_{yi}^2}{2g}$ وليس المدى الأفقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-21T13:36:33.192Z"}'::jsonb),
('mcq', 5, 2, '$v_{yi} = (49)\sin 30.0^\circ = 24.5\ \text{m/s}$، وعند القمة $v_y = 0$: $t = \frac{v_{yi}}{g} = \frac{24.5}{9.80} = 2.5\ \text{s}$.', '["هذا زمن التحليق كاملًا (الصعود والنزول)، لا زمن الصعود.","استُعملت المركّبة الأفقية $v_i\\cos\\theta_i$ بدل الرأسية.","","قُسم زمن الصعود على 2 خطأً، كأن القمة في منتصف زمن الصعود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-21T13:36:33.192Z"}'::jsonb),
('mcq', 6, 0, 'عند القمة $v_y = 0$: $v_y^2 = v_{yi}^2 - 2g\,y_{\text{max}} \Rightarrow v_{yi} = \sqrt{2g\,y_{\text{max}}} = \sqrt{2(9.80)(5.0)} = 9.9\ \text{m/s}$.', '["","نُسي العدد 2: $\\sqrt{g\\,y_{\\text{max}}}$.","نُسي الجذر التربيعي: $2g\\,y_{\\text{max}} = 98$، وهذه وحدتها $\\text{m}^2/\\text{s}^2$.","نُسي الجذر والعدد 2 معًا: $g\\,y_{\\text{max}}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-21T13:36:33.193Z"}'::jsonb),
('mcq', 7, 3, '$v_x = (9.40)\cos 41.0^\circ = 7.094\ \text{m/s}$، و$v_{yi} = (9.40)\sin 41.0^\circ = 6.167\ \text{m/s}$. بأخذ نقطة الإطلاق أصلًا و+y إلى أعلى: $-1.60 = 6.167t - 4.90t^2$، فالجذر الموجب $t = 1.479\ \text{s}$. البعد الأفقي $x = v_x t = (7.094)(1.479) = 10.5\ \text{m}$.', '["أُهمل ارتفاع الإطلاق 1.60 m، فحُسب المدى كأن الكرة تعود إلى مستوى الإطلاق.","استُعمل زمن الصعود وحده لحساب البعد الأفقي.","أُضيف إلى زمن التحليق زمن سقوط حر من السكون مسافة 1.60 m، مع أن الكرة تبلغ مستوى الإطلاق ولها سرعة رأسية إلى أسفل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-21T13:36:33.193Z"}'::jsonb),
('essay', 1, null::int, null, null, '$v_{xi} = (22.0)\cos 35.0^\circ = 18.02\ \text{m/s}$، $v_{yi} = (22.0)\sin 35.0^\circ = 12.62\ \text{m/s}$. (a) زمن الصعود $\frac{12.62}{9.80} = 1.288\ \text{s}$، فزمن التحليق $2.58\ \text{s}$. (b) $y_{\text{max}} = \frac{v_{yi}^2}{2g} = \frac{(12.62)^2}{2(9.80)} = 8.12\ \text{m}$. (c) $R = v_x t = (18.02)(2.575) = 46.4\ \text{m}$.', '["تحليل السرعة الابتدائية إلى مركّبتين","زمن التحليق 2.58 s","أقصى ارتفاع 8.12 m","المدى الأفقي 46.4 m"]'::jsonb, '["$v_{xi} = v_i\\cos\\theta_i = 18.0\\ \\text{m/s}$، $v_{yi} = v_i\\sin\\theta_i = 12.6\\ \\text{m/s}$","زمن الصعود: $v_y = v_{yi} - gt = 0 \\Rightarrow t = 1.29\\ \\text{s}$؛ زمن التحليق $= 2t = 2.58\\ \\text{s}$","$y_{\\text{max}} = v_{yi}t - \\frac{1}{2}gt^2 = 8.12\\ \\text{m}$","$R = v_x \\times 2t = 46.4\\ \\text{m}$"]'::jsonb, '[{"element":"المركّبتان","marks":1},{"element":"زمن التحليق","marks":1},{"element":"أقصى ارتفاع","marks":1},{"element":"المدى الأفقي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الحسابات صحيحة بالوحدات والأرقام المعنوية"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال زمن الصعود بدل زمن التحليق في حساب المدى.","تبديل $\\sin$ و$\\cos$.","نسيان العدد 2 في $2g$."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-21T13:36:33.194Z"}'::jsonb),
('essay', 2, null::int, null, null, 'بأخذ حافة الجرف أصلًا و+y إلى أعلى: $v_x = (12.0)\cos 40.0^\circ = 9.19\ \text{m/s}$، $v_{yi} = (12.0)\sin 40.0^\circ = 7.71\ \text{m/s}$. (a) $y_{\text{max}} = \frac{(7.71)^2}{2(9.80)} = 3.04\ \text{m}$ فوق الحافة. (b) الموقع النهائي $y = -30.0\ \text{m}$: $-30.0 = 7.71t - 4.90t^2$، والجذر الموجب $t = 3.38\ \text{s}$. (c) $x = v_x t = (9.19)(3.38) = 31.1\ \text{m}$.', '["اختيار نظام محاور وإشارة الإزاحة الرأسية $-30.0\\ \\text{m}$","أقصى ارتفاع 3.04 m","حل المعادلة التربيعية: $t = 3.38\\ \\text{s}$","البعد الأفقي 31.1 m"]'::jsonb, '["$v_x = 9.19\\ \\text{m/s}$، $v_{yi} = 7.71\\ \\text{m/s}$","$y_{\\text{max}} = \\frac{v_{yi}^2}{2g} = 3.04\\ \\text{m}$","$\\Delta y = v_{yi}t - \\frac{1}{2}gt^2$ مع $\\Delta y = -30.0\\ \\text{m}$: $4.90t^2 - 7.71t - 30.0 = 0$","$t = \\frac{7.71 + \\sqrt{(7.71)^2 + 4(4.90)(30.0)}}{2(4.90)} = 3.38\\ \\text{s}$","$x = v_x t = 31.1\\ \\text{m}$"]'::jsonb, '[{"element":"إشارة الإزاحة ونظام المحاور","marks":1},{"element":"أقصى ارتفاع","marks":1},{"element":"الزمن","marks":1},{"element":"البعد الأفقي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح"},{"level":"3 درجات","description":"خطأ في عنصر واحد"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["أخذ الإزاحة الرأسية $+30.0\\ \\text{m}$.","استعمال زمن التحليق للمستوى نفسه $\\frac{2v_{yi}}{g}$.","إهمال المركّبة الرأسية الابتدائية وحساب الزمن كسقوط حر من السكون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-21T13:36:33.194Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $v_{yi} = (45.0)\sin 25.0^\circ = 19.02\ \text{m/s}$، $y_{\text{max}} = \frac{(19.02)^2}{2(9.80)} = 18.5\ \text{m}$. (b) زمن التحليق $\frac{2(19.02)}{9.80} = 3.881\ \text{s}$، و$v_x = (45.0)\cos 25.0^\circ = 40.78\ \text{m/s}$، فالبعد $R = (40.78)(3.881) = 158\ \text{m}$. (c) عند $65.0^\circ$: $v_{yi} = 40.78\ \text{m/s}$ و$v_x = 19.02\ \text{m/s}$، زمن التحليق $8.323\ \text{s}$، فالمدى $R = 158\ \text{m}$ (المدى نفسه)، وأقصى ارتفاع $\frac{(40.78)^2}{2(9.80)} = 84.9\ \text{m}$ (أكبر بكثير). فالزاويتان المتتامّتان تعطيان المدى الأفقي نفسه، والزاوية الأكبر تعطي ارتفاعًا وزمن تحليق أكبر.', '["أقصى ارتفاع 18.5 m","المدى 158 m","المدى عند $65.0^\\circ$ يساوي 158 m","أقصى ارتفاع عند $65.0^\\circ$ يساوي 84.9 m والمقارنة"]'::jsonb, '["$v_{yi} = 19.0\\ \\text{m/s}$، $v_x = 40.8\\ \\text{m/s}$","$y_{\\text{max}} = \\frac{v_{yi}^2}{2g} = 18.5\\ \\text{m}$","$t = \\frac{2v_{yi}}{g} = 3.88\\ \\text{s}$، $R = v_x t = 158\\ \\text{m}$","عند $65.0^\\circ$: $t = 8.32\\ \\text{s}$، $R = 158\\ \\text{m}$، $y_{\\text{max}} = 84.9\\ \\text{m}$"]'::jsonb, '[{"element":"أقصى ارتفاع","marks":1},{"element":"المدى الأفقي","marks":1},{"element":"حسابات الزاوية الثانية","marks":1},{"element":"المقارنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الحسابات والمقارنة صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب المدى بزمن الصعود فقط.","توقع أن الزاوية الأكبر تعطي دائمًا مدى أكبر.","تبديل المركّبتين عند الزاوية الثانية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-21T13:36:33.195Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
