insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L1-O13'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ماذا يحدث للمدى الأفقي لكرة حقيقية وأقصى ارتفاع تصل إليه عند أخذ مقاومة الهواء في الاعتبار، مقارنةً بالقيم المحسوبة بإهمالها؟', null, null, '["يزداد مداها الأفقي ويقل أقصى ارتفاع تصل إليه","يقل مداها الأفقي ويقل أقصى ارتفاع تصل إليه","لا يتغيران؛ لأن مقاومة الهواء قوة صغيرة دائمًا","يزداد مداها الأفقي ويزداد أقصى ارتفاع تصل إليه"]'::jsonb, 'فهم', 'أثر مقاومة الهواء', 'متوسط', 'الكتاب ص 166 — مقاومة الهواء'),
('mcq', 2, 'ما أثر النتوءات الصغيرة على سطح كرة الجولف في حركتها بعد ضربها؟', null, null, '["تقلل مقاومة الهواء فيزداد مداها الأفقي","تزيد مقاومة الهواء فيقل مداها الأفقي","تزيد كتلة الكرة فيقل تسارعها إلى أسفل","تلغي أثر الجاذبية في جزء من مسارها"]'::jsonb, 'فهم', 'تفسير تطبيق حياتي', 'سهل', 'الكتاب ص 166 — مقاومة الهواء'),
('mcq', 3, 'ما أثر دوران كرة البيسبول حول نفسها في أثناء طيرانها في الهواء؟', null, null, '["تتحرك في خط مستقيم لا ينحني إطلاقًا","ينعدم أثر الجاذبية الأرضية فيها تمامًا","تتأثر بقوى تؤدي إلى انحرافها عن مسارها","يبقى مسارها قطعًا مكافئًا تامًّا متماثلًا"]'::jsonb, 'فهم', 'تفسير تطبيق حياتي', 'متوسط', 'الكتاب ص 166 — مقاومة الهواء'),
('mcq', 4, 'أيّ العبارات الآتية عن مقاومة الهواء في حركة المقذوفات صحيحة؟', null, null, '["لا تؤثر إلا في الأجسام الساقطة سقوطًا رأسيًّا","مهملة دائمًا لجميع المقذوفات في الواقع","تزيد المدى الأفقي لجميع المقذوفات","موجودة دائمًا، وقد تكون مهمة لبعض المقذوفات"]'::jsonb, 'تذكر', 'حقيقة علمية', 'سهل', 'الكتاب ص 166 — مقاومة الهواء'),
('mcq', 5, 'أُطلقت الأجسام الآتية بالسرعة الابتدائية نفسها وبالزاوية نفسها. أيّها يُتوقع أن يحيد مساره الفعلي عن المسار المحسوب بإهمال مقاومة الهواء أكثر من غيره؟', null, null, '["كرة تنس طاولة خفيفة جوفاء","كرة فولاذية صغيرة مصمتة","حجر صغير مصمت ثقيل","كرة صغيرة من الرصاص"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'متوسط', 'الكتاب ص 166، 110 — مقاومة الهواء؛ القوة المعيقة والسرعة الحدية'),
('mcq', 6, 'عند أخذ مقاومة الهواء في الاعتبار، ماذا يحدث للمركّبة الأفقية لسرعة المقذوف في أثناء طيرانه؟', null, null, '["تبقى ثابتة؛ لعدم وجود قوة أفقية تؤثر فيه","تتزايد؛ لأن الهواء يدفع المقذوف إلى الأمام","تتناقص؛ لوجود قوة أفقية تعاكس حركته","تصبح صفرًا فور مغادرة المقذوف نقطة الإطلاق"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 166، 179 — مقاومة الهواء؛ دليل مراجعة الفصل'),
('mcq', 7, 'يبين الشكل الآتي مسارين للكرة نفسها أُطلقت بالسرعة الابتدائية نفسها: أحدهما محسوب بإهمال مقاومة الهواء، والآخر مسارها الفعلي مع وجودها. أيّ المسارين يمثّل حركتها مع مقاومة الهواء، ولماذا؟', null, '[{"src":"qimg/phys1/c6l1-o13-paths.svg","alt":"مساران لكرة أُطلقت من النقطة نفسها على سطح أفقي نحو اليمين. المسار (1) منحنى رمادي متقطع مرتفع وطويل. المسار (2) منحنى برتقالي متصل يبدأ متطابقًا تقريبًا مع (1) ثم يصل إلى قمة أخفض ويسقط على بعد أقصر بكثير من نقطة الإطلاق. ومكتوب أسفل الشكل: الكرة نفسها أُطلقت بالسرعة الابتدائية نفسها في الحالتين."}]'::jsonb, '["(1)؛ لأن مقاومة الهواء تزيد المدى الأفقي للكرة","(1)؛ لأن مقاومة الهواء تدفع الكرة إلى أعلى فيزداد ارتفاعها","(2)؛ لأن مقاومة الهواء تزيد تسارع الجاذبية الأرضية","(2)؛ لأن مقاومة الهواء تقلل المدى الأفقي وأقصى ارتفاع"]'::jsonb, 'تحليل', 'تفسير رسم', 'صعب', 'الكتاب ص 166 — مقاومة الهواء'),
('essay', 1, 'وضّح أثر مقاومة الهواء في المدى الأفقي لمقذوف حقيقي وفي أقصى ارتفاع يصل إليه، مقارنةً بالقيم المحسوبة بإهمالها، وبيّن نوع الأجسام التي يكون أثرها فيها كبيرًا، ثم فسّر لماذا نهمل مقاومة الهواء عادةً عند حل مسائل المقذوفات.', null, null, null, 'فهم', 'توضيح أثر', 'سهل', 'الكتاب ص 166، 110 — مقاومة الهواء؛ القوة المعيقة والسرعة الحدية'),
('essay', 2, 'تُصنع كرة الجولف وعلى سطحها نتوءات صغيرة، وتنحرف كرة البيسبول عن مسارها عندما تدور حول نفسها. وضّح أثر الهواء في كل من الحالتين في حركة الكرة، وبيّن ماذا تستنتج عن أهمية مقاومة الهواء في حركة المقذوفات.', null, null, null, 'فهم', 'تفسير تطبيقات', 'متوسط', 'الكتاب ص 166 — مقاومة الهواء'),
('essay', 3, 'حسب طالب المدى الأفقي لكرة قُذفت من مستوى الأرض بسرعة 27.0 m/s بزاوية $30.0^\circ$ فوق الأفقي، مُهملًا مقاومة الهواء، فوجده 64.4 m، لكنه عندما قاسه فعليًّا وجده نحو 52 m. (a) تحقّق حسابيًّا من القيمة 64.4 m. (b) فسّر الفرق بين القيمتين. (c) لو أُعيدت التجربة بكرة صغيرة ثقيلة مصمتة لها السرعة والزاوية نفسيهما، فهل تتوقع أن يقترب المدى المقيس من 64.4 m أم يبتعد؟ علّل.', null, null, null, 'تحليل', 'تفسير نتائج', 'صعب', 'الكتاب ص 166، 110 — المسألة 3؛ مقاومة الهواء؛ القوة المعيقة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L1-O13') and x.type = v.type and x.number = v.number);
