select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'مقاومة الهواء قوة تعاكس حركة الكرة، فتقلل سرعتها في أثناء الصعود وفي الاتجاه الأفقي؛ لذلك تصل إلى ارتفاع أقل وتقطع مسافة أفقية أقل مما يُحسب بإهمالها.', '["مقاومة الهواء تعاكس الحركة الأفقية أيضًا، فلا تزيد المدى الأفقي.","","مقاومة الهواء موجودة دائمًا وقد تكون كبيرة لبعض المقذوفات، فلا يصح إهمال أثرها مطلقًا.","مقاومة الهواء لا تُكسب الكرة طاقة أو سرعة إضافية، بل تعيق حركتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-21T13:36:33.196Z"}'::jsonb),
('mcq', 2, 0, 'تؤدي النتوءات الصغيرة على سطح كرة الجولف إلى تقليل مقاومة الهواء، ومن ثم إلى زيادة مداها الأفقي.', '["","هذا عكس الصحيح؛ فالنتوءات تقلل مقاومة الهواء.","تسارع السقوط لا يعتمد على الكتلة عند إهمال الهواء، والنتوءات تؤثر في مقاومة الهواء لا في الكتلة.","الجاذبية الأرضية تؤثر في الكرة طوال مسارها ولا تلغيها النتوءات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-21T13:36:33.197Z"}'::jsonb),
('mcq', 3, 2, 'دوران كرة البيسبول حول نفسها يجعلها تتأثر بقوى من الهواء تؤدي إلى انحرافها عن المسار الذي تسلكه لولا ذلك.', '["الجاذبية تؤثر في الكرة دائمًا فتنحني حركتها، والدوران يزيد الانحراف لا يلغيه.","الدوران لا يلغي الجاذبية الأرضية.","","القطع المكافئ التام هو المسار عند إهمال الهواء، والدوران يحرف الكرة عنه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-21T13:36:33.197Z"}'::jsonb),
('mcq', 4, 3, 'قوة مقاومة الهواء موجودة دائمًا، وقد تكون قليلة جدًّا لبعض المقذوفات وكبيرة لمقذوفات أخرى، فتكون مهمة في وصف حركتها.', '["مقاومة الهواء تؤثر في أي جسم يتحرك خلال الهواء، ومنها المقذوفات.","نهملها في المسائل للتبسيط فقط، لكنها موجودة في الواقع وقد تكون كبيرة.","مقاومة الهواء عادة تقلل المدى الأفقي لأنها تعاكس الحركة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-21T13:36:33.197Z"}'::jsonb),
('mcq', 5, 0, 'تكون مقاومة الهواء قليلة جدًّا تجاه بعض المقذوفات وكبيرة تجاه أخرى؛ فالأجسام الخفيفة ذات السطوح الكبيرة يكون للقوة المعيقة تأثير ملحوظ في حركتها، أما الأجسام الثقيلة ذات السطوح الصغيرة فتأثرها أقل كثيرًا. وكرة تنس الطاولة خفيفة جدًّا بالنسبة إلى حجمها، فيحيد مسارها كثيرًا عن المسار المحسوب.', '["","الكرة الفولاذية الصغيرة المصمتة جسم ثقيل ذو سطح صغير، فتأثرها بمقاومة الهواء أقل كثيرًا.","الحجر الصغير المصمت الثقيل جسم ثقيل ذو سطح صغير، فتأثره بمقاومة الهواء أقل كثيرًا.","كرة الرصاص الصغيرة ثقيلة وسطحها صغير، فتأثرها بمقاومة الهواء أقل كثيرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-21T13:36:33.198Z"}'::jsonb),
('mcq', 6, 2, 'ثبات المركّبة الأفقية مشروط بإهمال مقاومة الهواء. أما مع وجودها فتؤثر في المقذوف قوة تعاكس حركته لها مركّبة أفقية معاكسة لاتجاه حركته، فتتناقص مركّبة سرعته الأفقية تدريجيًّا.', '["هذا صحيح فقط عند إهمال مقاومة الهواء، وليس عند أخذها في الاعتبار.","مقاومة الهواء تعاكس الحركة ولا تدفع المقذوف إلى الأمام.","","مقاومة الهواء تُنقص المركّبة الأفقية تدريجيًّا ولا تلغيها فجأة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-21T13:36:33.198Z"}'::jsonb),
('mcq', 7, 3, 'المسار (2) أخفض وأقصر؛ لأن مقاومة الهواء قوة تعاكس حركة الكرة فتقلل أقصى ارتفاع تصل إليه ومداها الأفقي. أما المسار (1) فهو المسار المحسوب بإهمال مقاومة الهواء.', '["المسار (1) هو الأطول، ومقاومة الهواء تقلل المدى لا تزيده.","مقاومة الهواء تعاكس حركة الكرة ولا تدفعها في اتجاه حركتها، فتقلل أقصى ارتفاع لا تزيده.","المسار (2) هو الصحيح، لكن السبب خطأ؛ فمقاومة الهواء لا تغيّر تسارع الجاذبية الأرضية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-21T13:36:33.198Z"}'::jsonb),
('essay', 1, null::int, null, null, 'مقاومة الهواء قوة تعاكس حركة المقذوف فتقلل سرعته؛ لذلك يصل المقذوف الحقيقي إلى أقصى ارتفاع أقل، ويقطع مدى أفقيًّا أقصر من القيمتين المحسوبتين بإهمالها. ويكون أثرها كبيرًا في الأجسام الخفيفة ذات السطوح الكبيرة (مثل كرة تنس الطاولة)، وقليلًا في الأجسام الثقيلة ذات السطوح الصغيرة. ونهملها في المسائل لتبسيط الحل؛ لأنها تكون قليلة جدًّا لبعض المقذوفات، فتبقى القوة الوحيدة المؤثرة هي الجاذبية الأرضية ويكون التسارع ثابتًا. لكن يجب أن نتذكر أنها موجودة دائمًا وقد تكون مهمة.', '["مقاومة الهواء تعاكس الحركة","يقل المدى الأفقي وأقصى ارتفاع","أثرها كبير في الأجسام الخفيفة ذات السطوح الكبيرة، وقليل في الثقيلة ذات السطوح الصغيرة","سبب الإهمال: التبسيط وقلة أثرها لبعض المقذوفات مع وجودها دائمًا"]'::jsonb, '[]'::jsonb, '[{"element":"اتجاه مقاومة الهواء","marks":1},{"element":"أثرها في المدى والارتفاع","marks":1},{"element":"الأجسام الأكثر تأثرًا بها","marks":1},{"element":"سبب إهمالها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن مقاومة الهواء غير موجودة في الواقع.","القول إنها تزيد المدى الأفقي.","القول إنها تغيّر قيمة g."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.199Z"}'::jsonb),
('essay', 2, null::int, null, null, 'كرة الجولف: تؤدي النتوءات الصغيرة على سطحها إلى تقليل مقاومة الهواء، فيزداد مداها الأفقي. كرة البيسبول: دورانها حول نفسها يجعلها تتأثر بقوى من الهواء تؤدي إلى انحرافها عن مسارها. والاستنتاج: قوة مقاومة الهواء موجودة دائمًا، وقد تكون مهمة في تحديد مسار المقذوف ومداه، وإن كنا نهملها في المسائل.', '["النتوءات تقلل مقاومة الهواء","فيزداد المدى الأفقي لكرة الجولف","دوران كرة البيسبول يعرّضها لقوى تحرفها عن مسارها","الاستنتاج: مقاومة الهواء موجودة دائمًا وقد تكون مهمة"]'::jsonb, '[]'::jsonb, '[{"element":"أثر النتوءات في مقاومة الهواء","marks":1},{"element":"أثرها في المدى","marks":1},{"element":"أثر الدوران","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النتوءات تزيد مقاومة الهواء.","القول إن الدوران يزيد كتلة الكرة أو وزنها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-21T13:36:33.199Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $v_{yi} = (27.0)\sin 30.0^\circ = 13.5\ \text{m/s}$، زمن التحليق $\frac{2(13.5)}{9.80} = 2.755\ \text{s}$، $v_x = (27.0)\cos 30.0^\circ = 23.38\ \text{m/s}$، $R = (23.38)(2.755) = 64.4\ \text{m}$. (b) الحساب افترض أن القوة الوحيدة هي الجاذبية الأرضية؛ أما في الواقع فتؤثر مقاومة الهواء في الكرة معاكسةً حركتها، فتتناقص مركّبة سرعتها الأفقية ويقل أقصى ارتفاع تصل إليه، فيقل المدى الأفقي. (c) يقترب من 64.4 m؛ لأن الأجسام الثقيلة ذات السطوح الصغيرة يكون تأثرها بمقاومة الهواء أقل كثيرًا من الأجسام الخفيفة ذات السطوح الكبيرة.', '["التحقق من 64.4 m بخطوات صحيحة","إرجاع الفرق إلى مقاومة الهواء","بيان أن مقاومة الهواء تقلل المركّبة الأفقية وأقصى ارتفاع فيقل المدى","التوقع الصحيح للكرة الثقيلة مع التعليل"]'::jsonb, '["$v_{yi} = 13.5\\ \\text{m/s}$، $v_x = 23.4\\ \\text{m/s}$","زمن التحليق $= \\frac{2v_{yi}}{g} = 2.76\\ \\text{s}$","$R = v_x t = 64.4\\ \\text{m}$"]'::jsonb, '[{"element":"التحقق الحسابي","marks":1},{"element":"سبب الفرق","marks":1},{"element":"آلية نقص المدى","marks":1},{"element":"التوقع والتعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إرجاع الفرق إلى خطأ في قيمة g.","القول إن مقاومة الهواء تؤثر في الحركة الرأسية فقط.","توقع أن الكرة الثقيلة تسقط أسرع فيقل مداها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-21T13:36:33.200Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C6-L1-O13') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L1-O14'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أُسقطت برتقالة من ارتفاع معيّن في اللحظة نفسها التي أُطلقت فيها رصاصة أفقيًّا من بندقية من الارتفاع نفسه. أيّ العبارات الآتية صحيحة؟ (أهمل مقاومة الهواء، والأرض أفقية)', null, null, '["تصل البرتقالة إلى الأرض أولًا؛ لأنها أثقل من الرصاصة","تصلان إلى الأرض في اللحظة نفسها","تصل الرصاصة أولًا؛ لأن سرعتها كبيرة جدًّا","تصل البرتقالة أولًا؛ لأن الرصاصة تبقى في الهواء أطول"]'::jsonb, 'فهم', 'تطبيق مبدأ', 'سهل', 'الكتاب ص 183 — اختبار مقنن، السؤال 7'),
('mcq', 2, 'يبين الشكل الآتي صورًا متتالية بفترات زمنية متساوية لكرتين: A تسقط من السكون، وB قُذفت أفقيًّا في اللحظة نفسها ومن الارتفاع نفسه. علامَ يدل تساوي الموقعين الرأسيين للكرتين في كل صورة؟', null, '[{"src":"qimg/phys1/c6l1-o14-strobe.svg","alt":"صور متتالية لكرتين التُقطت بفترات زمنية متساوية. الكرة A (رمادية) على اليسار تسقط رأسيًّا من السكون، فتقع صورها على خط رأسي واحد وتتزايد المسافات بينها إلى أسفل. والكرة B (صفراء) قُذفت أفقيًّا نحو اليمين (سهم أحمر مكتوب عنده v_x) في اللحظة نفسها ومن الارتفاع نفسه، فتتباعد صورها أفقيًّا بمسافات متساوية. وتمر خطوط أفقية متقطعة بكل صورة للكرة A، وتقع كل صورة للكرة B على الخط الأفقي نفسه الذي تقع عليه صورة A المأخوذة في اللحظة نفسها."}]'::jsonb, '["الحركة الأفقية للكرة B لا تؤثر في حركتها الرأسية","سرعة B الأفقية تتناقص بالمعدل الذي تزداد به سرعة A","الكرة B لا تتأثر بالجاذبية حتى تتوقف حركتها الأفقية","الكرتان تتحركان رأسيًّا بسرعة متجهة ثابتة"]'::jsonb, 'فهم', 'تفسير رسم', 'متوسط', 'الكتاب ص 162 — الشكل 6-1'),
('mcq', 3, 'تغادر الكرتان A وB أفقيًّا حافتي طاولتين متماثلتين ارتفاع كل منهما 1.22 m في اللحظة نفسها، كما في الشكل الآتي. ما زمن سقوط كل منهما حتى تصل إلى الأرض؟ (أهمل مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$)', null, '[{"src":"qimg/phys1/c6l1-o14-table.svg","alt":"طاولتان متماثلتان ارتفاع كل منهما 1.22 m (سهم رأسي برأسين بجانب كل منهما). عند حافة الطاولة اليسرى الكرة A تغادرها أفقيًّا نحو اليمين بسرعة 1.0 m/s (سهم أحمر قصير)، وعند حافة الطاولة اليمنى الكرة B تغادرها أفقيًّا نحو اليمين بسرعة 2.0 m/s (سهم أحمر أطول). ومكتوب أسفل الشكل: تغادر الكرتان حافتي الطاولتين في اللحظة نفسها."}]'::jsonb, '["A: 0.499 s، وB: 0.250 s","A: 0.499 s، وB: 0.998 s","A: 0.499 s، وB: 0.499 s","A: 0.353 s، وB: 0.353 s"]'::jsonb, 'تطبيق', 'تطبيق مبدأ', 'متوسط', 'الكتاب ص 162، 181 — تجربة «السقوط من فوق الحافة»؛ السؤال 39'),
('mcq', 4, 'تتدحرج كرتان على سطح طاولة أفقي بالسرعة نفسها، وكتلة إحداهما ضعف كتلة الأخرى، وتغادران حافة الطاولة في اللحظة نفسها. أيّ العبارات الآتية صحيحة؟ (أهمل مقاومة الهواء)', null, null, '["تصل الكرة الأثقل أولًا وعلى بعد أقرب من الطاولة","تصلان معًا، لكن الكرة الأثقل تسقط على بعد أكبر","تصل الكرة الأخف أولًا؛ لأنها أسهل حركة","تصلان معًا وعلى البعد الأفقي نفسه من الطاولة"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 162 — تجربة «السقوط من فوق الحافة» (السؤال 5)'),
('mcq', 5, 'من الارتفاع نفسه وفي اللحظة نفسها، قُذفت كرة A أفقيًّا بسرعة 4.0 m/s، وتُركت كرة B تسقط من السكون. ما مقدار المركّبة الرأسية لسرعة كل منهما بعد 0.50 s (قبل وصولهما إلى الأرض)؟ (أهمل مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$)', null, null, '["A: 4.9 m/s، وB: 4.9 m/s","A: 8.9 m/s، وB: 4.9 m/s","A: 0 m/s، وB: 4.9 m/s","A: 6.3 m/s، وB: 4.9 m/s"]'::jsonb, 'تطبيق', 'تفسير', 'متوسط', 'الكتاب ص 162–163 — استقلالية الحركة في بعدين؛ الشكل 6-2'),
('mcq', 6, 'بماذا تشبه الحركة الرأسية لجسم قُذف أفقيًّا من ارتفاع ما؟ (أهمل مقاومة الهواء)', null, null, '["حركة جسم يتحرك بسرعة متجهة ثابتة","حركة جسم ينزلق على سطح أفقي أملس","حركة جسم يسقط رأسيًّا من السكون","حركة جسم قُذف رأسيًّا إلى أعلى"]'::jsonb, 'تذكر', 'مقارنة حركتين', 'سهل', 'الكتاب ص 162 — استقلالية الحركة في بعدين'),
('mcq', 7, 'يبين الشكل الآتي أربع صور متتالية لكرة B قُذفت أفقيًّا. لو تُركت كرة A تسقط من السكون من موقع الصورة (1) نفسه وفي لحظة قذف B نفسها، فأين تكون A لحظة التقاط الصورة (4)؟ (أهمل مقاومة الهواء)', null, '[{"src":"qimg/phys1/c6l1-o14-grid.svg","alt":"شبكة مربعات، ومكتوب أسفلها: الفترة الزمنية بين كل صورتين متتاليتين 0.10 s، وطول ضلع المربع في الشبكة 0.10 m. عليها أربع صور متتالية مرقّمة (1) إلى (4) لكرة B قُذفت أفقيًّا نحو اليمين، ومكتوب فوق كل صورة موقعها الأفقي x (m): 0.00 ثم 0.30 ثم 0.60 ثم 0.90. وتنخفض الصور رأسيًّا بمسافات متزايدة: الصورة (1) عند الخط العلوي، و(2) أسفل منه بنحو نصف مربع، و(3) بنحو مربعين، و(4) بنحو أربعة مربعات ونصف."}]'::jsonb, '["تحت موقع الصورة (1) مباشرة، وأعلى من الصورة (4)","تحت موقع الصورة (1) مباشرة، وعلى ارتفاع الصورة (4) نفسه","تحت موقع الصورة (1) مباشرة، وأسفل من الصورة (4)","عند موقع الصورة (4) نفسه تمامًا"]'::jsonb, 'تحليل', 'قراءة رسم وحساب', 'صعب', 'الكتاب ص 161–162 — التجربة الاستهلالية؛ الشكل 6-1'),
('essay', 1, 'في تجربة، أُسقطت كرة من السكون، وقُذفت كرة أخرى أفقيًّا في اللحظة نفسها ومن الارتفاع نفسه، وصُوّرتا بفترات زمنية متساوية. صف ما تلاحظه في المواقع الرأسية والأفقية للكرتين، ثم وضّح ما تستنتجه عن الحركتين الأفقية والرأسية للمقذوف.', null, null, null, 'فهم', 'وصف واستنتاج', 'سهل', 'الكتاب ص 162 — استقلالية الحركة في بعدين'),
('essay', 2, 'من فوق سطح ارتفاعه 4.90 m، تُركت كرة A لتسقط من السكون، وقُذفت كرة B أفقيًّا بسرعة 3.0 m/s في اللحظة نفسها. (أهمل مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$) (a) احسب زمن وصول كل كرة إلى الأرض. (b) على أيّ بعد أفقي من نقطة الإطلاق تسقط B؟ (c) لو ضوعفت سرعة B الأفقية، فكيف يتغير زمن سقوطها وبعدها الأفقي؟ فسّر.', null, null, null, 'تحليل', 'مسألة ومقارنة', 'صعب', 'الكتاب ص 162–164 — استقلالية الحركة في بعدين؛ مسائل تدريبية 1'),
('essay', 3, 'قُذفت كرة أفقيًّا من فوق حافة طاولة. ارسم مخططين منفصلين لحركتها بنموذج الجسيم النقطي: أحدهما للحركة الأفقية والآخر للحركة الرأسية، مبيّنًا متجهات السرعة والتسارع، ثم وضّح كيف يتكوّن المسار المنحني من الحركتين معًا.', null, null, null, 'فهم', 'رسم مخططات وتفسير', 'متوسط', 'الكتاب ص 163 — الشكل 6-2 واستراتيجيات حل المسألة: الحركة في بعدين')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L1-O14') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الحركتان الأفقية والرأسية مستقلتان؛ فللبرتقالة والرصاصة السرعة الرأسية الابتدائية نفسها (صفر) والتسارع الرأسي نفسه $g$ والارتفاع نفسه، فتستغرقان الزمن نفسه للوصول إلى الأرض، ولا تؤثر السرعة الأفقية للرصاصة في زمن سقوطها.', '["تسارع السقوط $g$ لا يعتمد على الكتلة.","","السرعة الأفقية لا تؤثر في الحركة الرأسية، فلا تُسرع وصول الرصاصة.","السرعة الأفقية تزيد المسافة الأفقية فقط، ولا تطيل زمن السقوط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-21T13:36:33.201Z"}'::jsonb),
('mcq', 2, 0, 'ارتفاعا الكرتين متساويان في كل لحظة، فسرعتاهما الرأسيتان متساويتان؛ وهذا يعني أن الحركة الأفقية للكرة B لم تؤثر في حركتها الرأسية، أي إن الحركتين مستقلتان.', '["","المسافات الأفقية بين صور B متساوية، فسرعتها الأفقية ثابتة لا تتناقص.","الكرة B تنخفض مع A منذ اللحظة الأولى، فهي تتأثر بالجاذبية طوال الوقت.","المسافات الرأسية بين الصور تتزايد، فالحركة الرأسية متسارعة لا منتظمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-21T13:36:33.201Z"}'::jsonb),
('mcq', 3, 2, 'لكل من الكرتين $v_{yi} = 0$ والتسارع الرأسي $g$ نفسه والمسافة الرأسية نفسها، والحركة الرأسية مستقلة عن الأفقية: $1.22\ \text{m} = \frac{1}{2}(9.80\ \text{m/s}^2)t^2 \Rightarrow t = \sqrt{\frac{2(1.22\ \text{m})}{9.80\ \text{m/s}^2}} = 0.499\ \text{s}$ للكرتين؛ وتسقط B على بعد أفقي أكبر فقط.', '["عُدّ زمن السقوط متناسبًا عكسيًّا مع السرعة الأفقية؛ ومضاعفة السرعة الأفقية لا تغيّر الحركة الرأسية.","عُدّت الكرة B تحتاج زمنًا أطول لأنها تقطع مسافة أفقية أكبر؛ والزمن تحدده الحركة الرأسية وحدها.","","نُسي العدد 2 في $t = \\sqrt{\\frac{2|\\Delta y|}{g}}$، مع أن تساوي الزمنين صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.202Z"}'::jsonb),
('mcq', 4, 3, 'الكتلة لا تؤثر في حركة المقذوف: تسارع الكرتين الرأسي $g$، فزمنا سقوطهما متساويان؛ ولهما السرعة الأفقية الثابتة نفسها، فتقطعان المسافة الأفقية نفسها في الزمن نفسه. لذلك تصلان معًا وعلى البعد الأفقي نفسه من الطاولة.', '["تسارع السقوط $g$ لا يعتمد على الكتلة، فلا تصل الأثقل أولًا.","البعد الأفقي $= v_x t$، والكرتان لهما $v_x$ و$t$ متساويان، فالكتلة لا تزيد البعد.","الكتلة لا تظهر في معادلات حركة المقذوف، فلا تصل الأخف أولًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-21T13:36:33.202Z"}'::jsonb),
('mcq', 5, 0, 'لكل من الكرتين $v_{yi} = 0$ والتسارع الرأسي نفسه $g$، والحركة الأفقية للكرة A لا تؤثر في حركتها الرأسية: مقدار $v_y = gt = (9.80\ \text{m/s}^2)(0.50\ \text{s}) = 4.9\ \text{m/s}$ إلى أسفل لكل منهما.', '["","أُضيفت السرعة الأفقية 4.0 m/s إلى المركّبة الرأسية، مع أن الحركتين مستقلتان.","عُدّت A بلا مركّبة رأسية لأنها قُذفت أفقيًّا، مع أنها تتسارع إلى أسفل مثل B تمامًا.","هذا مقدار السرعة الكلية للكرة A $\\sqrt{(4.0)^2 + (4.9)^2}$، لا مركّبتها الرأسية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-21T13:36:33.203Z"}'::jsonb),
('mcq', 6, 2, 'الجسم المقذوف أفقيًّا ليس له سرعة ابتدائية رأسية، فحركته الرأسية تشبه حركة جسم يسقط رأسيًّا من السكون، وتتزايد سرعته إلى أسفل بانتظام بسبب الجاذبية الأرضية.', '["هذا وصف الحركة الأفقية للمقذوف لا الرأسية.","الانزلاق على سطح أفقي أملس يشبه الحركة الأفقية للمقذوف.","","المقذوف أفقيًّا ليس له سرعة رأسية ابتدائية إلى أعلى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.203Z"}'::jsonb),
('mcq', 7, 1, 'الحركتان الأفقية والرأسية مستقلتان: للكرتين السرعة الرأسية الابتدائية نفسها (صفر) والتسارع نفسه $g$، فتنخفضان المسافة الرأسية نفسها في كل لحظة؛ فبعد 0.30 s تكون كل منهما قد انخفضت $\frac{1}{2}(9.80\ \text{m/s}^2)(0.30\ \text{s})^2 = 0.44\ \text{m}$. وليس للكرة A سرعة أفقية فتبقى عند $x = 0.00\ \text{m}$. لذلك تكون A تحت موقع الصورة (1) مباشرة، وعلى ارتفاع الصورة (4) نفسه.', '["عُدّت السرعة الأفقية للكرة B كأنها تزيد سرعة سقوطها؛ والحركتان مستقلتان فتنخفض الكرتان معًا.","","عُدّت الحركة الأفقية للكرة B كأنها تُبطئ سقوطها؛ والحركة الأفقية لا تؤثر في الحركة الرأسية.","الكرة A تسقط من السكون فلا حركة أفقية لها؛ فتبقى عند $x = 0.00\\ \\text{m}$ ولا تنتقل أفقيًّا مع B."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-21T13:36:33.204Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المواقع الرأسية للكرتين متساوية في كل لحظة، والمسافات الرأسية التي تقطعانها متزايدة؛ فالحركة الرأسية متسارعة إلى أسفل بسبب الجاذبية الأرضية، وهي متماثلة للكرتين. أما الكرة المقذوفة أفقيًّا فتقطع مسافات أفقية متساوية في فترات متساوية، أي إن سرعتها الأفقية ثابتة. نستنتج أن الحركتين الأفقية والرأسية للمقذوف مستقلتان: فالحركة الأفقية لم تؤثر في الحركة الرأسية، والحركة الرأسية للمقذوف أفقيًّا تشبه السقوط من السكون.', '["المواقع الرأسية متساوية في كل لحظة","المسافات الرأسية متزايدة (حركة متسارعة)","المسافات الأفقية متساوية (سرعة أفقية ثابتة)","الاستنتاج: الحركتان مستقلتان"]'::jsonb, '[]'::jsonb, '[{"element":"المواقع الرأسية","marks":1},{"element":"طبيعة الحركة الرأسية","marks":1},{"element":"طبيعة الحركة الأفقية","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف واستنتاج كاملان"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكرة المقذوفة أفقيًّا تسقط أبطأ.","وصف الحركة الرأسية بأنها منتظمة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-21T13:36:33.204Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) لكل من الكرتين $v_{yi} = 0$ والإزاحة الرأسية $-4.90\ \text{m}$: $t = \sqrt{\frac{2(4.90)}{9.80}} = 1.00\ \text{s}$ للكرتين. (b) $x = v_x t = (3.0)(1.00) = 3.0\ \text{m}$. (c) يبقى الزمن 1.00 s؛ لأن الحركة الرأسية مستقلة عن الأفقية ولم يتغير فيها شيء، ويتضاعف البعد الأفقي إلى 6.0 m لأن $x = v_x t$.', '["زمن السقوط 1.00 s للكرتين","البعد الأفقي 3.0 m","الزمن لا يتغير عند مضاعفة السرعة الأفقية مع التفسير","البعد الأفقي يصبح 6.0 m"]'::jsonb, '["$\\Delta y = -\\frac{1}{2}gt^2 \\Rightarrow t = \\sqrt{\\frac{2(4.90\\ \\text{m})}{9.80\\ \\text{m/s}^2}} = 1.00\\ \\text{s}$","$x = v_x t = (3.0\\ \\text{m/s})(1.00\\ \\text{s}) = 3.0\\ \\text{m}$","عند $v_x = 6.0\\ \\text{m/s}$: $t = 1.00\\ \\text{s}$، $x = 6.0\\ \\text{m}$"]'::jsonb, '[{"element":"الزمن","marks":1},{"element":"البعد الأفقي","marks":1},{"element":"أثر مضاعفة السرعة في الزمن مع التفسير","marks":1},{"element":"البعد الجديد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب زمن أطول للكرة B لأنها «تقطع مسافة أكبر».","القول إن مضاعفة السرعة الأفقية تقلل زمن السقوط.","نسيان الجذر التربيعي في حساب الزمن."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-21T13:36:33.204Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المخطط الأفقي: نقاط متباعدة بمسافات متساوية في فترات زمنية متساوية، وعند كل نقطة سهم سرعة أحمر $\boldsymbol{v}_x$ بالطول نفسه، والتسارع الأفقي صفر ($a_x = 0$). المخطط الرأسي: نقاط تتزايد المسافات بينها إلى أسفل، وأسهم سرعة حمراء $\boldsymbol{v}_y$ إلى أسفل تتزايد أطوالها، وسهم تسارع بنفسجي ثابت إلى أسفل مقداره $g$. وفي كل لحظة يُجمع المتجهان $\boldsymbol{v}_x$ و$\boldsymbol{v}_y$ اتجاهيًّا فتنتج السرعة المتجهة الكلية المماسّة للمسار؛ فالسرعة الأفقية الثابتة مع التسارع الرأسي المنتظم ينتجان معًا مسارًا على شكل قطع مكافئ.', '["مخطط أفقي بمسافات متساوية وسرعة ثابتة وتسارع صفر","مخطط رأسي بمسافات متزايدة وسرعة متزايدة","تسارع رأسي ثابت إلى أسفل","الجمع الاتجاهي للمركّبتين يعطي المسار المنحني"]'::jsonb, '[]'::jsonb, '[{"element":"المخطط الأفقي","marks":1},{"element":"المخطط الرأسي","marks":1},{"element":"التسارع","marks":1},{"element":"تكوين المسار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مخططان صحيحان مع تفسير تكوين المسار"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم مسافات أفقية متناقصة.","رسم تسارع أفقي.","رسم المسافات الرأسية متساوية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-21T13:36:33.205Z"}'::jsonb)
