('mcq', 5, 'ما الشكل الذي يتخذه مسار المقذوف عند إهمال مقاومة الهواء؟', null, null, '["خط مستقيم مائل","قطع مكافئ","دائرة كاملة","خط مستقيم رأسي"]'::jsonb, 'تذكر', 'حقيقة علمية', 'سهل', 'الكتاب ص 179 — دليل مراجعة الفصل 6-1'),
('mcq', 6, 'ما الرمزان اللذان يُستعملان للمدى الأفقي ولأقصى ارتفاع، على الترتيب، في معادلات حركة المقذوف؟', null, null, '["$y_{\\text{max}}$ و$R$","$R$ و$\\theta_i$","$R$ و$y_{\\text{max}}$","$t$ و$y_{\\text{max}}$"]'::jsonb, 'تذكر', 'رمز', 'متوسط', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('mcq', 7, 'أيّ الأزواج الآتية يتضمّن كمية تُقاس بالمتر ثم كمية تُقاس بالثانية، على الترتيب؟', null, null, '["زمن التحليق، ثم أقصى ارتفاع","زاوية الإطلاق، ثم المدى الأفقي","أقصى ارتفاع، ثم زاوية الإطلاق","المدى الأفقي، ثم زمن التحليق"]'::jsonb, 'فهم', 'تمييز كميات', 'صعب', 'الكتاب ص 164–165 — المقذوفات التي تطلق بزاوية؛ مثال 1'),
('essay', 1, 'عرّف كلًّا من: المقذوف، ومسار المقذوف، والمدى الأفقي، وزمن التحليق.', null, null, null, 'تذكر', 'تعريف مصطلحات', 'متوسط', 'الكتاب ص 161، 164 — المفردات'),
('essay', 2, 'يبين الشكل الآتي حركة كرة قُذفت من سطح أرض أفقي. (a) سمِّ ما يمثله كلٌّ من (1) و(2) وعرّفه. (b) ماذا تمثّل القيمة 2.9 s في حركة الكرة؟ عرّف هذه الكمية. (c) لماذا لا يُمثَّل زمن التحليق بخط على الرسم كما يُمثَّل المدى الأفقي؟', null, '[{"src":"qimg/phys1/c6l1-o15-blanks.svg","alt":"منحنى متصل على شكل قوس يبدأ من نقطة على أرض أفقية مكتوب عندها t = 0 s وينتهي عند نقطة أخرى على الأرض مكتوب عندها t = 2.9 s. يشير إلى المنحنى سهم مكتوب عنده (1). وتحت الأرض سهم أفقي برأسين يمتد بين نقطتي البداية والنهاية مكتوب عنده (2)."}]'::jsonb, null, 'فهم', 'تسمية وتعريف', 'صعب', 'الكتاب ص 161، 164 — المفردات والشكل 6-3b'),
('essay', 3, 'ميّز بين الكميات الثلاث: أقصى ارتفاع، والمدى الأفقي، وزمن التحليق، من حيث: نوع الكمية (مسافة رأسية، مسافة أفقية، زمن)، ورمزها، ووحدة قياسها، وأين تظهر على مسار المقذوف.', null, null, null, 'فهم', 'مقارنة مصطلحات', 'صعب', 'الكتاب ص 164–165 — المقذوفات التي تطلق بزاوية؛ مثال 1')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
