from (values
('mcq', 1, 0, 'المدى الأفقي $R$ هو المسافة الأفقية التي يقطعها المقذوف.', '["","أقصى ارتفاع مسافة رأسية بين مستوى الإطلاق وأعلى نقطة، لا أفقية.","زمن التحليق كمية زمنية لا مسافة.","مسار المقذوف هو المنحنى الذي يتحرك عليه، لا المسافة الأفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-21T13:36:33.206Z"}'::jsonb),
('mcq', 2, 2, 'زمن التحليق هو الزمن الذي يقضيه المقذوف في الهواء، من لحظة إطلاقه حتى سقوطه.', '["هذا زمن الصعود فقط، وهو جزء من زمن التحليق.","هذا أيضًا زمن الصعود عند العودة إلى المستوى نفسه، لا الزمن الكلي في الهواء.","","زمن التحليق يبدأ بعد مغادرة المقذوف للقاذف، لا في أثناء الإطلاق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-21T13:36:33.206Z"}'::jsonb),
('mcq', 3, 1, 'حركة الجسم المقذوف في الهواء على هذا المنحنى تُسمّى مسار المقذوف، وشكله قطع مكافئ.', '["المدى الأفقي مسافة أفقية على مستوى الإطلاق، لا المنحنى نفسه.","","منحنى (الموقع – الزمن) رسم بياني محوره الأفقي الزمن، أما الشكل فيبين المسار في الفضاء.","أقصى ارتفاع مسافة رأسية تمثّل نقطة واحدة من المسار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-21T13:36:33.206Z"}'::jsonb),
('mcq', 4, 3, 'زمن التحليق هو الزمن الذي يقضيه المقذوف في الهواء، من لحظة إطلاقه حتى سقوطه؛ وهو هنا 2.4 s، أي مجموع زمن الصعود وزمن النزول.', '["زمن الصعود هو 1.2 s فقط، من الإطلاق حتى أقصى ارتفاع.","زمن النزول من أقصى ارتفاع إلى الأرض هو 1.2 s فقط.","الزمن الدوري كمية في الحركة الدائرية (زمن دورة كاملة)، لا في حركة المقذوف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-21T13:36:33.206Z"}'::jsonb),
('mcq', 5, 1, 'السرعة الأفقية الثابتة والتسارع الرأسي المنتظم ينتجان معًا مسارًا منحنيًا يُسمّى القطع المكافئ.', '["الجاذبية تغيّر اتجاه السرعة باستمرار، فلا يكون المسار مستقيمًا.","","الدائرة مسار الحركة الدائرية، لا المقذوف.","المسار الرأسي المستقيم يكون فقط عند انعدام المركّبة الأفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-21T13:36:33.207Z"}'::jsonb),
('mcq', 6, 2, 'يُرمز للمدى الأفقي بالرمز $R$، ولأقصى ارتفاع بالرمز $y_{\text{max}}$.', '["عُكس الترتيب: $y_{\\text{max}}$ لأقصى ارتفاع و$R$ للمدى الأفقي.","$\\theta_i$ رمز زاوية الإطلاق لا أقصى ارتفاع.","","$t$ رمز الزمن لا المدى الأفقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-21T13:36:33.207Z"}'::jsonb),
('mcq', 7, 3, 'المدى الأفقي مسافة أفقية تُقاس بالمتر (m)، وزمن التحليق زمن يُقاس بالثانية (s).', '["الترتيب معكوس: زمن التحليق بالثانية وأقصى ارتفاع بالمتر.","زاوية الإطلاق تُقاس بالدرجات، لا بالمتر.","زاوية الإطلاق تُقاس بالدرجات، لا بالثانية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-21T13:36:33.207Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المقذوف: الجسم الذي يُطلق في الهواء. مسار المقذوف: حركة الجسم المقذوف في الهواء على شكل منحنٍ (قطع مكافئ). المدى الأفقي $R$: المسافة الأفقية التي يقطعها المقذوف. زمن التحليق: الزمن الذي يقضيه المقذوف في الهواء.', '["تعريف المقذوف","تعريف مسار المقذوف","تعريف المدى الأفقي","تعريف زمن التحليق"]'::jsonb, '[]'::jsonb, '[{"element":"المقذوف","marks":1},{"element":"مسار المقذوف","marks":1},{"element":"المدى الأفقي","marks":1},{"element":"زمن التحليق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعريفات الأربعة صحيحة"},{"level":"3 درجات","description":"ثلاثة تعريفات صحيحة"},{"level":"درجتان","description":"تعريفان صحيحان"},{"level":"درجة واحدة","description":"تعريف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف زمن التحليق بأنه زمن الصعود فقط.","تعريف المدى الأفقي بأنه طول المسار المنحني."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.207Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) (1) مسار المقذوف: حركة الجسم المقذوف في الهواء على شكل منحنٍ. (2) المدى الأفقي: المسافة الأفقية التي يقطعها المقذوف. (b) 2.9 s زمن التحليق، وهو الزمن الذي يقضيه المقذوف في الهواء، من لحظة الإطلاق ($t = 0\ \text{s}$) حتى السقوط. (c) لأن زمن التحليق كمية زمنية تُقاس بالثانية، والرسم يمثّل مواقع ومسافات في الفضاء تُقاس بالمتر؛ فيُكتب الزمن عند النقاط ولا يُرسم طولًا.', '["(1) مسار المقذوف مع تعريفه","(2) المدى الأفقي مع تعريفه","2.9 s زمن التحليق مع تعريفه","التمييز بين كمية زمنية ومسافة"]'::jsonb, '[]'::jsonb, '[{"element":"(1)","marks":1},{"element":"(2)","marks":1},{"element":"زمن التحليق","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية (2) أقصى ارتفاع.","عدّ 2.9 s زمن الصعود."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-21T13:36:33.208Z"}'::jsonb),
('essay', 3, null::int, null, null, 'أقصى ارتفاع $y_{\text{max}}$: مسافة رأسية تُقاس بالمتر (m)، من مستوى الإطلاق إلى أعلى نقطة في المسار حيث تكون السرعة أفقية فقط. المدى الأفقي $R$: مسافة أفقية تُقاس بالمتر (m)، بين نقطة الإطلاق ونقطة السقوط. زمن التحليق: كمية زمنية تُقاس بالثانية (s)، من لحظة الإطلاق حتى لحظة السقوط، ولا تُمثَّل بطول على المسار.', '["أقصى ارتفاع: مسافة رأسية، $y_{\\text{max}}$، m، عند القمة","المدى الأفقي: مسافة أفقية، $R$، m، بين الإطلاق والسقوط","زمن التحليق: زمن، s، من الإطلاق إلى السقوط"]'::jsonb, '[]'::jsonb, '[{"element":"أقصى ارتفاع","marks":1},{"element":"المدى الأفقي","marks":1},{"element":"زمن التحليق","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تمييز صحيح للكميات الثلاث"},{"level":"درجتان","description":"تمييز صحيح لكميتين"},{"level":"درجة واحدة","description":"تمييز صحيح لكمية واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قياس زمن التحليق بالمتر.","الخلط بين رمزي $R$ و$y_{\\text{max}}$."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.208Z"}'::jsonb)
