('mcq', 1, 'يبين الشكل الآتي كرة قُذفت من سطح أرض أفقي فوصلت إلى أقصى ارتفاع بعد 1.4 s من قذفها، ثم عادت إلى مستوى الإطلاق نفسه. ما زمن تحليقها؟ (أهمل مقاومة الهواء)', null, '[{"src":"qimg/phys1/c6l1-o16-times.svg","alt":"مسار منحنٍ متقطع لكرة قُذفت من سطح أرض أفقي وعادت إليه. عند نقطة الإطلاق مكتوب t = 0 s، وعند أعلى نقطة في المسار مكتوب t = 1.4 s. ولا يوجد أي رقم عند نقطة السقوط."}]'::jsonb, '["1.4 s","0.70 s","2.8 s","4.2 s"]'::jsonb, 'تطبيق', 'استعمال التماثل', 'سهل', 'الكتاب ص 165 — مثال 1: تحليل كرة'),
('mcq', 2, 'قُذفت كرة رأسيًّا إلى أعلى بسرعة متجهة مقدارها 20 m/s. ما مقدار سرعتها لحظة عودتها إلى نقطة الإطلاق نفسها؟ (أهمل مقاومة الهواء)', null, null, '["20 m/s","0 m/s","10 m/s","40 m/s"]'::jsonb, 'فهم', 'تطبيق التماثل', 'سهل', 'الكتاب ص 180 — السؤال 33'),
('mcq', 3, 'في أثناء صعود كرة مقذوفة من سطح أرض أفقي مرّت بارتفاع معيّن بعد 0.40 s من قذفها، وكان زمن تحليقها حتى عودتها إلى الأرض 3.0 s. متى تمرّ بالارتفاع نفسه في أثناء نزولها؟ (أهمل مقاومة الهواء)', null, null, '["0.80 s","2.6 s","1.5 s","3.4 s"]'::jsonb, 'تحليل', 'استدلال بالتماثل', 'صعب', 'الكتاب ص 164–165 — التماثل؛ مثال 1'),
('mcq', 4, 'يبين الشكل الآتي مركّبتي السرعة المتجهة لكرة مقذوفة عند النقطة A في أثناء صعودها. ما مركّبتا سرعتها عند النقطة E الواقعة على الارتفاع نفسه في أثناء نزولها؟ (أهمل مقاومة الهواء)', null, '[{"src":"qimg/phys1/c6l1-o16-AE.svg","alt":"مسار منحنٍ متقطع لكرة قُذفت من سطح أرض أفقي نحو اليمين وعادت إليه. النقطة A على الجزء الصاعد، والنقطة E على الجزء النازل على الارتفاع نفسه (يصل بينهما خط أفقي متقطع). عند A سهمان أحمران: أفقي نحو اليمين مكتوب عنده v_x = 8.0 m/s، ورأسي إلى أعلى مكتوب عنده v_y = 6.0 m/s. أما عند E فلا توجد أسهم. وفي الزاوية العليا سهما المحورين +x و+y."}]'::jsonb, '["$v_x = 8.0\\ \\text{m/s}$، و$v_y = 6.0\\ \\text{m/s}$ إلى أعلى","$v_x = 6.0\\ \\text{m/s}$، و$v_y = 8.0\\ \\text{m/s}$ إلى أسفل","$v_x = 0\\ \\text{m/s}$، و$v_y = 10\\ \\text{m/s}$ إلى أسفل","$v_x = 8.0\\ \\text{m/s}$، و$v_y = 6.0\\ \\text{m/s}$ إلى أسفل"]'::jsonb, 'فهم', 'تطبيق التماثل على رسم', 'متوسط', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('mcq', 5, 'قُذفت كرة من سطح أرض أفقي في اتجاه يصنع زاوية $35^\circ$ فوق الأفقي، وعادت إلى المستوى نفسه. ما اتجاه سرعتها المتجهة لحظة ارتطامها بالأرض؟ (أهمل مقاومة الهواء)', null, null, '["$35^\\circ$ تحت الأفقي في اتجاه الحركة","$35^\\circ$ فوق الأفقي في اتجاه الحركة","$55^\\circ$ تحت الأفقي في اتجاه الحركة","رأسيًّا إلى أسفل تمامًا"]'::jsonb, 'تحليل', 'استنتاج بالتماثل', 'متوسط', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('mcq', 6, 'متى يكون زمن صعود المقذوف مساويًا لزمن نزوله؟', null, null, '["عندما يُقذف من فوق بناية مرتفعة بزاوية فوق الأفقي","عندما يُقذف بزاوية $45^\\circ$ فقط مع الأفقي","عندما تؤثر فيه مقاومة هواء كبيرة في أثناء حركته","عندما يعود إلى مستوى إطلاقه بإهمال مقاومة الهواء"]'::jsonb, 'فهم', 'شرط التماثل', 'متوسط', 'الكتاب ص 165 — مثال 1: تحليل كرة'),
('mcq', 7, 'قُذفت كرة بزاوية فوق سطح أرض أفقي فعادت إليه بعد 4.00 s. ما أقصى ارتفاع وصلت إليه؟ (أهمل مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$)', null, null, '["78.4 m","39.2 m","19.6 m","9.80 m"]'::jsonb, 'تطبيق', 'استدلال بالتماثل', 'متوسط', 'الكتاب ص 165 — مثال 1: تحليل كرة'),
('essay', 1, 'يبين الشكل الآتي المركّبة الرأسية لسرعة كرة قُذفت من سطح أرض أفقي عند بعض نقاط مسارها، وقد وصلت إلى النقطة B بعد 0.50 s من قذفها. (أهمل مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$) (a) احسب الزمن الذي تصل فيه الكرة إلى C. (b) مستعينًا بتماثل الحركة، حدّد زمن الوصول إلى D وإلى E، والمركّبة الرأسية للسرعة عند كل منهما. (c) ما زمن التحليق؟', null, '[{"src":"qimg/phys1/c6l1-o16-heights.svg","alt":"مسار منحنٍ متقطع لكرة قُذفت من سطح أرض أفقي وعادت إليه، وعليه خمس نقاط: A نقطة الإطلاق وعندها سهم أحمر رأسي إلى أعلى مكتوب عنده ‎+14.7 m/s، وB على الجزء الصاعد وعندها سهم أحمر رأسي إلى أعلى أقصر مكتوب عنده ‎+9.8 m/s، وC أعلى نقطة مكتوب عندها v_y = 0 m/s، وD على الجزء النازل على ارتفاع B نفسه (يصل بينهما خط أفقي متقطع) مكتوب عندها v_y = ?، وE نقطة السقوط على الأرض مكتوب عندها v_y = ?. وفي الزاوية العليا سهما المحورين +x و+y."}]'::jsonb, null, 'تطبيق', 'استعمال التماثل', 'سهل', 'الكتاب ص 164 — المقذوفات التي تطلق بزاوية'),
('essay', 2, 'قُذفت كرة من سطح أرض أفقي بمركّبة رأسية لسرعتها الابتدائية $v_{yi}$ وعادت إلى المستوى نفسه. (a) أثبت أن زمن الصعود إلى أقصى ارتفاع يساوي زمن النزول منه إلى مستوى الإطلاق. (b) تحقّق من ذلك عدديًّا عندما $v_{yi} = 14.7\ \text{m/s}$. (أهمل مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$)', null, null, null, 'تحليل', 'إثبات', 'صعب', 'الكتاب ص 165 — مثال 1: تحليل كرة'),
('essay', 3, 'بيّن في أيّ الحالات الآتية لا يكون زمن صعود المقذوف مساويًا لزمن نزوله، وفسّر السبب في كل حالة: (a) كرة قُذفت بزاوية من فوق سطح بناية وسقطت على الأرض. (b) كرة قُذفت من الأرض بزاوية فسقطت على سطح مرتفع. (c) كرة قُذفت من الأرض وعادت إليها مع وجود مقاومة هواء كبيرة. ثم اذكر شرطي تماثل حركة المقذوف.', null, null, null, 'تحليل', 'تفسير حالات', 'صعب', 'الكتاب ص 164–166 — التماثل؛ المسألة 5؛ مقاومة الهواء')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
