insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'المسار متماثل عند العودة إلى مستوى الإطلاق، فزمن الصعود يساوي زمن النزول، وزمن التحليق $= 2t = 2(1.4\ \text{s}) = 2.8\ \text{s}$.', '["هذا زمن الصعود وحده، ويُضاف إليه زمن النزول المساوي له.","قُسم زمن الصعود على 2 بدل مضاعفته.","","عُدّ زمن النزول ضعف زمن الصعود، والزمنان متساويان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-21T13:36:33.210Z"}'::jsonb),
('mcq', 2, 0, 'يتساوى مقدار السرعة الرأسية عند الارتفاع نفسه في أثناء الصعود والنزول، ويختلف الاتجاه فقط؛ فتعود الكرة بسرعة مقدارها 20 m/s إلى أسفل.', '["","السرعة تنعدم عند أقصى ارتفاع فقط، لا عند العودة إلى نقطة الإطلاق.","لا تفقد الكرة نصف سرعتها؛ فالحركة متماثلة بإهمال مقاومة الهواء.","لا تتضاعف السرعة؛ فالكرة تكتسب في النزول ما فقدته في الصعود فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.210Z"}'::jsonb),
('mcq', 3, 1, 'بالتماثل، يقطع المقذوف المسافة من مستوى الإطلاق إلى ذلك الارتفاع في 0.40 s صعودًا، وفي الزمن نفسه من ذلك الارتفاع إلى الأرض نزولًا؛ فيمر به نازلًا عند $3.0 - 0.40 = 2.6\ \text{s}$.', '["ضوعف زمن المرور الأول، وهذا يصح لو كان ذلك الارتفاع هو القمة.","","هذه لحظة الوصول إلى أقصى ارتفاع (نصف زمن التحليق).","أُضيف الزمن إلى زمن التحليق بدل طرحه منه، وهذا بعد ارتطام الكرة بالأرض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-21T13:36:33.210Z"}'::jsonb),
('mcq', 4, 3, 'المركّبة الأفقية ثابتة على امتداد المسار (8.0 m/s)، والمركّبة الرأسية متماثلة: مقدارها عند الارتفاع نفسه متساوٍ صعودًا ونزولًا (6.0 m/s) واتجاهها معكوس، أي إلى أسفل عند E.', '["الكرة عند E تنزل، فمركّبتها الرأسية إلى أسفل لا إلى أعلى.","بُدّلت المركّبتان؛ فالأفقية لا تتغير، والرأسية تتساوى مقدارًا فقط.","المركّبة الأفقية لا تنعدم، و10 m/s مقدار السرعة الكلية لا مركّبتها الرأسية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.211Z"}'::jsonb),
('mcq', 5, 0, 'لحظة الارتطام تكون المركّبة الأفقية مساوية لقيمتها الابتدائية، والرأسية مساوية لها مقدارًا ومعاكسة اتجاهًا؛ فتصنع السرعة مع الأفقي الزاوية نفسها $35^\circ$ لكن تحته.', '["","المركّبة الرأسية لحظة الارتطام إلى أسفل، فالسرعة تحت الأفقي لا فوقه.","هذه الزاوية مع الرأسي لا مع الأفقي.","المركّبة الأفقية لا تنعدم، فالسرعة ليست رأسية تمامًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-21T13:36:33.211Z"}'::jsonb),
('mcq', 6, 3, 'التماثل يتحقق عندما يعود المقذوف إلى الارتفاع نفسه الذي قُذف منه وبإهمال مقاومة الهواء؛ فيقطع في النزول المسافة الرأسية نفسها التي قطعها في الصعود وبالتسارع نفسه.', '["عند القذف من بناية ينزل المقذوف مسافة رأسية أكبر من التي صعدها، فيطول زمن نزوله.","التماثل لا يتعلق بزاوية معيّنة؛ فهو يتحقق لأي زاوية عند العودة إلى المستوى نفسه.","مقاومة الهواء تُفسد التماثل؛ فهو مشروط بإهمالها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.211Z"}'::jsonb),
('mcq', 7, 2, 'بالتماثل زمن النزول من القمة نصف زمن التحليق: $2.00\ \text{s}$، وعند القمة $v_y = 0$؛ فالكرة تسقط منها كما يسقط جسم من السكون: $y_{\text{max}} = \frac{1}{2}gt^2 = \frac{1}{2}(9.80\ \text{m/s}^2)(2.00\ \text{s})^2 = 19.6\ \text{m}$.', '["استُعمل زمن التحليق كاملًا 4.00 s بدل زمن النزول.","نُسي العامل $\\frac{1}{2}$: $(9.80)(2.00)^2$.","","نُسي تربيع الزمن: $\\frac{1}{2}(9.80)(2.00)$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-21T13:36:33.212Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $t_C = \frac{v_{yi}}{g} = \frac{14.7}{9.80} = 1.50\ \text{s}$. (b) D على ارتفاع B نفسه، وتصل إليها بعد القمة بالزمن الذي استغرقته من B إلى القمة ($1.50 - 0.50 = 1.00\ \text{s}$)، أي عند $t_D = 2.50\ \text{s}$، و$v_y = -9.8\ \text{m/s}$ (المقدار نفسه إلى أسفل). E عند $t_E = 2(1.50) = 3.00\ \text{s}$، و$v_y = -14.7\ \text{m/s}$. (c) زمن التحليق 3.00 s.', '["زمن الوصول إلى القمة 1.50 s","$t_D = 2.50\\ \\text{s}$ و$v_y = -9.8\\ \\text{m/s}$","$t_E = 3.00\\ \\text{s}$ و$v_y = -14.7\\ \\text{m/s}$","زمن التحليق 3.00 s"]'::jsonb, '["$t_C = \\frac{14.7\\ \\text{m/s}}{9.80\\ \\text{m/s}^2} = 1.50\\ \\text{s}$","$t_D = 1.50 + (1.50 - 0.50) = 2.50\\ \\text{s}$","$t_E = 2t_C = 3.00\\ \\text{s}$"]'::jsonb, '[{"element":"زمن القمة","marks":1},{"element":"النقطة D","marks":1},{"element":"النقطة E","marks":1},{"element":"زمن التحليق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع القيم صحيحة بإشاراتها"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة $v_y$ عند D وE موجبة.","جعل $t_D = 2 \\times 0.50\\ \\text{s}$."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.212Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) ليكن زمن الصعود $t_1$ وزمن النزول $t_2$. الصعود: عند القمة $v_y = 0$، فـ $t_1 = \frac{v_{yi}}{g}$، وأقصى ارتفاع $y_{\text{max}} = \frac{v_{yi}^2}{2g}$. النزول: تبدأ الكرة من القمة بسرعة رأسية صفر وتنزل المسافة $y_{\text{max}}$: $y_{\text{max}} = \frac{1}{2}gt_2^2$، فـ $t_2 = \sqrt{\frac{2y_{\text{max}}}{g}} = \sqrt{\frac{v_{yi}^2}{g^2}} = \frac{v_{yi}}{g}$؛ إذن $t_1 = t_2$. (b) $t_1 = \frac{14.7}{9.80} = 1.50\ \text{s}$، $y_{\text{max}} = \frac{(14.7)^2}{2(9.80)} = 11.0\ \text{m}$، $t_2 = \sqrt{\frac{2(11.0)}{9.80}} = 1.50\ \text{s}$.', '["زمن الصعود $\\frac{v_{yi}}{g}$","أقصى ارتفاع $\\frac{v_{yi}^2}{2g}$","زمن النزول من السكون يساوي $\\frac{v_{yi}}{g}$","التحقق العددي 1.50 s للزمنين"]'::jsonb, '["$t_1 = \\frac{v_{yi}}{g}$","$y_{\\text{max}} = \\frac{v_{yi}^2}{2g}$","$t_2 = \\sqrt{\\frac{2y_{\\text{max}}}{g}} = \\frac{v_{yi}}{g}$","عدديًّا: $1.50\\ \\text{s} = 1.50\\ \\text{s}$"]'::jsonb, '[{"element":"زمن الصعود","marks":1},{"element":"أقصى ارتفاع","marks":1},{"element":"زمن النزول والمساواة","marks":1},{"element":"التحقق العددي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إثبات كامل وتحقق عددي صحيح"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["افتراض التساوي دون إثبات.","نسيان أن السرعة الرأسية عند القمة صفر في معادلة النزول."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-21T13:36:33.213Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) زمن النزول أطول؛ لأن الكرة تنزل من القمة مسافة رأسية أكبر من التي صعدتها (تنزل إلى ما دون مستوى الإطلاق). (b) زمن النزول أقصر؛ لأنها تنزل مسافة رأسية أقل من التي صعدتها قبل أن تصطدم بالسطح المرتفع. (c) لا يتحقق التماثل؛ لأن مقاومة الهواء تعاكس الحركة فتغيّر السرعة بطريقة مختلفة في الصعود عنها في النزول، فلا يبقى المسار متماثلًا. شرطا التماثل: أن يعود المقذوف إلى مستوى الإطلاق نفسه، وأن تُهمل مقاومة الهواء.', '["(a) زمن النزول أطول مع السبب","(b) زمن النزول أقصر مع السبب","(c) مقاومة الهواء تُفسد التماثل","الشرطان"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة a","marks":1},{"element":"الحالة b","marks":1},{"element":"الحالة c","marks":1},{"element":"الشرطان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التماثل يتحقق دائمًا مهما كان مستوى السقوط.","عكس الحالتين a وb."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.213Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C6-L1-O16') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L1-O17'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تجلس في حافلة تتحرك بسرعة متجهة ثابتة على طريق أفقي، وتقذف كرة رأسيًّا إلى أعلى ثم تلتقطها. كيف يبدو مسار الكرة لك؟ (أهمل مقاومة الهواء)', null, null, '["خط مستقيم رأسي إلى أعلى ثم إلى أسفل","قطع مكافئ يتجه إلى الأمام مع الحافلة","قطع مكافئ يتجه إلى الخلف عكس الحافلة","خط مستقيم مائل إلى الخلف قليلًا"]'::jsonb, 'فهم', 'وصف مسار من إطار مرجعي', 'سهل', 'الكتاب ص 166 — مسارات المقذوفات تعتمد على موقع المشاهد'),
('mcq', 2, 'في الموقف السابق نفسه (كرة تُقذف رأسيًّا إلى أعلى داخل حافلة تتحرك بسرعة متجهة ثابتة)، كيف يبدو مسار الكرة لمراقب يقف على الرصيف؟', null, null, '["خط مستقيم رأسي إلى أعلى ثم إلى أسفل","قطع مكافئ ينحني عكس اتجاه حركة الحافلة","قطع مكافئ يتقدم في اتجاه حركة الحافلة","خط مستقيم أفقي في اتجاه حركة الحافلة"]'::jsonb, 'فهم', 'وصف مسار من إطار مرجعي', 'متوسط', 'الكتاب ص 166 — مسارات المقذوفات تعتمد على موقع المشاهد'),
('mcq', 3, 'لماذا يرى المراقب على الرصيف الكرة المقذوفة رأسيًّا داخل الحافلة المتحركة تتحرك في قطع مكافئ؟', null, null, '["لأن الهواء داخل الحافلة يدفع الكرة إلى الأمام","لأن للكرة سرعة أفقية تساوي سرعة الحافلة ويد الراكب","لأن الجاذبية الأرضية أكبر بالنسبة إلى المراقب الواقف","لأن الكرة تفقد سرعتها الأفقية بعد مغادرة اليد"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 166 — مسارات المقذوفات تعتمد على موقع المشاهد'),
('mcq', 4, 'ألقى قائد طائرة تتحرك بسرعة متجهة ثابتة وعلى ارتفاع ثابت رزمة ثقيلة. أين تكون الطائرة بالنسبة إلى الرزمة لحظة ارتطامها بالأرض؟ (أهمل مقاومة الهواء)', null, null, '["خلف الرزمة بمسافة أفقية كبيرة","أمام الرزمة بمسافة تساوي مداها الأفقي","فوق نقطة إلقاء الرزمة تمامًا","فوق الرزمة مباشرة"]'::jsonb, 'تحليل', 'استنتاج', 'متوسط', 'الكتاب ص 180 — السؤال 29'),
('mcq', 5, 'يبين الشكل الآتي ثلاثة مسارات محتملة لرزمة أُفلتت من طائرة تطير أفقيًّا بسرعة متجهة ثابتة. ما المسار الذي يراه مراقب على الأرض، وما المسار الذي يراه قائد الطائرة؟ (أهمل مقاومة الهواء)', null, '[{"src":"qimg/phys1/c6l1-o17-plane.svg","alt":"طائرة تطير أفقيًّا نحو اليمين (سهم أحمر مكتوب عنده v) وقد أُفلتت منها رزمة. من موقع الإفلات تنطلق ثلاثة مسارات إلى الأرض: المسار (1) خط رأسي داكن متقطع إلى أسفل مباشرة، والمسار (2) منحنى برتقالي متقطع ينحني إلى الأمام في اتجاه حركة الطائرة (قطع مكافئ)، والمسار (3) منحنى رمادي منقّط ينحني إلى الخلف عكس اتجاه حركة الطائرة."}]'::jsonb, '["المراقب على الأرض (2)، وقائد الطائرة (1)","المراقب على الأرض (1)، وقائد الطائرة (2)","المراقب على الأرض (3)، وقائد الطائرة (1)","المراقب على الأرض (2)، وقائد الطائرة (3)"]'::jsonb, 'تحليل', 'مقارنة إطارين مرجعيين', 'صعب', 'الكتاب ص 166، 180 — مسارات المقذوفات تعتمد على موقع المشاهد؛ السؤال 29'),
('mcq', 6, 'يقف راكب في قطار يتحرك بسرعة متجهة ثابتة مقدارها 15.0 m/s على مسار أفقي، ويقذف كرة رأسيًّا إلى أعلى بالنسبة إليه بسرعة 4.90 m/s ثم يلتقطها عند الارتفاع نفسه. ما الإزاحة الأفقية للكرة بالنسبة إلى الأرض من لحظة قذفها حتى التقاطها؟ (أهمل مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$)', null, null, '["0 m","7.50 m","15.0 m","4.90 m"]'::jsonb, 'تطبيق', 'حساب في إطار مرجعي', 'صعب', 'الكتاب ص 166 — مسارات المقذوفات تعتمد على موقع المشاهد'),
('mcq', 7, 'علامَ يعتمد شكل مسار المقذوف كما يُشاهَد؟', null, null, '["كتلة المقذوف فقط","الإطار المرجعي الذي يُلاحَظ منه","المسافة بين المشاهد والمقذوف فقط","لون المقذوف وحجمه"]'::jsonb, 'تذكر', 'مفهوم', 'سهل', 'الكتاب ص 161 — حركة المقذوف'),
('essay', 1, 'تجلس في حافلة تتحرك بسرعة متجهة ثابتة، وتقذف كرة رأسيًّا إلى أعلى ثم تلتقطها. صف مسار الكرة كما تراه أنت، وكما يراه مراقب يقف على الرصيف، وفسّر سبب الاختلاف، وبيّن أين تسقط الكرة بالنسبة إليك. (أهمل مقاومة الهواء)', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 166، 180 — مسارات المقذوفات تعتمد على موقع المشاهد؛ السؤال 36a'),
('essay', 2, 'تتحرك الحافلة في الشكل الآتي بسرعة متجهة ثابتة 12.0 m/s على طريق أفقي، ويقذف راكب كرة رأسيًّا إلى أعلى بالنسبة إليه بسرعة 4.90 m/s ثم يلتقطها عند الارتفاع نفسه. (أهمل مقاومة الهواء، و$g = 9.80\ \text{m/s}^2$) (a) احسب زمن بقاء الكرة في الهواء. (b) ما أقصى ارتفاع تصل إليه الكرة فوق يد الراكب؟ وهل يختلف باختلاف المشاهد؟ (c) احسب الإزاحة الأفقية للكرة بالنسبة إلى الراكب، وبالنسبة إلى المراقب على الرصيف. (d) صف شكل المسار كما يراه كلٌّ منهما.', null, '[{"src":"qimg/phys1/c6l1-o17-bus.svg","alt":"حافلة تتحرك على طريق أفقي نحو اليمين (سهم أحمر أفقي مكتوب عنده v وتحته «سرعة الحافلة»). داخل الحافلة كرة صفراء وسهم أحمر رأسي إلى أعلى مكتوب فوقه «سرعة الكرة بالنسبة إلى الراكب». وعلى الرصيف إلى اليمين شخص واقف مكتوب تحته «مراقب على الرصيف»."}]'::jsonb, null, 'تحليل', 'مسألة في إطارين مرجعيين', 'صعب', 'الكتاب ص 166 — مسارات المقذوفات تعتمد على موقع المشاهد'),
('essay', 3, 'ألقى قائد طائرة تتحرك بسرعة متجهة ثابتة وعلى ارتفاع ثابت رزمة ثقيلة. (a) صف مسار الرزمة كما يراه مراقب على الأرض، وكما يراه قائد الطائرة. (b) أين تكون الطائرة بالنسبة إلى الرزمة لحظة ارتطامها بالأرض؟ فسّر. (c) كيف تتغير إجابتك عن (b) لو كانت مقاومة الهواء كبيرة؟', null, null, null, 'تحليل', 'تفسير ومقارنة', 'متوسط', 'الكتاب ص 180 — السؤال 29')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L1-O17') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'لك وللحافلة وللكرة السرعة الأفقية نفسها، فلا تتحرك الكرة أفقيًّا بالنسبة إليك، وتبدو لك سالكة مسارًا مستقيمًا إلى أعلى ثم إلى أسفل.', '["","هذا ما يراه مراقب على الرصيف، لا الراكب الذي يتحرك مع الكرة.","الكرة لا تتأخر عن الحافلة؛ فلها السرعة الأفقية نفسها.","لا توجد حركة أفقية للكرة بالنسبة إلى الراكب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-21T13:36:33.214Z"}'::jsonb),
('mcq', 2, 2, 'يرى المراقب الكرة تغادر اليد وترتفع ثم تعود إلى اليد، وفي الوقت نفسه تتحرك أفقيًّا مع الحافلة؛ فتكون الكرة بالنسبة إليه مقذوفًا له سرعة أفقية وسرعة رأسية، ومساره قطع مكافئ يتقدم في اتجاه حركة الحافلة.', '["هذا ما يراه الراكب داخل الحافلة، لا المراقب الواقف.","الكرة لا تتأخر عن الحافلة؛ فهي تتحرك أفقيًّا بسرعة الحافلة نفسها.","","الكرة ترتفع وتنزل أيضًا، فمسارها ليس أفقيًّا مستقيمًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-21T13:36:33.215Z"}'::jsonb),
('mcq', 3, 1, 'الكرة تتحرك مع الحافلة ويد الراكب قبل قذفها، فللكرة السرعة الأفقية نفسها للحافلة واليد بالنسبة إلى الأرض؛ فيراها المراقب مقذوفًا له مركّبة أفقية ثابتة ومركّبة رأسية، ومساره قطع مكافئ.', '["الكرة تحتفظ بسرعتها الأفقية دون حاجة إلى دفع من الهواء.","","تسارع الجاذبية واحد للمراقبَين؛ والاختلاف في السرعة الأفقية النسبية فقط.","لو فقدت الكرة سرعتها الأفقية لسقطت خلف الراكب، لكنها تعود إلى يده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.215Z"}'::jsonb),
('mcq', 4, 3, 'للرزمة لحظة إلقائها سرعة الطائرة الأفقية نفسها، وتبقى هذه المركّبة ثابتة بإهمال مقاومة الهواء؛ فتقطع الرزمة والطائرة المسافة الأفقية نفسها في كل لحظة، وتبقى الطائرة فوق الرزمة مباشرة.', '["الطائرة والرزمة لهما السرعة الأفقية نفسها، فلا تتأخر الطائرة عنها.","لا تسبق الطائرة الرزمة؛ فكلتاهما تقطعان المسافة الأفقية نفسها.","الطائرة تكون قد تحركت أفقيًّا مسافة المدى الأفقي للرزمة، فلم تعد فوق نقطة الإلقاء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-11-21T13:36:33.215Z"}'::jsonb),
('mcq', 5, 0, 'بالنسبة إلى الأرض للرزمة سرعة أفقية تساوي سرعة الطائرة، فتتحرك في قطع مكافئ إلى الأمام (2). وبالنسبة إلى قائد الطائرة لا سرعة أفقية للرزمة، فيراها تسقط رأسيًّا تحته مباشرة (1).', '["","عُكس الإطاران المرجعيان: المسار الرأسي يراه القائد، والقطع المكافئ يراه المراقب على الأرض.","المسار (3) يتطلب أن تتحرك الرزمة إلى الخلف بالنسبة إلى الأرض، وهي تتحرك إلى الأمام بسرعة الطائرة.","القائد يرى الرزمة تحته دائمًا، فلا تتأخر عنه كما في المسار (3)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.216Z"}'::jsonb),
('mcq', 6, 2, 'زمن تحليق الكرة: $t = \frac{2v_{yi}}{g} = \frac{2(4.90)}{9.80} = 1.00\ \text{s}$. وبالنسبة إلى الأرض للكرة سرعة أفقية 15.0 m/s، فإزاحتها الأفقية $= (15.0\ \text{m/s})(1.00\ \text{s}) = 15.0\ \text{m}$.', '["هذه الإزاحة الأفقية بالنسبة إلى الراكب، والمطلوب بالنسبة إلى الأرض.","استُعمل زمن الصعود 0.500 s وحده بدل زمن التحليق كاملًا.","","ضُربت سرعة الكرة الرأسية في الزمن بدل سرعة القطار الأفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-21T13:36:33.216Z"}'::jsonb),
('mcq', 7, 1, 'يعتمد شكل مسار المقذوف على الإطار المرجعي الذي يُلاحَظ منه؛ فالكرة نفسها تبدو لراكب الحافلة متحركة في خط رأسي، ولمراقب على الرصيف متحركة في قطع مكافئ.', '["الكتلة لا تؤثر في حركة المقذوف بإهمال مقاومة الهواء.","","البعد عن المقذوف لا يغيّر شكل مساره؛ المهم حركة المشاهد بالنسبة إليه.","اللون والحجم لا يحددان شكل المسار المشاهَد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-21T13:36:33.217Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تراها أنت ترتفع رأسيًّا ثم تنزل رأسيًّا إلى يدك في خط مستقيم. ويراها المراقب على الرصيف تغادر يدك وترتفع ثم تعود إلى يدك، متحركة في الوقت نفسه أفقيًّا مع الحافلة، فيكون مسارها قطعًا مكافئًا. سبب الاختلاف: لكَ وللحافلة وللكرة السرعة الأفقية نفسها؛ فبالنسبة إليك لا سرعة أفقية للكرة، وبالنسبة إلى المراقب لها سرعة أفقية تساوي سرعة الحافلة. فشكل المسار يعتمد على الإطار المرجعي. وتسقط الكرة في يدك.', '["مسار رأسي مستقيم بالنسبة إلى الراكب","قطع مكافئ بالنسبة إلى المراقب","التفسير بتساوي السرعة الأفقية للكرة والحافلة","الكرة تسقط في يد الراكب"]'::jsonb, '[]'::jsonb, '[{"element":"مسار الراكب","marks":1},{"element":"مسار المراقب","marks":1},{"element":"التفسير","marks":1},{"element":"موضع السقوط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكرة تسقط خلف الراكب.","القول إن المسار نفسه لكل المشاهدين."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-21T13:36:33.217Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $t = \frac{2v_{yi}}{g} = \frac{2(4.90)}{9.80} = 1.00\ \text{s}$. (b) $y_{\text{max}} = \frac{(4.90)^2}{2(9.80)} = 1.23\ \text{m}$، ولا يختلف؛ لأن الحركة الرأسية واحدة للمشاهدين. (c) بالنسبة إلى الراكب: 0 m. بالنسبة إلى المراقب: $(12.0\ \text{m/s})(1.00\ \text{s}) = 12.0\ \text{m}$ في اتجاه حركة الحافلة. (d) الراكب: خط رأسي إلى أعلى ثم إلى أسفل. المراقب: قطع مكافئ مداه الأفقي 12.0 m وأقصى ارتفاعه 1.23 m.', '["زمن البقاء 1.00 s","أقصى ارتفاع 1.23 m وهو نفسه للمشاهدين","الإزاحة الأفقية 0 m و12.0 m","شكلا المسار"]'::jsonb, '["$t = \\frac{2(4.90\\ \\text{m/s})}{9.80\\ \\text{m/s}^2} = 1.00\\ \\text{s}$","$y_{\\text{max}} = \\frac{v_{yi}^2}{2g} = 1.23\\ \\text{m}$","بالنسبة إلى المراقب: $\\Delta x = v_x t = (12.0)(1.00) = 12.0\\ \\text{m}$"]'::jsonb, '[{"element":"الزمن","marks":1},{"element":"أقصى ارتفاع","marks":1},{"element":"الإزاحتان الأفقيتان","marks":1},{"element":"شكلا المسار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال زمن الصعود فقط في حساب الإزاحة الأفقية.","القول إن أقصى ارتفاع أكبر بالنسبة إلى المراقب.","إعطاء إزاحة أفقية للكرة بالنسبة إلى الراكب."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-21T13:36:33.218Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) المراقب على الأرض: للرزمة سرعة أفقية تساوي سرعة الطائرة وتسقط في الوقت نفسه، فيرى مسارها قطعًا مكافئًا يتقدم في اتجاه حركة الطائرة. قائد الطائرة: لا سرعة أفقية للرزمة بالنسبة إليه، فيراها تسقط رأسيًّا تحته مباشرة. (b) تكون الطائرة فوق الرزمة مباشرة؛ لأن المركّبة الأفقية لسرعة الرزمة تبقى مساوية لسرعة الطائرة طوال السقوط فتقطعان المسافة الأفقية نفسها. (c) مع مقاومة هواء كبيرة تتناقص المركّبة الأفقية لسرعة الرزمة، فتتأخر عن الطائرة، وتكون الطائرة أمام الرزمة لحظة ارتطامها.', '["مسار القطع المكافئ للمراقب على الأرض","مسار رأسي لقائد الطائرة","الطائرة فوق الرزمة مباشرة مع التفسير","أثر مقاومة الهواء: الطائرة تسبق الرزمة"]'::jsonb, '[]'::jsonb, '[{"element":"مسار المراقب","marks":1},{"element":"مسار القائد","marks":1},{"element":"موضع الطائرة والتفسير","marks":1},{"element":"أثر مقاومة الهواء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الرزمة تسقط خلف الطائرة بإهمال مقاومة الهواء.","القول إن القائد يرى قطعًا مكافئًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-11-21T13:36:33.218Z"}'::jsonb)
