('mcq', 1, 'ما المقصود بالحركة الدائرية المنتظمة؟', null, null, '["حركة جسم بسرعة متجهة ثابتة حول دائرة نصف قطرها ثابت","حركة جسم بسرعة ثابتة المقدار حول دائرة نصف قطرها ثابت","حركة جسم حول دائرة بتسارع ثابت مقدارًا واتجاهًا","حركة جسم يزداد مقدار سرعته بانتظام حول دائرة نصف قطرها ثابت"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 168 — وصف الحركة الدائرية'),
('mcq', 2, 'تبيّن المخططات الآتية مواقع أربعة أجسام صُوِّرت على فترات زمنية متساوية (منظورة من أعلى). أيّ المخططات يمثل حركة دائرية منتظمة؟', null, '[{"src":"qimg/phys1/c6l2-o01-paths.svg","alt":"أربعة مخططات مرقمة من 1 إلى 4 لنقاط تمثل مواقع أجسام على فترات زمنية متساوية. المخطط 1: عشر نقاط موزعة بمسافات متساوية على دائرة مرسومة بخط متقطع خفيف. المخطط 2: ثماني نقاط على دائرة مماثلة لكن المسافات بين النقاط المتتالية تتزايد تدريجيًا. المخطط 3: إحدى عشرة نقطة متساوية التباعد تقريبًا على مسار حلزوني يزداد بُعده عن المركز. المخطط 4: سبع نقاط متساوية التباعد على خط مستقيم أفقي."}]'::jsonb, '["المخطط 2","المخطط 3","المخطط 4","المخطط 1"]'::jsonb, 'فهم', 'تفسير مخطط حركة', 'متوسط', 'الكتاب ص 168 — الحركة الدائرية المنتظمة'),
('mcq', 3, 'أيّ الحركات الآتية مثال على الحركة الدائرية المنتظمة؟', null, null, '["نقطة على طرف ريشة مروحة سقف تدور بمعدل ثابت","سيارة يزداد مقدار سرعتها وهي تسلك منعطفًا دائريًا","كرة تتدحرج بسرعة ثابتة على أرضية مستوية في خط مستقيم","حجر مربوط بخيط يلتف حول إصبع فيقصر الخيط باستمرار"]'::jsonb, 'تطبيق', 'تمييز مثال', 'سهل', 'الكتاب ص 168 — وصف الحركة الدائرية'),
('mcq', 4, 'جسم يتحرك حركة دائرية منتظمة. أيّ الكميات الآتية تبقى ثابتة في أثناء حركته؟', null, null, '["السرعة المتجهة ومتجه الموقع","متجه التسارع المركزي ومقدار السرعة","مقدار السرعة وطول متجه الموقع","اتجاه السرعة وطول متجه الموقع"]'::jsonb, 'فهم', 'تمييز الكميات الثابتة', 'صعب', 'الكتاب ص 168 — وصف الحركة الدائرية'),
('mcq', 5, 'يبيّن الجدول الآتي قياسات لأربعة أجسام تدور حول مراكز ثابتة، عند لحظتين مختلفتين. أيّ الأجسام يتحرك حركة دائرية منتظمة؟', '{"headers":["الجسم","مقدار السرعة عند t = 0 s","مقدار السرعة عند t = 4.0 s","بُعده عن المركز عند t = 0 s","بُعده عن المركز عند t = 4.0 s"],"rows":[["1","3.0 m/s","3.0 m/s","2.0 m","2.5 m"],["2","4.0 m/s","6.0 m/s","1.0 m","1.0 m"],["3","5.0 m/s","5.0 m/s","1.5 m","1.5 m"],["4","2.0 m/s","3.0 m/s","3.0 m","2.0 m"]]}'::jsonb, null, '["الجسم 1","الجسم 2","الجسم 3","الجسم 4"]'::jsonb, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 168 — وصف الحركة الدائرية'),
('mcq', 6, 'قمر صناعي يدور حول الأرض في مدار دائري بسرعة ثابتة المقدار. لماذا تُعدّ حركته حركة دائرية منتظمة مع أن سرعته المتجهة تتغير؟', null, null, '["لأن الانتظام يعني ثبات مقدار السرعة ونصف القطر فقط","لأن سرعته المتجهة ثابتة فعلًا ولا يتغير منها شيء","لأن تسارعه يساوي صفرًا لثبات مقدار سرعته","لأن بُعده عن مركز الأرض يتغير بمعدل منتظم في أثناء دورانه"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 168 — وصف الحركة الدائرية'),
('mcq', 7, 'جسم يتحرك على دائرة نصف قطرها ثابت، ويقطع أقواسًا متساوية الطول في فترات زمنية متساوية. ما الوصف الصحيح لحركته؟', null, null, '["حركة دائرية منتظمة؛ لأن سرعته المتجهة ثابتة","حركة غير منتظمة؛ لأن اتجاه حركته يتغير","حركة منتظمة؛ لأن تسارعه يساوي صفرًا","حركة دائرية منتظمة؛ لأن مقدار سرعته ثابت"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 168 — وصف الحركة الدائرية'),
('essay', 1, 'وضّح المقصود بالحركة الدائرية المنتظمة، واذكر الشرطين اللازمين لتكون حركة جسم دائرية منتظمة، ثم بيّن ما الذي يتغير في أثناء هذه الحركة، ومثّل لها بمثال من الحياة.', null, null, null, 'فهم', 'شرح مفهوم', 'سهل', 'الكتاب ص 168 — وصف الحركة الدائرية'),
('essay', 2, 'في لعبة الأفعوانية تصعد العربة الحلقة الرأسية فيتناقص مقدار سرعتها، ثم تنزل فيتزايد، وشكل الحلقة ليس دائرة تامة. هل تتحرك العربة في هذه الحلقة حركة دائرية منتظمة؟ فسّر إجابتك.', null, null, null, 'تحليل', 'تحليل موقف', 'متوسط', 'الكتاب ص 168، 182 — الحركة الدائرية المنتظمة، التقويم 50'),
('essay', 3, 'كرة مربوطة في نهاية خيط خفيف تتحرك في مسار دائري في المستوى الرأسي، وتؤثر فيها قوة الشد وقوة الجاذبية الأرضية فقط. حلّل حركة الكرة، وبيّن هل يمكن أن تكون حركتها دائرية منتظمة إذا تُركت تدور دون أن يحركها أحد.', null, null, null, 'تحليل', 'تحليل حركة', 'صعب', 'الكتاب ص 168، 182 — الحركة الدائرية المنتظمة، التقويم 51')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
