select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الحركة الدائرية المنتظمة هي حركة جسم أو جسيم بسرعة ثابتة المقدار حول دائرة نصف قطرها ثابت؛ فالثابت مقدار السرعة ونصف القطر، أما الاتجاه فيتغير.', '["السرعة المتجهة لا يمكن أن تبقى ثابتة في مسار دائري؛ لأن اتجاهها يتغير باستمرار، والثابت هو مقدارها فقط.","","اتجاه التسارع في الحركة الدائرية المنتظمة يتغير باستمرار ليبقى نحو المركز، فلا يكون ثابت الاتجاه.","ازدياد مقدار السرعة يجعل الحركة غير منتظمة؛ فشرط الانتظام ثبات مقدار السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-21T13:36:33.219Z"}'::jsonb),
('mcq', 2, 3, 'في المخطط 1 تقع النقاط على دائرة واحدة (نصف قطر ثابت)، والمسافات بين المواقع المتتالية متساوية في فترات زمنية متساوية (مقدار سرعة ثابت)؛ وهذان شرطا الحركة الدائرية المنتظمة.', '["النقاط على دائرة لكن المسافات بينها تتزايد، أي أن مقدار السرعة يزداد، فالحركة دائرية غير منتظمة.","المسافات متساوية تقريبًا لكن بُعد الجسم عن المركز يزداد (مسار حلزوني)، فنصف القطر غير ثابت.","النقاط متساوية التباعد لكنها على خط مستقيم؛ فهذه حركة منتظمة في خط مستقيم لا حركة دائرية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-21T13:36:33.220Z"}'::jsonb),
('mcq', 3, 0, 'النقطة على طرف ريشة المروحة تبقى على بُعد ثابت من محور الدوران، وتقطع مسافات متساوية في أزمنة متساوية عندما تدور المروحة بمعدل ثابت؛ فمقدار سرعتها ونصف قطر مسارها ثابتان.', '["","مقدار سرعة السيارة يتغير، والانتظام يتطلب ثبات مقدار السرعة.","الكرة تتحرك في خط مستقيم لا في مسار دائري.","قِصر الخيط يعني أن نصف قطر المسار يتناقص، فلا يكون نصف القطر ثابتًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-21T13:36:33.220Z"}'::jsonb),
('mcq', 4, 2, 'في الحركة الدائرية المنتظمة يبقى طول متجه الموقع (نصف القطر $r$) ثابتًا ويتغير اتجاهه، ويبقى مقدار السرعة ثابتًا ويتغير اتجاهها.', '["اتجاه كل من السرعة المتجهة ومتجه الموقع يتغير باستمرار، فلا يكون أيٌّ منهما ثابتًا.","مقدار السرعة ثابت، لكن متجه التسارع يتغير اتجاهه ليبقى نحو المركز.","","طول متجه الموقع ثابت، لكن اتجاه السرعة يتغير باستمرار لأنها مماسية للمسار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.220Z"}'::jsonb),
('mcq', 5, 2, 'الجسم 3 بقي مقدار سرعته 5.0 m/s وبُعده عن المركز 1.5 m عند اللحظتين، فمقدار سرعته ونصف قطر مساره ثابتان.', '["بُعد الجسم 1 عن المركز تغيّر من 2.0 m إلى 2.5 m، فنصف قطر مساره غير ثابت.","مقدار سرعة الجسم 2 تغيّر من 4.0 m/s إلى 6.0 m/s، فحركته غير منتظمة.","","مقدار السرعة ونصف القطر كلاهما تغيّرا في الجسم 4."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.220Z"}'::jsonb),
('mcq', 6, 0, 'الانتظام في الحركة الدائرية يعني ثبات مقدار السرعة وثبات نصف القطر؛ أما اتجاه السرعة فيتغير حتمًا في أي مسار دائري، ولا يتعارض ذلك مع التعريف.', '["","اتجاه سرعة القمر يتغير باستمرار، فسرعته المتجهة غير ثابتة.","تغيّر اتجاه السرعة يعني وجود تسارع (نحو المركز)، فتسارعه لا يساوي صفرًا.","لو تغير بُعده عن المركز لما كان المدار دائريًا؛ فنصف القطر يجب أن يبقى ثابتًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.221Z"}'::jsonb),
('mcq', 7, 3, 'قطع أقواس متساوية في أزمنة متساوية يعني أن مقدار السرعة ثابت، ومع ثبات نصف القطر تكون الحركة دائرية منتظمة.', '["الحكم صحيح لكن التعليل خاطئ؛ فالسرعة المتجهة تتغير اتجاهًا، والثابت مقدارها.","تغير الاتجاه لا يمنع الانتظام؛ فالحركة الدائرية المنتظمة يتغير فيها الاتجاه دائمًا.","الجسم الذي يتغير اتجاه سرعته متسارع، فتسارعه لا يساوي صفرًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-21T13:36:33.221Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الحركة الدائرية المنتظمة هي حركة جسم أو جسيم بسرعة ثابتة المقدار حول دائرة نصف قطرها ثابت. شرطاها: (1) ثبات نصف قطر المسار $r$، (2) ثبات مقدار السرعة $v$. أما الذي يتغير فهو اتجاه السرعة المتجهة واتجاه متجه الموقع باستمرار. مثال: نقطة على طرف ريشة مروحة تدور بمعدل ثابت، أو حجر مربوط بخيط يدور في دائرة أفقية بسرعة ثابتة المقدار.', '["التعريف: حركة بسرعة ثابتة المقدار حول دائرة نصف قطرها ثابت","الشرط الأول: ثبات نصف القطر","الشرط الثاني: ثبات مقدار السرعة","المتغير: اتجاه السرعة واتجاه متجه الموقع","مثال صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الشرطان","marks":1},{"element":"ما يتغير","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق مع الشرطين وما يتغير ومثال صحيح"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في الشرطين أو ما يتغير أو المثال"},{"level":"درجة واحدة","description":"ذكر ثبات السرعة دون تمييز المقدار من الاتجاه"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن السرعة المتجهة ثابتة","إغفال شرط ثبات نصف القطر","إعطاء مثال يتغير فيه مقدار السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-21T13:36:33.221Z"}'::jsonb),
('essay', 2, null::int, null, null, 'لا تتحرك حركة دائرية منتظمة. فالحركة الدائرية المنتظمة تتطلب شرطين: ثبات مقدار السرعة، وثبات نصف قطر المسار. وفي الأفعوانية يتغير مقدار سرعة العربة (يتناقص في الصعود ويتزايد في النزول)، كما أن الحلقة ليست دائرة تامة فنصف قطر انحناء المسار يتغير من موضع إلى آخر. اختلال أيٍّ من الشرطين يكفي للحكم بأن الحركة غير منتظمة.', '["الحكم: ليست حركة دائرية منتظمة","الشرط الأول مختل: مقدار السرعة يتغير","الشرط الثاني مختل: نصف القطر غير ثابت","ربط الحكم بتعريف الحركة الدائرية المنتظمة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"تحليل مقدار السرعة","marks":1},{"element":"تحليل نصف القطر","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حكم صحيح مع تحليل الشرطين"},{"level":"درجتان","description":"حكم صحيح مع تحليل شرط واحد"},{"level":"درجة واحدة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"حكم خاطئ أو لا إجابة"}]'::jsonb, '["عدّ أي حركة على حلقة دائرية حركة منتظمة","الاستدلال بتغير الاتجاه على عدم الانتظام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-21T13:36:33.221Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قوة الشد في الخيط تكون دائمًا على امتداد الخيط نحو المركز، فهي عمودية على السرعة ولا تغير مقدارها. أما قوة الجاذبية فاتجاهها رأسي إلى أسفل دائمًا، فيكون لها عند معظم المواقع مركّبة في اتجاه المماس: في أثناء صعود الكرة تكون هذه المركّبة عكس اتجاه الحركة فيتناقص مقدار السرعة، وفي أثناء نزولها تكون في اتجاه الحركة فيتزايد. لذلك يتغير مقدار سرعة الكرة على المسار، فلا تكون حركتها دائرية منتظمة، وتكون سرعتها أكبر ما يمكن عند أدنى نقطة وأصغر ما يمكن عند أعلى نقطة.', '["الشد نحو المركز عمودي على السرعة","للجاذبية مركّبة مماسية في معظم المواقع","المركّبة المماسية تبطئ الكرة في الصعود وتسرعها في النزول","الحكم: الحركة غير منتظمة"]'::jsonb, '[]'::jsonb, '[{"element":"دور قوة الشد","marks":1},{"element":"المركّبة المماسية للجاذبية","marks":1},{"element":"أثرها في مقدار السرعة","marks":1},{"element":"الحكم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحليل كامل للقوتين وأثرهما مع حكم صحيح"},{"level":"2–3 درجات","description":"حكم صحيح مع تحليل ناقص لإحدى القوتين"},{"level":"درجة واحدة","description":"حكم صحيح دون تحليل"},{"level":"صفر","description":"حكم خاطئ أو لا إجابة"}]'::jsonb, '["افتراض أن الجاذبية لا تؤثر في مقدار السرعة","عدّ الحركة منتظمة لأن الخيط يُبقي نصف القطر ثابتًا","افتراض أن الشد يغير مقدار السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-21T13:36:33.222Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
