select (select id from public.objectives where code = 'P1-C6-L2-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالتسارع المركزي؟', null, null, '["تسارع جسم في حركة دائرية يشير دائمًا إلى خارج الدائرة بعيدًا عن مركزها","تسارع جسم في حركة دائرية يكون في اتجاه المماس للدائرة","تسارع جسم في حركة دائرية منتظمة يشير دائمًا إلى المركز","تسارع يشير نحو المركز ويزيد مقدار سرعة الجسم باستمرار"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 168 — اتجاه التسارع في الحركة الدائرية'),
('mcq', 2, 'يبيّن الشكل متجهي السرعة $\boldsymbol{v}_1$ و$\boldsymbol{v}_2$ لجسم يتحرك حركة دائرية منتظمة عند بداية فترة زمنية قصيرة ونهايتها. إلى أين يشير متجه التغير في السرعة $\Delta\boldsymbol{v} = \boldsymbol{v}_2 - \boldsymbol{v}_1$؟', null, '[{"src":"qimg/phys1/c6l2-o02-dv.svg","alt":"دائرة في وسطها نقطة مكتوب تحتها «المركز». سهم رمادي منحنٍ أعلى يسار الدائرة يبين أن الجسم يدور مع اتجاه عقارب الساعة. نقطتان متقاربتان في الجزء العلوي من الدائرة: عند النقطة اليسرى سهم أحمر مماسي للدائرة يتجه إلى أعلى اليمين قليلًا مكتوب عنده v1، وعند النقطة اليمنى سهم أحمر مماسي مساوٍ له في الطول يتجه إلى أسفل اليمين قليلًا مكتوب عنده v2."}]'::jsonb, '["نحو مركز الدائرة","في اتجاه $\\boldsymbol{v}_1$","بعيدًا عن مركز الدائرة","في اتجاه $\\boldsymbol{v}_2$"]'::jsonb, 'فهم', 'تفسير متجهات', 'متوسط', 'الكتاب ص 168 — الشكل 6-6'),
('mcq', 3, 'في الحركة الدائرية المنتظمة يكون التسارع المتوسط $\boldsymbol{\bar{a}} = \frac{\Delta\boldsymbol{v}}{\Delta t}$. ما اتجاه هذا التسارع؟', null, null, '["في اتجاه $\\boldsymbol{v}_1$","في اتجاه الإزاحة $\\Delta\\boldsymbol{r}$","في اتجاه متجه الموقع $\\boldsymbol{r}_1$","في اتجاه $\\Delta\\boldsymbol{v}$ نفسه"]'::jsonb, 'فهم', 'تفسير علاقة', 'سهل', 'الكتاب ص 168 — اتجاه التسارع في الحركة الدائرية'),
('mcq', 4, 'جسم يتحرك حركة دائرية منتظمة عكس اتجاه عقارب الساعة (منظورًا من أعلى) كما في الشكل. ما اتجاه تسارعه عندما يكون عند النقطة الشمالية من الدائرة كما هو مبيّن؟', null, '[{"src":"qimg/phys1/c6l2-o02-compass.svg","alt":"دائرة في مركزها نقطة صغيرة، وجسم (نقطة كبيرة) عند أعلى نقطة في الدائرة. سهم رمادي منحنٍ عند الجزء العلوي الأيمن خارج الدائرة يبين أن الدوران عكس اتجاه عقارب الساعة. وفي أعلى يمين الشكل بوصلة: سهم إلى أعلى مكتوب عنده شمال، وأسفله جنوب، ويمينه شرق، ويساره غرب."}]'::jsonb, '["نحو الغرب","نحو الجنوب","نحو الشمال","نحو الشرق"]'::jsonb, 'تطبيق', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 168 — اتجاه التسارع في الحركة الدائرية'),
('mcq', 5, 'أيّ العبارات الآتية تصف متجه التسارع المركزي لجسم يتحرك حركة دائرية منتظمة؟', null, null, '["مقداره ثابت واتجاهه يتغير ليبقى نحو المركز","مقداره ثابت واتجاهه ثابت لا يتغير","مقداره يتغير واتجاهه ثابت نحو الأسفل","مقداره صفر في كل لحظة لأن مقدار السرعة ثابت"]'::jsonb, 'فهم', 'وصف متجه', 'سهل', 'الكتاب ص 168، 169 — التسارع المركزي'),
('mcq', 6, 'قال طالب: «التسارع المركزي لا يغير مقدار سرعة الجسم». ما الذي يفسر صحة قوله؟', null, null, '["لأن مقداره صغير جدًا في جميع حالات الحركة الدائرية","لأنه في اتجاه السرعة نفسه دائمًا","لأن الجسم لا يتسارع في الحركة الدائرية","لأنه عمودي على السرعة فيغير اتجاهها فقط"]'::jsonb, 'تحليل', 'تعليل', 'صعب', 'الكتاب ص 168، 179 — التسارع المركزي'),
('mcq', 7, 'جسم يتحرك حركة دائرية منتظمة عكس اتجاه عقارب الساعة. أيّ المخططات الآتية يمثل اتجاهات تسارعه عند ثلاثة مواقع على المسار؟', null, '[{"src":"qimg/phys1/c6l2-o02-panels.svg","alt":"أربعة مخططات مرقمة من 1 إلى 4، في كل منها دائرة ومركزها وسهم رمادي منحنٍ يبين الدوران عكس عقارب الساعة، وثلاث نقاط على الدائرة (أعلاها وأسفلها يسارًا وأسفلها يمينًا) يخرج من كل منها سهم بنفسجي قصير. المخطط 1: الأسهم الثلاثة تتجه نحو مركز الدائرة. المخطط 2: الأسهم تتجه بعيدًا عن المركز إلى الخارج. المخطط 3: الأسهم مماسية للدائرة. المخطط 4: الأسهم الثلاثة رأسية إلى أسفل."}]'::jsonb, '["المخطط 2","المخطط 1","المخطط 3","المخطط 4"]'::jsonb, 'فهم', 'تفسير مخطط', 'متوسط', 'الكتاب ص 168 — اتجاه التسارع في الحركة الدائرية'),
('essay', 1, 'وضّح المقصود بالتسارع المركزي، وفسّر لماذا يشير نحو مركز الدائرة مستعينًا بمتجهي السرعة $\boldsymbol{v}_1$ و$\boldsymbol{v}_2$ عند بداية فترة زمنية قصيرة ونهايتها.', null, null, null, 'فهم', 'شرح مفهوم', 'متوسط', 'الكتاب ص 168 — الشكل 6-6'),
('essay', 2, 'يبيّن الشكل جسمًا يتحرك حركة دائرية منتظمة عكس اتجاه عقارب الساعة، وسرعته عند الموقع $P_1$ هي $\boldsymbol{v}_1$ وعند الموقع $P_2$ هي $\boldsymbol{v}_2$. (a) ارسم المتجهين من نقطة واحدة وأوجد بالرسم $\Delta\boldsymbol{v} = \boldsymbol{v}_2 - \boldsymbol{v}_1$. (b) صف اتجاه $\Delta\boldsymbol{v}$ بالنسبة إلى مركز الدائرة. (c) ماذا تستنتج عن اتجاه التسارع؟', null, '[{"src":"qimg/phys1/c6l2-o02-e-sub.svg","alt":"دائرة في مركزها نقطة، وسهم رمادي منحنٍ عند يمينها العلوي يبين الدوران عكس عقارب الساعة. موقعان في الجزء العلوي: P1 على يمين القمة بزاوية 60 درجة من الأفقي، ويخرج منه سهم أحمر مماسي متجه إلى أعلى اليسار مكتوب عنده v1. وP2 عند قمة الدائرة تمامًا، ويخرج منه سهم أحمر أفقي إلى اليسار مساوٍ للأول في الطول مكتوب عنده v2."}]'::jsonb, null, 'تطبيق', 'رسم متجهات', 'صعب', 'الكتاب ص 168 — الشكل 6-6'),
('essay', 3, 'قال طالب: «التسارع المركزي يعني أن الجسم يتسارع نحو المركز؛ لذا فهو يقترب من مركز الدائرة تدريجيًا، ويزداد مقدار سرعته باستمرار». قوّم عبارة الطالب، موضحًا المقصود بالتسارع المركزي واتجاهه وأثره في السرعة المتجهة للجسم في الحركة الدائرية المنتظمة.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 168، 169 — التسارع المركزي')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
