from (values
('mcq', 1, 2, 'متجه التسارع في الحركة الدائرية المنتظمة يشير دائمًا إلى مركز الدائرة؛ لذا يُسمّى التسارع المركزي.', '["التسارع في الحركة الدائرية المنتظمة يشير نحو المركز لا بعيدًا عنه.","الاتجاه المماسي هو اتجاه السرعة، أما التسارع المركزي فعمودي عليها نحو المركز.","","التسارع المركزي لا يغير مقدار السرعة، فهو يغير اتجاهها فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-21T13:36:33.223Z"}'::jsonb),
('mcq', 2, 0, 'عند رسم $\boldsymbol{v}_1$ و$\boldsymbol{v}_2$ من نقطة واحدة وإيجاد الفرق بينهما يتجه $\Delta\boldsymbol{v}$ نحو مركز الدائرة، ولأن التسارع في اتجاه $\Delta\boldsymbol{v}$ فهو يشير نحو المركز.', '["","طرح متجهين متساويين في المقدار ومختلفين في الاتجاه لا يعطي متجهًا في اتجاه أحدهما.","هذا عكس الاتجاه الصحيح؛ فرسم $\\boldsymbol{v}_2 - \\boldsymbol{v}_1$ يعطي متجهًا يتجه نحو الداخل.","$\\Delta\\boldsymbol{v}$ ليس في اتجاه السرعة النهائية؛ لأن مقداري السرعتين متساويان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-21T13:36:33.223Z"}'::jsonb),
('mcq', 3, 3, 'بما أن $\Delta t$ كمية قياسية موجبة، فإن $\boldsymbol{\bar{a}}$ له اتجاه $\Delta\boldsymbol{v}$ نفسه، وهو نحو مركز الدائرة.', '["قسمة متجه على كمية قياسية موجبة ($\\Delta t$) تعطي اتجاه المتجه المقسوم وهو $\\Delta\\boldsymbol{v}$ لا $\\boldsymbol{v}_1$.","اتجاه $\\Delta\\boldsymbol{r}$ هو اتجاه السرعة المتجهة المتوسطة لا اتجاه التسارع.","متجه الموقع يتجه من المركز إلى الخارج، والتسارع يتجه عكسه نحو المركز.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-21T13:36:33.223Z"}'::jsonb),
('mcq', 4, 1, 'التسارع المركزي يشير دائمًا من الجسم نحو مركز الدائرة؛ والجسم عند أقصى الشمال فالمركز جنوبه، فيكون التسارع نحو الجنوب.', '["هذا اتجاه سرعة الجسم عند هذه النقطة (مماسي)، لا اتجاه تسارعه.","","هذا الاتجاه بعيد عن المركز، والتسارع المركزي يشير نحو المركز.","هذا عكس اتجاه السرعة المماسية، والتسارع لا يكون مماسيًا في الحركة الدائرية المنتظمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-21T13:36:33.224Z"}'::jsonb),
('mcq', 5, 0, 'في الحركة الدائرية المنتظمة يبقى مقدار التسارع المركزي ثابتًا، لكن اتجاهه يدور مع الجسم ليشير دائمًا إلى مركز الدائرة.', '["","اتجاه التسارع يتغير مع تغير موقع الجسم لأنه يشير دائمًا إلى المركز.","مقدار التسارع المركزي ثابت ما دام $v$ و$r$ ثابتين، واتجاهه ليس ثابتًا.","ثبات مقدار السرعة لا يعني انعدام التسارع؛ فاتجاه السرعة يتغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-21T13:36:33.224Z"}'::jsonb),
('mcq', 6, 3, 'التسارع المركزي يتجه نحو المركز، والسرعة مماسية؛ فهما متعامدان دائمًا، ولذلك لا يغير التسارع المركزي مقدار السرعة بل يغير اتجاهها فقط.', '["مقدار التسارع المركزي قد يكون كبيرًا جدًا، وعدم تغييره لمقدار السرعة سببه اتجاهه لا مقداره.","لو كان في اتجاه السرعة لزاد مقدارها؛ والتسارع المركزي عمودي عليها.","الجسم يتسارع لأن اتجاه سرعته يتغير، فالعبارة تناقض وجود التسارع المركزي أصلًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-21T13:36:33.224Z"}'::jsonb),
('mcq', 7, 1, 'في المخطط 1 يشير سهم التسارع عند كل موقع نحو مركز الدائرة، وهذا هو التسارع المركزي.', '["الأسهم في هذا المخطط تشير بعيدًا عن المركز، والتسارع المركزي يشير نحوه.","","الأسهم في هذا المخطط مماسية، وهذا اتجاه السرعة لا التسارع.","الأسهم في هذا المخطط كلها نحو الأسفل كتسارع السقوط الحر، والتسارع المركزي يتغير اتجاهه مع موقع الجسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-21T13:36:33.225Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التسارع المركزي هو تسارع الجسم المتحرك حركة دائرية منتظمة، وهو يشير دائمًا إلى مركز الدائرة. التفسير: متجها السرعة $\boldsymbol{v}_1$ و$\boldsymbol{v}_2$ متساويان في المقدار ومماسيان للدائرة عند الموقعين. عند إيجاد الفرق $\Delta\boldsymbol{v} = \boldsymbol{v}_2 - \boldsymbol{v}_1$ برسم المتجهين من نقطة واحدة، يتجه $\Delta\boldsymbol{v}$ نحو مركز الدائرة. والتسارع المتوسط $\boldsymbol{\bar{a}} = \frac{\Delta\boldsymbol{v}}{\Delta t}$ له اتجاه $\Delta\boldsymbol{v}$ نفسه، فيشير نحو المركز.', '["التعريف: تسارع الحركة الدائرية المنتظمة المتجه نحو المركز","السرعتان متساويتان مقدارًا ومماسيتان","إيجاد $\\Delta\\boldsymbol{v}$ بطرح المتجهين واتجاهه نحو المركز","التسارع في اتجاه $\\Delta\\boldsymbol{v}$"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"وصف المتجهين","marks":1},{"element":"اتجاه $\\Delta\\boldsymbol{v}$","marks":1},{"element":"ربط التسارع بـ $\\Delta\\boldsymbol{v}$","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف وتفسير كامل بالمتجهات"},{"level":"2–3 درجات","description":"تعريف صحيح وتفسير ناقص"},{"level":"درجة واحدة","description":"تعريف دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع المتجهين بدل طرحهما","القول إن التسارع في اتجاه السرعة","إهمال أن $\\Delta t$ لا يغير الاتجاه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-21T13:36:33.225Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) يُرسم $\boldsymbol{v}_1$ و$\boldsymbol{v}_2$ من نقطة واحدة دون تغيير طولَيهما أو اتجاهَيهما، ثم يُرسم $\Delta\boldsymbol{v}$ من رأس $\boldsymbol{v}_1$ إلى رأس $\boldsymbol{v}_2$ (لأن $\boldsymbol{v}_1 + \Delta\boldsymbol{v} = \boldsymbol{v}_2$). (b) يكون $\Delta\boldsymbol{v}$ متجهًا إلى أسفل وقليلًا إلى اليسار؛ أي نحو مركز الدائرة تقريبًا (في اتجاه منصِّف القوس بين الموقعين نحو الداخل). (c) لأن $\boldsymbol{\bar{a}} = \frac{\Delta\boldsymbol{v}}{\Delta t}$ فالتسارع في اتجاه $\Delta\boldsymbol{v}$، أي نحو مركز الدائرة، ويقترب اتجاهه أكثر من المركز كلما صغرت الفترة الزمنية.', '["رسم المتجهين من نقطة واحدة","$\\Delta\\boldsymbol{v}$ من رأس $\\boldsymbol{v}_1$ إلى رأس $\\boldsymbol{v}_2$","اتجاه $\\Delta\\boldsymbol{v}$ نحو المركز","التسارع نحو المركز"]'::jsonb, '["انقل $\\boldsymbol{v}_2$ بحيث يبدأ من ذيل $\\boldsymbol{v}_1$ نفسه","ارسم $\\Delta\\boldsymbol{v}$ من رأس $\\boldsymbol{v}_1$ إلى رأس $\\boldsymbol{v}_2$","قارن اتجاه $\\Delta\\boldsymbol{v}$ بالخط الواصل إلى المركز","استنتج اتجاه $\\boldsymbol{\\bar{a}} = \\frac{\\Delta\\boldsymbol{v}}{\\Delta t}$"]'::jsonb, '[{"element":"الرسم الصحيح","marks":2},{"element":"اتجاه $\\Delta\\boldsymbol{v}$","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"رسم صحيح واتجاه صحيح واستنتاج صحيح"},{"level":"2–3 درجات","description":"رسم صحيح مع خلل في الوصف أو الاستنتاج"},{"level":"درجة واحدة","description":"استنتاج صحيح دون رسم"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم $\\Delta\\boldsymbol{v}$ من رأس $\\boldsymbol{v}_2$ إلى رأس $\\boldsymbol{v}_1$","تغيير طول أحد المتجهين عند نقله","جمع المتجهين بدل طرحهما"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-21T13:36:33.226Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة في جزأيها. التسارع المركزي هو تسارع الجسم المتحرك حركة دائرية منتظمة، ومتجهه يشير دائمًا إلى مركز الدائرة. (1) لا يزداد مقدار السرعة: لأن التسارع المركزي عمودي في كل لحظة على السرعة المتجهة المماسية، فلا مركّبة له في اتجاهها؛ فهو يغير اتجاه السرعة فقط ويبقى مقدارها ثابتًا. (2) لا يقترب الجسم من المركز: فمعنى أن التسارع نحو المركز أن التغير في السرعة $\Delta\boldsymbol{v}$ يتجه نحو المركز، لا أن الجسم يتحرك نحوه؛ فالجسم له سرعة مماسية، والتسارع المركزي يحرف اتجاه حركته باستمرار عن الخط المستقيم (المماس) الذي كان سيسلكه، فيبقى على بُعد ثابت $r$ من المركز.', '["الحكم بخطأ العبارة","التسارع المركزي يشير دائمًا إلى مركز الدائرة","التسارع عمودي على السرعة فلا يغير مقدارها بل اتجاهها فقط","$\\Delta\\boldsymbol{v}$ نحو المركز لا حركة الجسم؛ فالجسم يبقى على بُعد ثابت $r$"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعريف والاتجاه","marks":1},{"element":"نفي زيادة مقدار السرعة مع التعليل","marks":1},{"element":"نفي الاقتراب من المركز مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعريف التسارع المركزي وتعليل خطأ الجزأين"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل خطأ أحد الجزأين فقط"},{"level":"درجة واحدة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"تأييد العبارة أو لا إجابة"}]'::jsonb, '["قبول أن الجسم يقترب من المركز","القول إن التسارع المركزي يزيد مقدار السرعة","الخلط بين اتجاه التسارع واتجاه حركة الجسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-21T13:36:33.226Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
