from (values
('mcq', 1, 'في اشتقاق علاقة التسارع المركزي يُقارَن مثلث متجهات الموقع ($\boldsymbol{r}_1$، $\boldsymbol{r}_2$، $\Delta\boldsymbol{r}$) بمثلث متجهات السرعة ($\boldsymbol{v}_1$، $\boldsymbol{v}_2$، $\Delta\boldsymbol{v}$). لماذا يكون المثلثان متشابهين؟', null, null, '["لأن $\\Delta\\boldsymbol{r}$ يوازي $\\Delta\\boldsymbol{v}$ دائمًا","لأن طول متجه الموقع $\\boldsymbol{r}$ يساوي مقدار متجه السرعة $\\boldsymbol{v}$","لأن $\\Delta\\boldsymbol{r}$ عمودي على $\\boldsymbol{r}_1$ تمامًا","لأن الزاوية بين متجهي الموقع تساوي الزاوية بين متجهي السرعة"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 169 — التسارع المركزي'),
('mcq', 2, 'ما العلاقة التي تنتج مباشرة عن تشابه مثلث متجهات الموقع ومثلث متجهات السرعة؟', null, null, '["$\\frac{\\Delta r}{v} = \\frac{\\Delta v}{r}$","$\\frac{\\Delta r}{r} = \\frac{\\Delta v}{v}$","$\\Delta r \\cdot r = \\Delta v \\cdot v$","$\\frac{r}{\\Delta v} = \\frac{v}{\\Delta r}$"]'::jsonb, 'تذكر', 'تذكر علاقة', 'سهل', 'الكتاب ص 169 — التسارع المركزي'),
('mcq', 3, 'بعد قسمة طرفي $\frac{\Delta r}{r} = \frac{\Delta v}{v}$ على $\Delta t$ والتعويض بـ $v = \frac{\Delta r}{\Delta t}$ و$a = \frac{\Delta v}{\Delta t}$، ما المعادلة الناتجة؟', null, null, '["$\\frac{v}{r} = \\frac{v}{a}$","$\\frac{r}{v} = \\frac{a}{v}$","$\\frac{v}{r} = \\frac{a}{v}$","$v \\cdot r = a \\cdot v$"]'::jsonb, 'فهم', 'خطوة اشتقاق', 'متوسط', 'الكتاب ص 169 — التسارع المركزي'),
('mcq', 4, 'ما الصيغة التي تنتج عند حل المعادلة $\frac{v}{r} = \frac{a}{v}$ لإيجاد التسارع المركزي؟', null, null, '["$a_{\\text{C}} = \\frac{v^2}{r}$","$a_{\\text{C}} = \\frac{v}{r}$","$a_{\\text{C}} = \\frac{r}{v^2}$","$a_{\\text{C}} = \\frac{v^2}{r^2}$"]'::jsonb, 'تذكر', 'خطوة اشتقاق', 'سهل', 'الكتاب ص 169 — التسارع المركزي'),
('mcq', 5, 'يبيّن الشكل مثلث متجهات الموقع ومثلث متجهات السرعة لجسم يتحرك حركة دائرية منتظمة خلال فترة زمنية قصيرة. إذا كان طول $\Delta\boldsymbol{r}$ يساوي 0.10 من طول متجه الموقع، فكم يساوي مقدار $\Delta\boldsymbol{v}$؟', null, '[{"src":"qimg/phys1/c6l2-o03-tri.svg","alt":"شكلان متجاوران. على اليسار مثلث بخطوط خضراء: متجه r1 ومتجه r2 يخرجان من نقطة واحدة وبينهما زاوية مكتوب عندها Δθ، ومتجه Δr يصل رأس r1 برأس r2. وعلى اليمين مثلث بخطوط حمراء مماثل في الشكل: متجه v1 ومتجه v2 يخرجان من نقطة واحدة وبينهما الزاوية Δθ نفسها، ومتجه Δv يصل رأس v1 برأس v2. لا توجد أطوال عددية على الشكل."}]'::jsonb, '["$0.10\\,r$","$0.10\\,v$","$10\\,v$","$0.010\\,v$"]'::jsonb, 'تطبيق', 'استعمال التناسب', 'متوسط', 'الكتاب ص 169 — مقارنة الشكلين 6-5b و6-6b'),
('mcq', 6, 'في اشتقاق التسارع المركزي استُعملت العلاقة $v = \frac{\Delta r}{\Delta t}$. ماذا يمثل $\Delta r$ في هذه العلاقة؟', null, null, '["نصف قطر الدائرة التي يتحرك عليها الجسم","التغير في طول متجه الموقع خلال الفترة الزمنية القصيرة","مقدار متجه الإزاحة خلال فترة زمنية قصيرة","محيط الدائرة التي يدور عليها الجسم"]'::jsonb, 'فهم', 'تفسير رمز', 'متوسط', 'الكتاب ص 168، 169 — الإزاحة في الحركة الدائرية'),
('mcq', 7, 'جسم يتحرك حركة دائرية منتظمة، وخلال فترة زمنية قصيرة دار متجه موقعه بزاوية صغيرة $\Delta\theta$. ماذا يحدث لمتجه سرعته خلال الفترة نفسها؟', null, null, '["يدور بالزاوية $\\Delta\\theta$ نفسها ويبقى مقداره ثابتًا","يدور بزاوية $2\\Delta\\theta$ ويبقى مقداره ثابتًا دون تغيير","لا يدور، لأن مقدار السرعة ثابت","يدور بالزاوية $\\Delta\\theta$ ويزداد مقداره"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 169 — التسارع المركزي'),
('essay', 1, 'استنتج علاقة التسارع المركزي $a_{\text{C}} = \frac{v^2}{r}$ مستعينًا بالشكل الذي يبيّن متجهي الموقع ومتجهي السرعة لجسم في حركة دائرية منتظمة ومثلثيهما، موضحًا كل خطوة.', null, '[{"src":"qimg/phys1/c6l2-o03-e-tri.svg","alt":"على اليسار دائرة مركزها نقطة، وسهم رمادي منحنٍ أعلاها يبين الدوران مع عقارب الساعة. من المركز يخرج متجهان أخضران: r1 إلى نقطة قرب قمة الدائرة، وr2 إلى نقطة على يمينها أسفل منها، وبينهما زاوية Δθ عند المركز، ومتجه أخضر Δr يصل رأس r1 برأس r2. عند كل من النقطتين سهم أحمر مماسي: v1 عند النقطة الأولى متجه إلى اليمين تقريبًا، وv2 عند الثانية متجه إلى أسفل اليمين. على اليمين مثلث أحمر: v1 وv2 مرسومان من نقطة واحدة وبينهما الزاوية Δθ، وΔv يصل رأس v1 برأس v2."}]'::jsonb, null, 'فهم', 'اشتقاق', 'صعب', 'الكتاب ص 169 — التسارع المركزي'),
('essay', 2, 'بيّن لماذا يتشابه مثلث متجهات الموقع ومثلث متجهات السرعة في الحركة الدائرية المنتظمة، واكتب النسبة الناتجة عن التشابه، ثم تحقق باستعمال الوحدات من أن المقدار $\frac{v^2}{r}$ له وحدة التسارع.', null, null, null, 'فهم', 'تعليل وتحقق', 'متوسط', 'الكتاب ص 169 — التسارع المركزي'),
('essay', 3, 'جسم يتحرك حركة دائرية منتظمة على دائرة نصف قطرها 2.0 m بسرعة مقدارها 4.0 m/s. خلال فترة زمنية قصيرة مقدارها 0.050 s: (a) احسب مقدار الإزاحة $\Delta r$ تقريبًا. (b) استعمل تشابه المثلثين لحساب $\Delta v$. (c) احسب التسارع $\frac{\Delta v}{\Delta t}$، وقارنه بـ $\frac{v^2}{r}$.', null, null, null, 'تطبيق', 'مسألة اشتقاق عددية', 'صعب', 'الكتاب ص 169 — التسارع المركزي')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L2-O03') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'متجه السرعة عمودي على متجه الموقع عند كل موقع، فعندما يدور متجه الموقع بزاوية $\Delta\theta$ يدور متجه السرعة بالزاوية نفسها؛ وكلا المثلثين متساوي الساقين ($|\boldsymbol{r}_1| = |\boldsymbol{r}_2|$، $|\boldsymbol{v}_1| = |\boldsymbol{v}_2|$)، فهما متشابهان.', '["$\\Delta\\boldsymbol{r}$ تقريبًا مماسي و$\\Delta\\boldsymbol{v}$ نحو المركز، فهما متعامدان تقريبًا لا متوازيان.","الطول والمقدار كميتان مختلفتان في الوحدة ولا يتساويان، والتشابه لا يتطلب تساويهما.","هذه ليست علة التشابه؛ فالتشابه قائم على تساوي الزاوية بين ضلعين متساويين في كل مثلث.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.227Z"}'::jsonb),
('mcq', 2, 1, 'في المثلثين المتشابهين تتناسب الأضلاع المتناظرة: $\Delta r$ يقابل $\Delta v$، و$r$ يقابل $v$؛ لذا $\frac{\Delta r}{r} = \frac{\Delta v}{v}$.', '["هذه النسبة تقابل ضلعًا من مثلث الموقع بضلع من مثلث السرعة غير مناظر له.","","التشابه يعطي تساوي نسب الأضلاع المتناظرة لا تساوي حواصل ضربها.","هذه الصيغة تكافئ $r\\Delta r = v\\Delta v$، وهي لا تمثل تناسب الأضلاع المتناظرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.227Z"}'::jsonb),
('mcq', 3, 2, '$\frac{\Delta r}{r\Delta t} = \frac{1}{r}\left(\frac{\Delta r}{\Delta t}\right) = \frac{v}{r}$، و$\frac{\Delta v}{v\Delta t} = \frac{1}{v}\left(\frac{\Delta v}{\Delta t}\right) = \frac{a}{v}$؛ فينتج $\frac{v}{r} = \frac{a}{v}$.', '["الطرف الأيمن مقلوب؛ فـ $\\frac{\\Delta v}{v\\Delta t}$ تساوي $\\frac{a}{v}$ لا $\\frac{v}{a}$.","الطرف الأيسر مقلوب؛ فـ $\\frac{\\Delta r}{r\\Delta t}$ تساوي $\\frac{v}{r}$.","","التعويض الصحيح يعطي نسبتين لا حاصلَي ضرب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-21T13:36:33.228Z"}'::jsonb),
('mcq', 4, 0, 'بضرب طرفي $\frac{v}{r} = \frac{a}{v}$ في $v$ نحصل على $a = \frac{v^2}{r}$، ويُرمز له $a_{\text{C}}$ تعبيرًا عن التسارع المركزي.', '["","عند ضرب الطرفين في $v$ يصبح البسط $v^2$ لا $v$.","هذه الصيغة مقلوبة؛ ووحدتها $\\text{s}^2/\\text{m}$ لا وحدة التسارع.","نصف القطر يظهر في المقام مرة واحدة فقط، ووحدة هذه الصيغة $\\text{s}^{-2}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.228Z"}'::jsonb),
('mcq', 5, 1, 'من التشابه $\frac{\Delta v}{v} = \frac{\Delta r}{r} = 0.10$، إذن $\Delta v = 0.10\,v$.', '["التشابه يربط $\\Delta v$ بـ $v$ في مثلث السرعة، لا بـ $r$ من مثلث الموقع.","","هذا مقلوب النسبة؛ فـ $\\frac{\\Delta v}{v} = \\frac{\\Delta r}{r} = 0.10$ لا 10.","هذا ناتج تربيع النسبة، والتشابه يعطي النسبة نفسها دون تربيع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.228Z"}'::jsonb),
('mcq', 6, 2, '$\Delta\boldsymbol{r} = \boldsymbol{r}_2 - \boldsymbol{r}_1$ هو متجه الإزاحة خلال الفترة $\Delta t$، ومقداره مقسومًا على $\Delta t$ يعطي مقدار السرعة.', '["نصف القطر هو $r$ نفسه، أما $\\Delta r$ فهو طول ضلع الإزاحة في مثلث الموقع.","طول متجه الموقع ثابت في الحركة الدائرية، فالتغير في طوله صفر؛ والمقصود مقدار متجه التغير $\\Delta\\boldsymbol{r}$.","","المحيط $2\\pi r$ يُقطع في زمن دوري كامل، لا في فترة زمنية قصيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.229Z"}'::jsonb),
('mcq', 7, 0, 'لأن السرعة عمودية على متجه الموقع عند كل موقع، فإن دوران متجه الموقع بزاوية $\Delta\theta$ يرافقه دوران متجه السرعة بالزاوية نفسها؛ ولهذا يتشابه المثلثان.', '["","متجه السرعة عمودي دائمًا على متجه الموقع، فيدوران معًا بالزاوية نفسها.","ثبات المقدار لا يعني ثبات الاتجاه؛ فاتجاه السرعة يتغير مع دوران متجه الموقع.","مقدار السرعة ثابت في الحركة الدائرية المنتظمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.229Z"}'::jsonb),
('essay', 1, null::int, null, null, 'متجه السرعة عمودي على متجه الموقع، فالزاوية بين $\boldsymbol{r}_1$ و$\boldsymbol{r}_2$ تساوي الزاوية بين $\boldsymbol{v}_1$ و$\boldsymbol{v}_2$؛ وكل مثلث متساوي الساقين، لذا فالمثلثان متشابهان. من التشابه: $\frac{\Delta r}{r} = \frac{\Delta v}{v}$. نقسم الطرفين على $\Delta t$: $\frac{\Delta r}{r\Delta t} = \frac{\Delta v}{v\Delta t}$، أي $\frac{1}{r}\left(\frac{\Delta r}{\Delta t}\right) = \frac{1}{v}\left(\frac{\Delta v}{\Delta t}\right)$. لكن $v = \frac{\Delta r}{\Delta t}$ و$a = \frac{\Delta v}{\Delta t}$، فنحصل على $\frac{v}{r} = \frac{a}{v}$، ومنه $a_{\text{C}} = \frac{v^2}{r}$.', '["تعليل تشابه المثلثين","كتابة $\\frac{\\Delta r}{r} = \\frac{\\Delta v}{v}$","القسمة على $\\Delta t$","التعويض بـ $v$ و$a$","الوصول إلى $a_{\\text{C}} = \\frac{v^2}{r}$"]'::jsonb, '["المثلثان متشابهان: الزاوية $\\Delta\\theta$ مشتركة وكلاهما متساوي الساقين","$\\frac{\\Delta r}{r} = \\frac{\\Delta v}{v}$","$\\frac{\\Delta r}{r\\Delta t} = \\frac{\\Delta v}{v\\Delta t}$","$\\frac{v}{r} = \\frac{a}{v}$","$a_{\\text{C}} = \\frac{v^2}{r}$"]'::jsonb, '[{"element":"تعليل التشابه","marks":1},{"element":"النسبة","marks":1},{"element":"القسمة والتعويض","marks":1},{"element":"النتيجة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اشتقاق كامل مع تعليل التشابه"},{"level":"2–3 درجات","description":"اشتقاق صحيح ينقصه التعليل أو خطوة"},{"level":"درجة واحدة","description":"كتابة النتيجة النهائية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["مقابلة $\\Delta r$ بـ $v$ بدل $\\Delta v$","نسيان ضرب الطرفين في $v$","عدم تعليل تشابه المثلثين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-21T13:36:33.230Z"}'::jsonb),
('essay', 2, null::int, null, null, 'متجه السرعة عمودي دائمًا على متجه الموقع، فعندما يدور متجه الموقع بزاوية $\Delta\theta$ يدور متجه السرعة بالزاوية نفسها؛ وكل مثلث متساوي الساقين لأن $|\boldsymbol{r}_1| = |\boldsymbol{r}_2| = r$ و$|\boldsymbol{v}_1| = |\boldsymbol{v}_2| = v$، فالمثلثان متشابهان. النسبة: $\frac{\Delta r}{r} = \frac{\Delta v}{v}$. الوحدات: $\frac{(\text{m/s})^2}{\text{m}} = \frac{\text{m}^2/\text{s}^2}{\text{m}} = \text{m/s}^2$، وهي وحدة التسارع.', '["السرعة عمودية على الموقع فالزاوية مشتركة","المثلثان متساويا الساقين","النسبة $\\frac{\\Delta r}{r} = \\frac{\\Delta v}{v}$","تحليل الوحدات يعطي $\\text{m/s}^2$"]'::jsonb, '["$\\frac{(\\text{m/s})^2}{\\text{m}} = \\frac{\\text{m}^2}{\\text{s}^2\\cdot\\text{m}} = \\text{m/s}^2$"]'::jsonb, '[{"element":"تعليل التشابه","marks":1},{"element":"النسبة","marks":1},{"element":"تحليل الوحدات","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل ونسبة وتحليل وحدات صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تربيع وحدة السرعة","تعليل التشابه بتساوي الأطوال لا بتساوي الزاوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.230Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $\Delta r \approx v\Delta t = (4.0\ \text{m/s})(0.050\ \text{s}) = 0.20\ \text{m}$. (b) من التشابه $\Delta v = \frac{v\,\Delta r}{r} = \frac{(4.0)(0.20)}{2.0} = 0.40\ \text{m/s}$. (c) $a = \frac{\Delta v}{\Delta t} = \frac{0.40\ \text{m/s}}{0.050\ \text{s}} = 8.0\ \text{m/s}^2$، و$\frac{v^2}{r} = \frac{(4.0)^2}{2.0} = 8.0\ \text{m/s}^2$؛ فالنتيجتان متساويتان، وهذا يؤكد العلاقة $a_{\text{C}} = \frac{v^2}{r}$.', '["$\\Delta r = 0.20\\ \\text{m}$","$\\Delta v = 0.40\\ \\text{m/s}$","$a = 8.0\\ \\text{m/s}^2$","المقارنة مع $\\frac{v^2}{r} = 8.0\\ \\text{m/s}^2$"]'::jsonb, '["$\\Delta r \\approx v\\Delta t = 4.0 \\times 0.050 = 0.20\\ \\text{m}$","$\\frac{\\Delta v}{v} = \\frac{\\Delta r}{r} \\Rightarrow \\Delta v = \\frac{4.0 \\times 0.20}{2.0} = 0.40\\ \\text{m/s}$","$a = \\frac{0.40}{0.050} = 8.0\\ \\text{m/s}^2$","$\\frac{v^2}{r} = \\frac{16}{2.0} = 8.0\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"حساب $\\Delta r$","marks":1},{"element":"حساب $\\Delta v$","marks":1},{"element":"حساب التسارع","marks":1},{"element":"المقارنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الحسابات صحيحة مع المقارنة"},{"level":"2–3 درجات","description":"خطأ حسابي واحد أو غياب المقارنة"},{"level":"درجة واحدة","description":"حساب $\\Delta r$ فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال $\\Delta v = \\frac{r\\,\\Delta r}{v}$","نسيان القسمة على $\\Delta t$","تربيع النسبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-21T13:36:33.231Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C6-L2-O03') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

