select (select id from public.objectives where code = 'P1-C6-L2-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا يتسارع جسم يتحرك بسرعة ثابتة المقدار في مسار دائري؟', null, null, '["لأن اتجاه سرعته يتغير باستمرار، فتتغير سرعته المتجهة","لأن مقدار سرعته يتغير قليلًا عند كل نقطة","لأن بُعده عن مركز المسار يتغير باستمرار","لأن قوة الطرد المركزي تدفعه إلى الخارج بعيدًا عن المركز"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 168 — مقدمة الدرس 6-2'),
('mcq', 2, 'التسارع كمية فيزيائية تصف المعدل الزمني للتغير في:', null, null, '["مقدار السرعة فقط دون اتجاهها","موقع الجسم بالنسبة إلى نقطة الأصل","السرعة المتجهة مقدارًا واتجاهًا","المسافة الكلية التي يقطعها الجسم في مساره"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 168 — مقدمة الدرس 6-2'),
('mcq', 3, 'هل يمكن أن تدور سيارة في منعطف وتسارعها يساوي صفرًا؟', null, null, '["نعم؛ إذا بقي مقدار سرعتها ثابتًا طوال المنعطف","لا؛ فتغير اتجاه السرعة يعني وجود تسارع","نعم؛ إذا كان نصف قطر المنعطف كبيرًا","نعم؛ إذا كانت سرعتها صغيرة جدًا"]'::jsonb, 'تطبيق', 'حكم وتعليل', 'متوسط', 'الكتاب ص 168، 180 — التقويم 30a'),
('mcq', 4, 'هل يمكن أن تدور سيارة في منعطف دائري بتسارع ثابت (مقدارًا واتجاهًا)؟', null, null, '["نعم؛ لأن مقدار التسارع المركزي ثابت","نعم؛ إذا تحركت بسرعة ثابتة المقدار طوال المنعطف","لا؛ لأن مقدار تسارعها يتغير دائمًا","لا؛ لأن اتجاه التسارع المركزي يتغير مع موقعها"]'::jsonb, 'تحليل', 'حكم وتعليل', 'صعب', 'الكتاب ص 168، 180 — التقويم 30b'),
('mcq', 5, 'سيارة تتحرك في مضمار دائري، وعداد السرعة فيها يشير إلى القراءة نفسها عند الموقعين A وB المبيّنين في الشكل. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys1/c6l2-o04-ab.svg","alt":"دائرة تمثل مضمارًا وفي مركزها نقطة، وسهم رمادي منحنٍ يبين الحركة عكس عقارب الساعة. الموقع A على يمين الدائرة ويخرج منه سهم أحمر رأسي إلى أعلى مكتوب عنده vA، والموقع B عند قمة الدائرة ويخرج منه سهم أحمر أفقي إلى اليسار مكتوب عنده vB، والسهمان متساويان في الطول."}]'::jsonb, '["سرعتها المتجهة عند A هي نفسها عند B، فهي غير متسارعة","هي متسارعة لأن مقدار سرعتها زاد بين A وB","هي متسارعة لأن عداد السرعة يقيس السرعة المتجهة مقدارًا واتجاهًا","سرعتها المتجهة عند A تختلف عنها عند B، لذا فهي متسارعة"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 168 — مقدمة الدرس 6-2'),
('mcq', 6, 'أيّ الأجسام الآتية تسارعه يساوي صفرًا؟', null, null, '["سيارة تسير بسرعة ثابتة المقدار في منعطف دائري أفقي","سيارة تسير بسرعة ثابتة المقدار على طريق مستقيم","قمر يدور حول كوكب بسرعة ثابتة المقدار","طفل على دوامة خيل تدور بمعدل ثابت"]'::jsonb, 'تطبيق', 'تمييز حالات', 'متوسط', 'الكتاب ص 168 — مقدمة الدرس 6-2'),
('mcq', 7, 'قال طالب: «الجسم في الحركة الدائرية المنتظمة غير متسارع؛ لأن عداد سرعته لا يتغير». ما الخطأ في تفكير الطالب؟', null, null, '["نسي أن مقدار السرعة يتغير في الحركة الدائرية المنتظمة","ظن أن عداد السرعة يقيس الموقع لا السرعة","عدّ التسارع تغيرًا في مقدار السرعة وأهمل اتجاهها","لا خطأ في تفكيره؛ فالجسم فعلًا غير متسارع"]'::jsonb, 'تقويم', 'تقويم استدلال', 'صعب', 'الكتاب ص 168 — مقدمة الدرس 6-2'),
('essay', 1, 'حجر مثبت في نهاية خيط يدور بسرعة ثابتة المقدار في مسار دائري أفقي. فسّر لماذا يُعدّ الحجر متسارعًا مع أن مقدار سرعته لا يتغير.', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 168 — مقدمة الدرس 6-2'),
('essay', 2, 'يبيّن الشكل جسمًا يتحرك حركة دائرية منتظمة عكس اتجاه عقارب الساعة بسرعة مقدارها 5.0 m/s. سرعته عند الموقع $P_1$ (أقصى الشرق) هي $\boldsymbol{v}_1$ نحو الشمال، وعند الموقع $P_2$ (أقصى الشمال) هي $\boldsymbol{v}_2$ نحو الغرب. (a) احسب مقدار التغير في السرعة $\Delta\boldsymbol{v}$ بين الموقعين وحدد اتجاهه. (b) ماذا تستنتج عن تسارع الجسم رغم ثبات مقدار سرعته؟', null, '[{"src":"qimg/phys1/c6l2-o04-e-quarter.svg","alt":"دائرة في مركزها نقطة، وسهم رمادي منحنٍ يبين الحركة عكس عقارب الساعة. الموقع P1 عند أقصى يمين الدائرة ويخرج منه سهم أحمر رأسي إلى أعلى مكتوب عنده v1 و5.0 m/s. والموقع P2 عند قمة الدائرة ويخرج منه سهم أحمر أفقي إلى اليسار مكتوب عنده v2 و5.0 m/s. وفي أسفل يمين الشكل بوصلة: شمال إلى أعلى، وجنوب إلى أسفل، وشرق إلى اليمين، وغرب إلى اليسار."}]'::jsonb, null, 'تطبيق', 'حساب تغير السرعة', 'صعب', 'الكتاب ص 168 — مقدمة الدرس 6-2'),
('essay', 3, 'سيارة (1) تزيد سرعتها على طريق مستقيم، وسيارة (2) تسير بسرعة ثابتة المقدار في منعطف دائري. أيّ السيارتين متسارعة؟ قارن بينهما من حيث ما يتغير في السرعة المتجهة لكل منهما واتجاه تسارعها بالنسبة إلى سرعتها.', null, null, null, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 168 — مقدمة الدرس 6-2')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L2-O04') and x.type = v.type and x.number = v.number);
