select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'التسارع هو التغير في السرعة المتجهة مقدارًا واتجاهًا. ولأن اتجاه حركة الجسم يتغير لحظيًا في المسار الدائري فإن سرعته المتجهة تتغير، لذلك فهو يتسارع.', '["","مقدار السرعة ثابت كما في نص السؤال؛ فالتغير في الاتجاه لا في المقدار.","نصف القطر ثابت في المسار الدائري، فليس هو سبب التسارع.","قوة الطرد المركزي قوة وهمية لا وجود لها، والتسارع سببه تغير اتجاه السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-21T13:36:33.232Z"}'::jsonb),
('mcq', 2, 2, 'التسارع هو التغير في السرعة المتجهة (مقدارًا واتجاهًا) مقسومًا على الزمن، وليس التغير في مقدار السرعة فقط.', '["هذا التصور الخاطئ يجعل الجسم الدوّار غير متسارع؛ والتسارع يشمل تغير الاتجاه أيضًا.","المعدل الزمني للتغير في الموقع هو السرعة المتجهة لا التسارع.","","المعدل الزمني للمسافة هو السرعة المتوسطة (القياسية)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-21T13:36:33.232Z"}'::jsonb),
('mcq', 3, 1, 'الدوران في منعطف يعني تغير اتجاه السرعة المتجهة، وأي تغير في السرعة المتجهة يعني وجود تسارع؛ فلا يمكن أن يكون التسارع صفرًا.', '["ثبات المقدار لا يكفي؛ فاتجاه السرعة يتغير في المنعطف فتتسارع السيارة.","","كِبَر نصف القطر يقلل التسارع المركزي لكنه لا يجعله صفرًا.","السرعة الصغيرة تقلل التسارع، لكن ما دام الاتجاه يتغير فالتسارع موجود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-21T13:36:33.232Z"}'::jsonb),
('mcq', 4, 3, 'التسارع المركزي يشير دائمًا إلى مركز المنعطف، فيتغير اتجاهه مع تغير موقع السيارة؛ لذا لا يكون التسارع ثابتًا متجهًا حتى لو ثبت مقداره.', '["ثبات المقدار وحده لا يجعل التسارع ثابتًا؛ فالتسارع متجه واتجاهه يتغير.","حتى مع ثبات مقدار السرعة يدور اتجاه التسارع ليبقى نحو المركز.","مقدار التسارع المركزي قد يكون ثابتًا؛ والسبب الصحيح تغير اتجاهه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-21T13:36:33.232Z"}'::jsonb),
('mcq', 5, 3, 'تساوي قراءة العداد يعني تساوي مقداري السرعة، لكن اتجاه السرعة عند A يختلف عنه عند B كما يبين الشكل؛ فالسرعة المتجهة تغيرت، والسيارة متسارعة.', '["متجها السرعة عند A وB مختلفان في الاتجاه، فالسرعة المتجهة تغيرت.","عداد السرعة لم يتغير، فمقدار السرعة ثابت؛ والتغير في الاتجاه فقط.","عداد السرعة يقيس مقدار السرعة فقط ولا يبين اتجاهها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-21T13:36:33.233Z"}'::jsonb),
('mcq', 6, 1, 'السيارة التي تسير على طريق مستقيم بسرعة ثابتة المقدار لا يتغير مقدار سرعتها ولا اتجاهها، فتسارعها صفر؛ أما بقية الأجسام فتتحرك في مسارات دائرية فيتغير اتجاه سرعتها.', '["اتجاه سرعة السيارة في المنعطف يتغير، فهي متسارعة.","","القمر يتحرك في مسار دائري فيتغير اتجاه سرعته، فهو متسارع نحو الكوكب.","الطفل يتحرك في دائرة فيتغير اتجاه سرعته، فله تسارع مركزي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.233Z"}'::jsonb),
('mcq', 7, 2, 'التسارع تغير في السرعة المتجهة مقدارًا واتجاهًا، والطالب اعتمد على ثبات المقدار فقط؛ مع أن اتجاه السرعة في المسار الدائري يتغير لحظيًا، فالجسم متسارع.', '["مقدار السرعة ثابت فعلًا في الحركة الدائرية المنتظمة، وهذا الجزء من كلامه صحيح.","العداد يقيس مقدار السرعة، والطالب استعمله استعمالًا صحيحًا؛ وخطؤه في مفهوم التسارع.","","الجسم متسارع لأن اتجاه سرعته يتغير باستمرار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-21T13:36:33.233Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التسارع هو التغير في السرعة المتجهة مقدارًا واتجاهًا، لا التغير في مقدار السرعة فقط. والحجر في المسار الدائري يتغير اتجاه حركته لحظيًا، فتتغير سرعته المتجهة رغم ثبات مقدارها؛ لذلك فهو متسارع، ويكون تسارعه نحو مركز الدائرة (تسارعًا مركزيًا).', '["تعريف التسارع بدلالة السرعة المتجهة","اتجاه حركة الحجر يتغير لحظيًا","السرعة المتجهة تتغير رغم ثبات المقدار","التسارع نحو المركز"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف التسارع","marks":1},{"element":"تغير الاتجاه","marks":1},{"element":"الاستنتاج واتجاه التسارع","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل"},{"level":"درجتان","description":"تفسير صحيح دون تحديد اتجاه التسارع أو دون تعريفه"},{"level":"درجة واحدة","description":"ذكر تغير الاتجاه فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الحجر غير متسارع","نسبة التسارع إلى قوة طرد مركزي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-21T13:36:33.233Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $\Delta\boldsymbol{v} = \boldsymbol{v}_2 - \boldsymbol{v}_1$؛ مركّبتاه: نحو الغرب 5.0 m/s، ونحو الجنوب 5.0 m/s. مقداره $\sqrt{(5.0)^2 + (5.0)^2} = 7.1\ \text{m/s}$، واتجاهه نحو الجنوب الغربي (بزاوية $45^\circ$ جنوب الغرب)، أي نحو داخل الدائرة باتجاه المركز تقريبًا. (b) لأن $\Delta\boldsymbol{v}$ لا يساوي صفرًا، فالسرعة المتجهة تغيرت رغم أن مقدارها بقي 5.0 m/s؛ إذن الجسم متسارع، وتسارعه المتوسط في اتجاه $\Delta\boldsymbol{v}$ نحو داخل الدائرة.', '["مركّبتا $\\Delta\\boldsymbol{v}$: 5.0 m/s غربًا و5.0 m/s جنوبًا","المقدار 7.1 m/s","الاتجاه جنوب غرب نحو داخل الدائرة","الاستنتاج: الجسم متسارع"]'::jsonb, '["$\\boldsymbol{v}_1$: 5.0 m/s شمالًا، $\\boldsymbol{v}_2$: 5.0 m/s غربًا","$\\Delta\\boldsymbol{v} = \\boldsymbol{v}_2 + (-\\boldsymbol{v}_1)$: 5.0 m/s غربًا + 5.0 m/s جنوبًا","$|\\Delta\\boldsymbol{v}| = \\sqrt{5.0^2 + 5.0^2} = 7.1\\ \\text{m/s}$","الاتجاه $45^\\circ$ جنوب الغرب"]'::jsonb, '[{"element":"المركّبتان","marks":1},{"element":"المقدار","marks":1},{"element":"الاتجاه","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب واتجاه واستنتاج صحيحة"},{"level":"2–3 درجات","description":"خطأ في الاتجاه أو المقدار"},{"level":"درجة واحدة","description":"استنتاج صحيح دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح المقدارين فقط والحصول على صفر","جمع المتجهين بدل طرحهما فيكون الاتجاه شمال غرب","نسيان الجذر التربيعي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-21T13:36:33.234Z"}'::jsonb),
('essay', 3, null::int, null, null, 'كلتا السيارتين متسارعة؛ لأن السرعة المتجهة لكل منهما تتغير. السيارة (1): يتغير مقدار سرعتها ولا يتغير اتجاهها، وتسارعها في اتجاه سرعتها. السيارة (2): يبقى مقدار سرعتها ثابتًا ويتغير اتجاهها، وتسارعها نحو مركز المنعطف عموديًا على سرعتها المماسية.', '["كلتاهما متسارعة","(1) يتغير المقدار، والتسارع في اتجاه السرعة","(2) يتغير الاتجاه، والتسارع عمودي على السرعة نحو المركز"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"تحليل السيارة 1","marks":1},{"element":"تحليل السيارة 2","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حكم ومقارنة صحيحة"},{"level":"درجتان","description":"حكم صحيح ومقارنة ناقصة"},{"level":"درجة واحدة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بأن سيارة المنعطف غير متسارعة","جعل تسارع سيارة المنعطف في اتجاه سرعتها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-21T13:36:33.234Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
