insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L2-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'كيف يعتمد مقدار التسارع المركزي لجسم على مقدار سرعته ونصف قطر مساره الدائري؟', null, null, '["يتناسب طرديًا مع السرعة وعكسيًا مع مربع نصف القطر","يتناسب طرديًا مع مربع السرعة وعكسيًا مع نصف القطر","يتناسب طرديًا مع كل من مقدار السرعة ونصف القطر معًا","يتناسب عكسيًا مع مربع السرعة وطرديًا مع نصف القطر"]'::jsonb, 'تذكر', 'تذكر علاقة', 'سهل', 'الكتاب ص 169 — التسارع المركزي'),
('mcq', 2, 'جسم يتحرك حركة دائرية منتظمة. إذا تضاعف مقدار سرعته مع بقاء نصف قطر مساره ثابتًا، فإن مقدار تسارعه المركزي:', null, null, '["يصبح مثلَي قيمته فقط","يصبح نصف قيمته الأصلية","يصبح ربع قيمته الأصلية","يصبح أربعة أمثال قيمته"]'::jsonb, 'فهم', 'تحليل تناسب', 'سهل', 'الكتاب ص 169 — التسارع المركزي'),
('mcq', 3, 'سيارة تسلك منعطفين بسرعة ثابتة المقدار نفسها، ونصف قطر المنعطف الثاني مثلا نصف قطر الأول. كيف يكون تسارعها المركزي في المنعطف الثاني مقارنة بالأول؟', null, null, '["نصف قيمته في المنعطف الأول","مثلَي قيمته في المنعطف الأول","أربعة أمثال قيمته في المنعطف الأول","ربع قيمته في المنعطف الأول"]'::jsonb, 'فهم', 'تحليل تناسب', 'سهل', 'الكتاب ص 169 — التسارع المركزي'),
('mcq', 4, 'جسم يتحرك حركة دائرية منتظمة. إذا أصبح كل من مقدار سرعته ونصف قطر مساره ثلاثة أمثال قيمته، فإن تسارعه المركزي:', null, null, '["يبقى ثابتًا لأن الزيادتين تلغي إحداهما الأخرى","يصبح تسعة أمثال قيمته","يصبح ثلاثة أمثال قيمته","يصبح ثلث قيمته الأصلية"]'::jsonb, 'تطبيق', 'تحليل تناسب', 'متوسط', 'الكتاب ص 169 — التسارع المركزي'),
('mcq', 5, 'أيّ المنحنيات الآتية يمثل العلاقة بين مقدار التسارع المركزي $a_{\text{C}}$ ومقدار السرعة $v$ لأجسام تتحرك على دوائر لها نصف القطر نفسه؟', null, '[{"src":"qimg/phys1/c6l2-o05-graphs.svg","alt":"أربعة منحنيات بيانية صغيرة مرقمة من 1 إلى 4، في كل منها محور أفقي مكتوب عنده v ومحور رأسي مكتوب عنده ac، دون أرقام. المنحنى 1: خط مستقيم مائل يبدأ من نقطة الأصل. المنحنى 2: منحنى يبدأ من نقطة الأصل وتزداد شدة ميله إلى أعلى (قطع مكافئ). المنحنى 3: منحنى يبدأ مرتفعًا ويتناقص بسرعة ثم ببطء مقتربًا من المحور الأفقي. المنحنى 4: خط أفقي موازٍ للمحور الأفقي."}]'::jsonb, '["المنحنى 1","المنحنى 3","المنحنى 2","المنحنى 4"]'::jsonb, 'فهم', 'تفسير منحنى', 'متوسط', 'الكتاب ص 169 — التسارع المركزي'),
('mcq', 6, 'يبيّن المنحنى التسارع المركزي لأجسام تتحرك بسرعة ثابتة المقدار نفسها على دوائر مختلفة أنصاف أقطارها. ما مقدار التسارع المركزي المتوقع لجسم يتحرك بالسرعة نفسها على دائرة نصف قطرها 4.0 m؟', null, '[{"src":"qimg/phys1/c6l2-o05-ar.svg","alt":"منحنى بياني: المحور الأفقي نصف القطر r (m) من 0 إلى 2.5 بتدريج كل 0.5، والمحور الرأسي التسارع المركزي (m/s²) من 0 إلى 40 بتدريج كل 5. منحنى بنفسجي متناقص يمر بثلاث نقاط معلّمة: (0.5، 32) و(1.0، 16) و(2.0، 8)، ويبدأ قرب r = 0.46 وينتهي عند r = 2.2 تقريبًا."}]'::jsonb, '["4.0 m/s²","64 m/s²","2.0 m/s²","16 m/s²"]'::jsonb, 'تحليل', 'استقراء من منحنى', 'صعب', 'الكتاب ص 169 — التسارع المركزي'),
('mcq', 7, 'يبيّن الشكل سيارتين A وB تتحركان بسرعة ثابتة المقدار 20 m/s، الأولى على مسار دائري نصف قطره 50 m والثانية على مسار نصف قطره 100 m. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys1/c6l2-o05-tracks.svg","alt":"دائرتان متجاورتان تمثلان مسارين. الدائرة اليسرى صغيرة نصف قطرها مكتوب 50 m بخط أخضر من مركزها، وعند قمتها سيارة على شكل نقطة مكتوب عندها A. الدائرة اليمنى كبيرة نصف قطرها مكتوب 100 m، وعند قمتها نقطة مكتوب عندها B."}]'::jsonb, '["التسارع المركزي للسيارة B مثلا تسارع A","التسارع المركزي للسيارة A أربعة أمثال تسارع السيارة B","التسارعان متساويان لأن السيارتين لهما مقدار السرعة نفسه","التسارع المركزي للسيارة A مثلا تسارع B"]'::jsonb, 'تطبيق', 'مقارنة', 'متوسط', 'الكتاب ص 169 — التسارع المركزي'),
('essay', 1, 'صف كيف يعتمد مقدار التسارع المركزي لجسم على مقدار سرعته ونصف قطر مساره الدائري، ثم فسّر في ضوء ذلك لماذا يُطلب من السائقين خفض سرعتهم عند المنعطفات الحادة.', null, null, null, 'فهم', 'وصف وتفسير', 'متوسط', 'الكتاب ص 168، 169 — أهداف الدرس، التسارع المركزي'),
('essay', 2, 'يبيّن الجدول الآتي مقدار السرعة ونصف القطر لأربعة أجسام تتحرك حركة دائرية منتظمة. (a) احسب التسارع المركزي لكل جسم. (b) قارن بين الجسمين 1 و2، ثم بين الجسمين 2 و3، واستنتج من كل مقارنة كيف يعتمد التسارع المركزي على المتغير الذي تغيّر.', '{"headers":["الجسم","مقدار السرعة (m/s)","نصف القطر (m)"],"rows":[["1","10","20"],["2","20","20"],["3","20","40"],["4","10","40"]]}'::jsonb, null, null, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 169 — التسارع المركزي'),
('essay', 3, 'عدّاء يركض على مسار دائري بسرعة ثابتة المقدار. أراد أن يضاعف مقدار سرعته مع إبقاء تسارعه المركزي كما هو (حتى لا تزيد القوة المطلوبة من الاحتكاك). كيف يجب أن يتغير نصف قطر مساره؟ وضّح بالعلاقة الرياضية.', null, null, null, 'تطبيق', 'استدلال كمي', 'صعب', 'الكتاب ص 169 — التسارع المركزي')
