from (values
('mcq', 1, 1, 'من العلاقة $a_{\text{C}} = \frac{v^2}{r}$: مقدار التسارع المركزي يساوي مربع السرعة مقسومًا على نصف قطر دائرة الحركة؛ فهو يتناسب طرديًا مع $v^2$ وعكسيًا مع $r$.', '["السرعة هي التي تظهر مربعة في العلاقة $a_{\\text{C}} = \\frac{v^2}{r}$، ونصف القطر يظهر مرة واحدة.","","نصف القطر في المقام، فزيادته تقلل التسارع المركزي لا تزيده.","هذا عكس العلاقة؛ فزيادة السرعة تزيد التسارع المركزي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-21T13:36:33.235Z"}'::jsonb),
('mcq', 2, 3, '$a_{\text{C}} \propto v^2$ عند ثبات $r$؛ فإذا أصبحت السرعة $2v$ صار التسارع $\frac{(2v)^2}{r} = 4\frac{v^2}{r}$، أي أربعة أمثال قيمته.', '["هذا يهمل تربيع السرعة في العلاقة $a_{\\text{C}} = \\frac{v^2}{r}$.","زيادة السرعة تزيد التسارع المركزي ولا تنقصه.","هذا يعامل السرعة كأنها في المقام؛ والصحيح أن $v^2$ في البسط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-21T13:36:33.235Z"}'::jsonb),
('mcq', 3, 0, 'عند ثبات $v$: $a_{\text{C}} = \frac{v^2}{r}$، فإذا أصبح نصف القطر $2r$ صار التسارع $\frac{v^2}{2r}$، أي نصف قيمته؛ لذلك يكون المنعطف الحاد (نصف القطر الصغير) أخطر عند السرعة نفسها.', '["","نصف القطر في المقام؛ فمضاعفته تقلل التسارع إلى النصف لا تضاعفه.","هذا يجعل التسارع يتناسب طرديًا مع $r^2$، وهو عكسي مع $r$.","التسارع يتناسب عكسيًا مع $r$ لا مع $r^2$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-21T13:36:33.236Z"}'::jsonb),
('mcq', 4, 2, '$a_{\text{C}}^{\prime} = \frac{(3v)^2}{3r} = \frac{9v^2}{3r} = 3\frac{v^2}{r}$؛ أي ثلاثة أمثال التسارع الأصلي.', '["السرعة مربعة في البسط ونصف القطر غير مربع في المقام، فلا يلغي أحدهما الآخر.","هذا يأخذ أثر تربيع السرعة فقط ويهمل زيادة نصف القطر في المقام.","","هذا يعكس أثر الزيادتين؛ فالبسط يزيد 9 مرات والمقام 3 مرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-21T13:36:33.236Z"}'::jsonb),
('mcq', 5, 2, 'عند ثبات $r$ يكون $a_{\text{C}} = \frac{v^2}{r} \propto v^2$، فالمنحنى قطع مكافئ يبدأ من نقطة الأصل وينحني إلى أعلى كالمنحنى 2.', '["الخط المستقيم المار بنقطة الأصل يعني أن $a_{\\text{C}}$ يتناسب مع $v$، لكنه يتناسب مع $v^2$.","المنحنى المتناقص يعني أن التسارع يقل بزيادة السرعة، وهذا شكل علاقته بنصف القطر لا بالسرعة.","","الخط الأفقي يعني أن التسارع لا يعتمد على السرعة، وهو يعتمد عليها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.236Z"}'::jsonb),
('mcq', 6, 0, 'من المنحنى: عند 0.50 m يكون 32 m/s²، وعند 1.0 m يكون 16 m/s²، وعند 2.0 m يكون 8.0 m/s²؛ فحاصل الضرب $a_{\text{C}} r = 16\ \text{m}^2/\text{s}^2$ ثابت (يساوي $v^2$). إذن عند $r = 4.0\ \text{m}$: $a_{\text{C}} = \frac{16}{4.0} = 4.0\ \text{m/s}^2$.', '["","هذا يعامل التسارع كأنه يتناسب طرديًا مع نصف القطر، والمنحنى يبيّن أنه يتناقص بزيادته.","هذا يقسم على مربع نسبة نصفي القطرين (من 2.0 m إلى 4.0 m)، والتناسب عكسي مع $r$ لا مع $r^2$.","هذا يفترض أن التسارع لا يتغير بتغير نصف القطر، والمنحنى يبيّن أنه يتغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.237Z"}'::jsonb),
('mcq', 7, 3, '$a_{\text{C},A} = \frac{(20)^2}{50} = 8.0\ \text{m/s}^2$ و$a_{\text{C},B} = \frac{(20)^2}{100} = 4.0\ \text{m/s}^2$؛ فتسارع A مثلا تسارع B.', '["نصف قطر مسار B أكبر، فتسارعها المركزي أصغر لا أكبر.","التسارع يتناسب عكسيًا مع $r$ لا مع $r^2$ عند ثبات السرعة.","تساوي السرعة لا يكفي؛ فالتسارع يعتمد على نصف القطر أيضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-21T13:36:33.237Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من العلاقة $a_{\text{C}} = \frac{v^2}{r}$: يزداد التسارع المركزي بزيادة مقدار السرعة، ويتناسب طرديًا مع مربعها (مضاعفة السرعة تضاعف التسارع أربع مرات)، ويقل بزيادة نصف القطر لأنه يتناسب معه عكسيًا (مضاعفة نصف القطر تجعله النصف). المنعطف الحاد نصف قطره صغير، فيحتاج إلى تسارع مركزي كبير، أي إلى قوة محصلة كبيرة نحو المركز يوفرها الاحتكاك؛ وخفض السرعة يقلل $v^2$ كثيرًا فيقل التسارع المطلوب، فلا تنزلق السيارة.', '["التناسب الطردي مع $v^2$","التناسب العكسي مع $r$","المنعطف الحاد نصف قطره صغير فيتطلب تسارعًا كبيرًا","خفض السرعة يقلل التسارع المطلوب بقدر كبير"]'::jsonb, '[]'::jsonb, '[{"element":"علاقة التسارع بالسرعة","marks":1},{"element":"علاقته بنصف القطر","marks":1},{"element":"تفسير المنعطف الحاد","marks":1},{"element":"أثر خفض السرعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف العلاقتين وتفسير كامل"},{"level":"2–3 درجات","description":"وصف صحيح وتفسير ناقص"},{"level":"درجة واحدة","description":"وصف إحدى العلاقتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التسارع يتناسب طرديًا مع نصف القطر","إغفال تربيع السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-21T13:36:33.238Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $a_{\text{C}} = \frac{v^2}{r}$: الجسم 1: $\frac{(10)^2}{20} = 5.0\ \text{m/s}^2$، الجسم 2: $\frac{(20)^2}{20} = 20\ \text{m/s}^2$، الجسم 3: $\frac{(20)^2}{40} = 10\ \text{m/s}^2$، الجسم 4: $\frac{(10)^2}{40} = 2.5\ \text{m/s}^2$. (b) بين 1 و2 تضاعفت السرعة ونصف القطر ثابت فصار التسارع أربعة أمثاله؛ إذن يتناسب التسارع طرديًا مع مربع السرعة. وبين 2 و3 تضاعف نصف القطر والسرعة ثابتة فصار التسارع نصف قيمته؛ إذن يتناسب التسارع عكسيًا مع نصف القطر.', '["حساب التسارعات الأربعة","المقارنة 1 و2: التناسب مع $v^2$","المقارنة 2 و3: التناسب العكسي مع $r$"]'::jsonb, '["$a_{\\text{C},1} = 100/20 = 5.0\\ \\text{m/s}^2$","$a_{\\text{C},2} = 400/20 = 20\\ \\text{m/s}^2$","$a_{\\text{C},3} = 400/40 = 10\\ \\text{m/s}^2$","$a_{\\text{C},4} = 100/40 = 2.5\\ \\text{m/s}^2$","$\\frac{a_{\\text{C},2}}{a_{\\text{C},1}} = 4$ و$\\frac{a_{\\text{C},3}}{a_{\\text{C},2}} = \\frac{1}{2}$"]'::jsonb, '[{"element":"الحسابات","marks":2},{"element":"المقارنة الأولى واستنتاجها","marks":1},{"element":"المقارنة الثانية واستنتاجها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة واستنتاجان صحيحان"},{"level":"2–3 درجات","description":"حسابات صحيحة واستنتاج واحد"},{"level":"درجة واحدة","description":"حسابات صحيحة دون استنتاج"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تربيع السرعة","مقارنة جسمين تغير فيهما المتغيران معًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.238Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يجب أن يصبح نصف القطر أربعة أمثال قيمته. فمن $a_{\text{C}} = \frac{v^2}{r}$ وثبات $a_{\text{C}}$: $\frac{v^2}{r} = \frac{(2v)^2}{r^{\prime}}$، ومنه $r^{\prime} = \frac{4v^2 r}{v^2} = 4r$. فمضاعفة السرعة تضاعف البسط أربع مرات، ولا يبقى التسارع ثابتًا إلا إذا تضاعف المقام أربع مرات أيضًا.', '["كتابة شرط ثبات $a_{\\text{C}}$","التعويض بـ $2v$","النتيجة $r^{\\prime} = 4r$"]'::jsonb, '["$\\frac{v^2}{r} = \\frac{(2v)^2}{r^{\\prime}}$","$r^{\\prime} = \\frac{4v^2}{v^2}r = 4r$"]'::jsonb, '[{"element":"شرط الثبات","marks":1},{"element":"التعويض والحل","marks":1},{"element":"النتيجة مع التفسير","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حل صحيح مع تفسير"},{"level":"درجتان","description":"نتيجة صحيحة دون تفسير كافٍ"},{"level":"درجة واحدة","description":"كتابة العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول بمضاعفة نصف القطر فقط","القول بتصغير نصف القطر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-21T13:36:33.238Z"}'::jsonb)
