('mcq', 1, 'ما الخطوة التي تُستعمل لكتابة التسارع المركزي بدلالة الزمن الدوري $\text{T}$؟', null, null, '["تعويض $v = r\\text{T}$ في العلاقة $a_{\\text{C}} = \\frac{v^2}{r}$","تعويض $v = \\frac{\\text{T}}{2\\pi r}$ في العلاقة $a_{\\text{C}} = \\frac{v^2}{r}$","تعويض $v = \\frac{2\\pi r}{\\text{T}}$ في $a_{\\text{C}} = \\frac{v^2}{r}$","ضرب العلاقة $a_{\\text{C}} = \\frac{v^2}{r}$ في الزمن الدوري $\\text{T}$"]'::jsonb, 'فهم', 'خطوة اشتقاق', 'سهل', 'الكتاب ص 169 — التسارع المركزي بدلالة الزمن الدوري'),
('mcq', 2, 'أيّ العلاقات الآتية تعطي مقدار التسارع المركزي بدلالة نصف القطر $r$ والزمن الدوري $\text{T}$؟', null, null, '["$a_{\\text{C}} = \\frac{4\\pi^2 r}{\\text{T}^2}$","$a_{\\text{C}} = \\frac{2\\pi r}{\\text{T}^2}$","$a_{\\text{C}} = \\frac{4\\pi^2 r^2}{\\text{T}^2}$","$a_{\\text{C}} = \\frac{4\\pi^2 r}{\\text{T}}$"]'::jsonb, 'تذكر', 'تذكر علاقة', 'سهل', 'الكتاب ص 169 — التسارع المركزي بدلالة الزمن الدوري'),
('mcq', 3, 'جسم يتحرك حركة دائرية منتظمة. إذا تضاعف زمنه الدوري مع بقاء نصف القطر ثابتًا، فإن تسارعه المركزي:', null, null, '["يصبح نصف قيمته الأصلية","يصبح مثلَي قيمته الأصلية","يصبح أربعة أمثال قيمته الأصلية","يصبح ربع قيمته"]'::jsonb, 'فهم', 'تحليل تناسب', 'متوسط', 'الكتاب ص 169 — التسارع المركزي بدلالة الزمن الدوري'),
('mcq', 4, 'نقطتان على قرص يدور بزمن دوري ثابت، بُعد الثانية عن المحور مثلا بُعد الأولى. كيف يكون التسارع المركزي للنقطة الثانية مقارنة بالأولى؟', null, null, '["نصف تسارع النقطة الأولى","مثلا تسارع النقطة الأولى","أربعة أمثال تسارع النقطة الأولى","مساويًا له لتساوي زمنيهما الدوريين"]'::jsonb, 'فهم', 'تحليل تناسب', 'متوسط', 'الكتاب ص 169، 178 — التسارع المركزي، محطات الفضاء الدوارة'),
('mcq', 5, 'جسم يتحرك على دائرة نصف قطرها 0.50 m، ويكمل دورة كاملة كل 0.80 s. ما مقدار تسارعه المركزي؟', null, null, '["31 m/s²","4.9 m/s²","25 m/s²","15 m/s²"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 169، 170 — التسارع المركزي، المثال 2'),
('mcq', 6, 'تدور الأرض حول محورها دورة كل 24 h، ونصف قطرها عند خط الاستواء $6.38\times10^{6}\ \text{m}$. ما مقدار التسارع المركزي لجسم على خط الاستواء؟', null, null, '["$4.37\\times10^{5}\\ \\text{m/s}^2$","$5.37\\times10^{-3}\\ \\text{m/s}^2$","$2.92\\times10^{3}\\ \\text{m/s}^2$","$3.37\\times10^{-2}\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب مع تحويل وحدات', 'صعب', 'الكتاب ص 169، 171 — التسارع المركزي، المراجعة 18'),
('mcq', 7, 'يبيّن المنحنى العلاقة بين التسارع المركزي لجسم ومقلوب مربع زمنه الدوري $\frac{1}{\text{T}^2}$ عند دورانه على دائرة نصف قطرها ثابت. ما نصف قطر الدائرة تقريبًا؟', null, '[{"src":"qimg/phys1/c6l2-o06-inv.svg","alt":"منحنى بياني: المحور الأفقي 1/T² بوحدة s⁻² من 0 إلى 1.2 بتدريج كل 0.2، والمحور الرأسي التسارع المركزي (m/s²) من 0 إلى 45 بتدريج كل 5. خط مستقيم بنفسجي يبدأ من نقطة الأصل، وعليه أربع نقاط: (0.25، 9.9 تقريبًا) و(0.50، 19.7 تقريبًا) و(0.75، 29.6 تقريبًا) و(1.00، 39.5 تقريبًا، أي أسفل خط 40 بقليل)."}]'::jsonb, '["39 m","1.0 m","6.3 m","0.025 m"]'::jsonb, 'تحليل', 'تحليل منحنى', 'صعب', 'الكتاب ص 169 — التسارع المركزي بدلالة الزمن الدوري'),
('essay', 1, 'اشتق علاقة التسارع المركزي بدلالة الزمن الدوري $a_{\text{C}} = \frac{4\pi^2 r}{\text{T}^2}$ مبتدئًا من $a_{\text{C}} = \frac{v^2}{r}$، موضحًا من أين جاءت العلاقة $v = \frac{2\pi r}{\text{T}}$.', null, null, null, 'فهم', 'اشتقاق', 'سهل', 'الكتاب ص 169 — التسارع المركزي بدلالة الزمن الدوري'),
('essay', 2, 'سدادة مطاطية مثبتة بخيط تدور في دائرة أفقية نصف قطرها 0.80 m، وتكمل دورة كاملة كل 1.25 s. احسب مقدار تسارعها المركزي بطريقتين: (a) باستعمال $a_{\text{C}} = \frac{4\pi^2 r}{\text{T}^2}$ مباشرة. (b) بحساب $v$ أولًا ثم $a_{\text{C}} = \frac{v^2}{r}$. ثم علّق على النتيجتين.', null, null, null, 'تطبيق', 'حساب بطريقتين', 'متوسط', 'الكتاب ص 169، 170 — المثال 2'),
('essay', 3, 'صُممت محطة فضائية دوّارة على شكل حلقتين متحدتي المركز كما في الشكل، نصف قطر الحلقة الخارجية 150 m والداخلية 75 m، وتدوران معًا بالزمن الدوري نفسه. (a) احسب الزمن الدوري اللازم ليكون التسارع المركزي عند الحلقة الخارجية 9.80 m/s². (b) احسب التسارع المركزي عند الحلقة الداخلية بالزمن الدوري نفسه، وفسّر الفرق.', null, '[{"src":"qimg/phys1/c6l2-o06-station.svg","alt":"حلقتان رماديتان متحدتا المركز تمثلان محطة فضائية. خط أخضر من المركز إلى الحلقة الداخلية مكتوب عنده 75 m، وخط أخضر آخر من المركز إلى الحلقة الخارجية مكتوب عنده 150 m. سهم رمادي منحنٍ خارج الحلقة الخارجية يبين اتجاه الدوران."}]'::jsonb, null, 'تحليل', 'مسألة تصميم', 'صعب', 'الكتاب ص 169، 178 — التسارع المركزي، محطات الفضاء الدوارة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L2-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الجسم يقطع محيط الدائرة $2\pi r$ خلال زمن دوري واحد، فـ $v = \frac{2\pi r}{\text{T}}$، وبتعويضها في $a_{\text{C}} = \frac{v^2}{r}$ نحصل على $a_{\text{C}} = \frac{4\pi^2 r}{\text{T}^2}$.', '["مقدار السرعة يساوي المسافة مقسومة على الزمن، لا حاصل ضرب نصف القطر في الزمن.","هذه الصيغة مقلوبة؛ فالسرعة تساوي المحيط مقسومًا على الزمن الدوري.","","ضرب التسارع في الزمن يعطي سرعة لا تسارعًا، ولا يحذف $v$ من العلاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-21T13:36:33.239Z"}'::jsonb),
('mcq', 2, 0, '$a_{\text{C}} = \frac{v^2}{r} = \frac{\left(\frac{2\pi r}{\text{T}}\right)^2}{r} = \frac{4\pi^2 r^2}{\text{T}^2 r} = \frac{4\pi^2 r}{\text{T}^2}$.', '["","عند تربيع $\\frac{2\\pi r}{\\text{T}}$ يجب تربيع $2\\pi$ أيضًا فيصبح $4\\pi^2$.","بعد تربيع السرعة يُقسم على $r$ فيبقى $r$ واحد في البسط لا $r^2$.","الزمن الدوري يظهر مربعًا لأنه في مقام السرعة التي تُربَّع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-21T13:36:33.240Z"}'::jsonb),
('mcq', 3, 3, '$a_{\text{C}} = \frac{4\pi^2 r}{\text{T}^2} \propto \frac{1}{\text{T}^2}$؛ فمضاعفة $\text{T}$ تجعل المقام أربعة أمثاله، فيصبح التسارع ربع قيمته.', '["هذا يهمل تربيع الزمن الدوري في المقام.","زيادة الزمن الدوري تعني حركة أبطأ، فيقل التسارع لا يزيد.","هذا يضع $\\text{T}^2$ في البسط، وهو في المقام.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.240Z"}'::jsonb),
('mcq', 4, 1, 'عند ثبات $\text{T}$: $a_{\text{C}} = \frac{4\pi^2 r}{\text{T}^2} \propto r$؛ فالنقطة الأبعد مرتين لها تسارع مركزي مثلا تسارع الأقرب.', '["هذا يطبق العلاقة $\\frac{v^2}{r}$ مع افتراض ثبات $v$، لكن النقطتين لهما الزمن الدوري نفسه لا السرعة نفسها.","","نصف القطر في البسط بالقوة الأولى في $\\frac{4\\pi^2 r}{\\text{T}^2}$ لا مربعًا.","تساوي الزمن الدوري لا يكفي؛ فالتسارع يتناسب طرديًا مع $r$ عند ثبات $\\text{T}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-21T13:36:33.240Z"}'::jsonb),
('mcq', 5, 0, '$a_{\text{C}} = \frac{4\pi^2 r}{\text{T}^2} = \frac{4\pi^2 (0.50\ \text{m})}{(0.80\ \text{s})^2} = 31\ \text{m/s}^2$.', '["","هذا ناتج $\\frac{2\\pi r}{\\text{T}^2}$؛ أي لم يُربَّع $2\\pi$.","هذا ناتج القسمة على $\\text{T}$ بدل $\\text{T}^2$.","عُوِّض $r = 0.25\\ \\text{m}$ كأن 0.50 m قطر الدائرة، والمعطى نصف القطر نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.243Z"}'::jsonb),
('mcq', 6, 3, '$\text{T} = 24\ \text{h} = 24 \times 3600 = 8.64\times10^{4}\ \text{s}$؛ $a_{\text{C}} = \frac{4\pi^2 (6.38\times10^{6})}{(8.64\times10^{4})^2} = 3.37\times10^{-2}\ \text{m/s}^2$.', '["هذا ناتج تعويض الزمن بالساعات (24) دون تحويله إلى ثوانٍ.","هذا ناتج $\\frac{2\\pi r}{\\text{T}^2}$؛ أي نسيان تربيع $2\\pi$.","هذا ناتج القسمة على $\\text{T}$ لا على $\\text{T}^2$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.243Z"}'::jsonb),
('mcq', 7, 1, 'من $a_{\text{C}} = 4\pi^2 r \left(\frac{1}{\text{T}^2}\right)$ يكون الميل $4\pi^2 r$. من المنحنى: عند $\frac{1}{\text{T}^2} = 1.0\ \text{s}^{-2}$ يكون $a_{\text{C}} \approx 39.5\ \text{m/s}^2$، فالميل $\approx 39.5\ \text{m}$، و$r = \frac{39.5}{4\pi^2} \approx 1.0\ \text{m}$.', '["هذا ميل المنحنى نفسه ($4\\pi^2 r$)، ولم يُقسم على $4\\pi^2$.","","هذا ناتج قسمة الميل على $2\\pi$ بدل $4\\pi^2$.","هذا مقلوب الميل؛ والصحيح أن الميل يساوي $4\\pi^2 r$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.244Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الزمن الدوري $\text{T}$ هو الزمن اللازم لإكمال دورة كاملة، وخلاله يقطع الجسم مسافة تساوي محيط الدائرة $2\pi r$؛ لذا مقدار السرعة $v = \frac{2\pi r}{\text{T}}$. بالتعويض في $a_{\text{C}} = \frac{v^2}{r}$: $a_{\text{C}} = \frac{\left(\frac{2\pi r}{\text{T}}\right)^2}{r} = \frac{4\pi^2 r^2}{\text{T}^2 r} = \frac{4\pi^2 r}{\text{T}^2}$.', '["المسافة في زمن دوري واحد = $2\\pi r$","$v = \\frac{2\\pi r}{\\text{T}}$","التعويض وتربيع البسط كاملًا","الاختصار إلى $\\frac{4\\pi^2 r}{\\text{T}^2}$"]'::jsonb, '["$v = \\frac{2\\pi r}{\\text{T}}$","$a_{\\text{C}} = \\frac{(2\\pi r/\\text{T})^2}{r}$","$a_{\\text{C}} = \\frac{4\\pi^2 r}{\\text{T}^2}$"]'::jsonb, '[{"element":"أصل علاقة السرعة","marks":1},{"element":"التعويض","marks":1},{"element":"الاختصار والنتيجة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"اشتقاق كامل صحيح"},{"level":"درجتان","description":"اشتقاق صحيح دون تفسير أصل $v$"},{"level":"درجة واحدة","description":"كتابة النتيجة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تربيع $2\\pi$","نسيان اختصار $r$","كتابة $\\text{T}$ دون تربيع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-21T13:36:33.244Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $a_{\text{C}} = \frac{4\pi^2 (0.80\ \text{m})}{(1.25\ \text{s})^2} = 20\ \text{m/s}^2$. (b) $v = \frac{2\pi (0.80\ \text{m})}{1.25\ \text{s}} = 4.02\ \text{m/s}$ (يُحتفظ برقم إضافي في الناتج الوسيط)، ثم $a_{\text{C}} = \frac{(4.02\ \text{m/s})^2}{0.80\ \text{m}} = 20\ \text{m/s}^2$. النتيجتان متساويتان لأن العلاقة الثانية نتجت من الأولى بتعويض $v = \frac{2\pi r}{\text{T}}$.', '["الطريقة الأولى: 20 m/s²","حساب $v = 4.02\\ \\text{m/s}$","الطريقة الثانية: 20 m/s²","التعليق على تطابق النتيجتين"]'::jsonb, '["$a_{\\text{C}} = \\frac{4\\pi^2 \\times 0.80}{1.25^2} = 20.2 \\approx 20\\ \\text{m/s}^2$","$v = \\frac{2\\pi \\times 0.80}{1.25} = 4.02\\ \\text{m/s}$","$a_{\\text{C}} = \\frac{4.02^2}{0.80} = 20\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"الطريقة الأولى","marks":1},{"element":"حساب السرعة","marks":1},{"element":"الطريقة الثانية","marks":1},{"element":"التعليق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان صحيحان مع التعليق"},{"level":"2–3 درجات","description":"حساب صحيح بطريقة واحدة أو خطأ في الأرقام المعنوية"},{"level":"درجة واحدة","description":"كتابة العلاقات دون حساب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تربيع الزمن الدوري","تقريب $v$ مبكرًا تقريبًا يغير النتيجة","استعمال القطر بدل نصف القطر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-21T13:36:33.245Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) من $a_{\text{C}} = \frac{4\pi^2 r}{\text{T}^2}$: $\text{T} = 2\pi\sqrt{\frac{r}{a_{\text{C}}}} = 2\pi\sqrt{\frac{150\ \text{m}}{9.80\ \text{m/s}^2}} = 24.6\ \text{s}$. (b) $a_{\text{C}} = \frac{4\pi^2 (75\ \text{m})}{(24.6\ \text{s})^2} = 4.90\ \text{m/s}^2$، أي نصف تسارع الحلقة الخارجية؛ لأن التسارع المركزي يتناسب طرديًا مع نصف القطر عند ثبات الزمن الدوري، والحلقة الداخلية نصف قطرها نصف قطر الخارجية.', '["إعادة ترتيب العلاقة لإيجاد $\\text{T}$","$\\text{T} = 24.6\\ \\text{s}$","تسارع الحلقة الداخلية 4.90 m/s²","التفسير: $a_{\\text{C}} \\propto r$ عند ثبات $\\text{T}$"]'::jsonb, '["$\\text{T}^2 = \\frac{4\\pi^2 r}{a_{\\text{C}}}$","$\\text{T} = 2\\pi\\sqrt{150/9.80} = 24.6\\ \\text{s}$","$a_{\\text{C}} = \\frac{4\\pi^2 \\times 75}{24.6^2} = 4.90\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"إيجاد T","marks":2},{"element":"التسارع الداخلي","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان وتفسير صحيح"},{"level":"2–3 درجات","description":"حساب واحد صحيح مع تفسير أو حسابان دون تفسير"},{"level":"درجة واحدة","description":"كتابة العلاقة الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان الجذر التربيعي عند إيجاد T","افتراض أن التسارع يقل إلى الربع في الحلقة الداخلية","استعمال $\\frac{v^2}{r}$ بافتراض ثبات السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-21T13:36:33.245Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C6-L2-O06') and x.type = v.type and x.number = v.number
