insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L2-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالقوة المركزية؟', null, null, '["قوة جديدة مستقلة تُضاف إلى القوى المؤثرة في الجسم عند دورانه","قوة تدفع الجسم الدوّار بعيدًا عن مركز الدائرة إلى الخارج","قوة تؤثر في اتجاه المماس فتحافظ على مقدار سرعة الجسم","محصلة القوى المؤثرة في الجسم في اتجاه مركز الدائرة"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 169، 170 — القوة المركزية'),
('mcq', 2, 'جسم يتحرك حركة دائرية منتظمة عكس اتجاه عقارب الساعة. أيّ المخططات الآتية يمثل اتجاه القوة المحصلة المؤثرة فيه عند الموقع المبيّن؟', null, '[{"src":"qimg/phys1/c6l2-o07-net.svg","alt":"أربعة مخططات مرقمة من 1 إلى 4، في كل منها دائرة مركزها نقطة، وجسم عند أقصى يمين الدائرة، وسهم رمادي منحنٍ أسفل الدائرة يبين الدوران عكس عقارب الساعة. يخرج من الجسم سهم أزرق: في المخطط 1 أفقي إلى اليسار نحو المركز، وفي المخطط 2 رأسي إلى أعلى مماس للدائرة، وفي المخطط 3 أفقي إلى اليمين بعيدًا عن المركز، وفي المخطط 4 مائل إلى أعلى اليسار بين اتجاه المركز واتجاه المماس."}]'::jsonb, '["المخطط 2","المخطط 1","المخطط 3","المخطط 4"]'::jsonb, 'فهم', 'تفسير مخطط', 'سهل', 'الكتاب ص 169، 170 — القوة المركزية'),
('mcq', 3, 'يُقال إن «القوة المركزية ليست نوعًا جديدًا من القوى». ماذا تعني هذه العبارة؟', null, null, '["أنها قوة وهمية لا وجود لها فلا تؤثر في الجسم الدوّار أصلًا","أنها تساوي دائمًا وزن الجسم الدوّار في المقدار","أنها تسمية لمحصلة قوى حقيقية كالشد أو الاحتكاك نحو المركز","أنها تنشأ عن الجاذبية الأرضية وحدها في جميع الحالات"]'::jsonb, 'فهم', 'تفسير عبارة', 'متوسط', 'الكتاب ص 170 — القوة المركزية'),
('mcq', 4, 'ما العلاقة بين اتجاه القوة المحصلة واتجاه السرعة المتجهة لجسم يتحرك حركة دائرية منتظمة؟', null, null, '["القوة المحصلة عمودية دائمًا على السرعة المتجهة","القوة المحصلة في اتجاه السرعة المتجهة دائمًا","القوة المحصلة عكس اتجاه السرعة المتجهة دائمًا","القوة المحصلة تصنع زاوية $45^\\circ$ مع السرعة المتجهة"]'::jsonb, 'فهم', 'تحديد علاقة', 'متوسط', 'الكتاب ص 169، 180 — القوة المركزية، التقويم 31'),
('mcq', 5, 'سدادة تدور مربوطة بخيط في دائرة أفقية على سطح أملس (أهمل قوى الاتجاه الرأسي). ما القوى الأفقية التي تُرسم في مخطط الجسم الحر للسدادة؟', null, null, '["قوة الشد نحو المركز وقوة مركزية إضافية نحو المركز","قوة الشد في الخيط فقط نحو المركز","قوة الشد نحو المركز وقوة طرد مركزي مساوية لها نحو الخارج","قوة في اتجاه السرعة المماسية تحافظ على حركة السدادة"]'::jsonb, 'تطبيق', 'رسم مخطط الجسم الحر', 'صعب', 'الكتاب ص 170 — القوة المركزية، المثال 2'),
('mcq', 6, 'جسم يتحرك حركة دائرية منتظمة. إذا استُبدل به جسم كتلته مثلا كتلته، يتحرك بمقدار السرعة نفسه وعلى الدائرة نفسها، فإن القوة المركزية اللازمة:', null, null, '["تبقى كما هي لأن التسارع المركزي لم يتغير","تصبح نصف قيمتها الأصلية","تصبح مثلَي قيمتها","تصبح أربعة أمثال قيمتها الأصلية"]'::jsonb, 'تطبيق', 'تحليل تناسب', 'متوسط', 'الكتاب ص 169 — القانون الثاني لنيوتن في الحركة الدائرية'),
('mcq', 7, 'جسم يدور في مسار دائري، وكانت القوة المحصلة المؤثرة فيه مائلة عن اتجاه المركز بحيث يكون لها مركّبة في اتجاه سرعته. ماذا يحدث لحركته؟', null, null, '["يتغير اتجاه سرعته ويزداد مقدارها، فلا تبقى منتظمة","تبقى حركته دائرية منتظمة لأن جزءًا من القوة نحو المركز","يتحرك فورًا في خط مستقيم مماس للمسار الدائري","يقل نصف قطر مساره فقط ويبقى مقدار سرعته ثابتًا"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 169، 170 — القوة المركزية، المحوران c وtang'),
('essay', 1, 'وضّح المقصود بالقوة المركزية، وحدد اتجاهها، واكتب العلاقة التي تربطها بكتلة الجسم وتسارعه المركزي.', null, null, null, 'فهم', 'شرح مفهوم', 'سهل', 'الكتاب ص 169، 170 — القوة المركزية'),
('essay', 2, 'كتب طالب أن القوى المؤثرة في سيارة تسلك منعطفًا أفقيًا هي: الوزن، والقوة العمودية، والاحتكاك، و«القوة المركزية»، ورسم أربعة أسهم في مخطط الجسم الحر. قوّم إجابة الطالب، وصحح مخطط الجسم الحر.', null, null, null, 'تقويم', 'تقويم إجابة', 'صعب', 'الكتاب ص 169، 170 — القوة المركزية'),
('essay', 3, 'ما العلاقة بين القوة المحصلة والسرعة المتجهة لجسم يتحرك حركة دائرية منتظمة؟ ناقش ذلك من حيث: (a) اتجاه القوة المحصلة بالنسبة إلى السرعة المتجهة. (b) مقدار القوة المحصلة بدلالة مقدار السرعة، وكيف يتغير إذا تضاعف مقدار السرعة على الدائرة نفسها. (c) لماذا لا يتغير مقدار السرعة مع وجود قوة محصلة تؤثر في الجسم.', null, null, null, 'تحليل', 'تحليل علاقة', 'متوسط', 'الكتاب ص 169، 180 — القوة المركزية، التقويم 31')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
