select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'لأن تسارع الجسم الدوّار نحو المركز، فلا بد أن تكون القوة المحصلة نحو المركز أيضًا، وتُسمّى هذه القوة القوة المركزية؛ وهي تسمية أخرى لمحصلة القوى الحقيقية المؤثرة في اتجاه المركز.', '["القوة المركزية ليست قوة إضافية؛ إنها تسمية لمحصلة القوى الحقيقية في اتجاه المركز.","هذا وصف «قوة الطرد المركزي» الوهمية؛ والقوة المركزية تتجه نحو المركز.","القوة المركزية نحو المركز لا في اتجاه المماس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.246Z"}'::jsonb),
('mcq', 2, 1, 'القوة المحصلة في الحركة الدائرية المنتظمة في اتجاه التسارع، أي نحو مركز الدائرة، كما في المخطط 1.', '["السهم في هذا المخطط مماسي في اتجاه الحركة؛ وهذا اتجاه السرعة لا القوة المحصلة.","","السهم يتجه بعيدًا عن المركز؛ ولا توجد قوة محصلة إلى الخارج في الحركة الدائرية المنتظمة.","لهذا السهم مركّبة مماسية تغير مقدار السرعة، فلا تبقى الحركة منتظمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-21T13:36:33.246Z"}'::jsonb),
('mcq', 3, 2, 'القوة المركزية تمثل مجموع القوى الحقيقية التي تؤثر في اتجاه المركز؛ فقد تكون قوة شد أو احتكاك أو تجاذب كتلي أو غيرها، ولا تُضاف قوة جديدة باسمها.', '["القوة المركزية حقيقية لأنها محصلة قوى حقيقية؛ أما الوهمية فهي قوة الطرد المركزي.","مقدارها $\\frac{mv^2}{r}$ وقد يكون أكبر من الوزن أو أصغر منه.","","مصدرها يختلف: شد أو احتكاك أو قوة عمودية أو تجاذب كتلي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-21T13:36:33.247Z"}'::jsonb),
('mcq', 4, 0, 'القوة المحصلة نحو المركز، والسرعة مماسية للمسار؛ والمماس عمودي على نصف القطر، فالقوة المحصلة عمودية على السرعة في كل لحظة.', '["","لو كانت في اتجاه السرعة لزاد مقدار السرعة ولم يتغير اتجاهها.","لو كانت عكس السرعة لتباطأ الجسم في خط مستقيم.","وجود مركّبة على امتداد السرعة يغير مقدارها، فلا تبقى الحركة منتظمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-21T13:36:33.247Z"}'::jsonb),
('mcq', 5, 1, 'القوة الأفقية الوحيدة المؤثرة في السدادة هي قوة الشد في الخيط نحو المركز، وهي نفسها القوة المركزية؛ فلا تُضاف قوة أخرى باسم القوة المركزية، ولا توجد قوة طرد.', '["القوة المركزية هنا هي قوة الشد نفسها، ورسمها مرة أخرى يضاعف القوة خطأً.","","قوة الطرد المركزي وهمية، ولو وُجدت لكانت المحصلة صفرًا فتحركت السدادة في خط مستقيم.","لا يلزم وجود قوة في اتجاه الحركة لاستمرارها؛ فالجسم يستمر بقصوره الذاتي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-21T13:36:33.247Z"}'::jsonb),
('mcq', 6, 2, '$F_{\text{المحصلة}} = ma_{\text{C}} = \frac{mv^2}{r}$؛ وعند ثبات $v$ و$r$ تتناسب القوة طرديًا مع $m$، فتتضاعف.', '["التسارع لم يتغير، لكن القوة تساوي $ma_{\\text{C}}$ فتتضاعف بمضاعفة الكتلة.","القوة المركزية تتناسب طرديًا مع الكتلة لا عكسيًا.","","الكتلة غير مربعة في العلاقة $F = \\frac{mv^2}{r}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-21T13:36:33.248Z"}'::jsonb),
('mcq', 7, 0, 'مركّبة القوة نحو المركز تغير اتجاه السرعة، ومركّبتها على المحور المماسي (في اتجاه السرعة) تزيد مقدارها؛ لذا لا تكون الحركة دائرية منتظمة، فالمنتظمة تتطلب أن تكون محصلة القوى نحو المركز تمامًا.', '["","المركّبة في اتجاه السرعة تزيد مقدارها، فيختل شرط ثبات مقدار السرعة.","الحركة المستقيمة تحدث عند زوال القوة المحصلة نحو المركز، وهي موجودة هنا.","المركّبة المماسية تغير مقدار السرعة، فلا يبقى ثابتًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-21T13:36:33.248Z"}'::jsonb),
('essay', 1, null::int, null, null, 'القوة المركزية هي محصلة القوى المؤثرة في الجسم المتحرك حركة دائرية منتظمة في اتجاه مركز الدائرة؛ وهي ليست قوة جديدة بل تسمية لمجموع القوى الحقيقية (شد، احتكاك، تجاذب...) نحو المركز. اتجاهها نحو مركز الدائرة دائمًا، في اتجاه التسارع المركزي. العلاقة (القانون الثاني لنيوتن في الحركة الدائرية): $F_{\text{المحصلة}} = ma_{\text{C}} = \frac{mv^2}{r}$.', '["التعريف: محصلة القوى نحو المركز","ليست قوة جديدة","الاتجاه نحو المركز","$F_{\\text{المحصلة}} = ma_{\\text{C}}$"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الاتجاه","marks":1},{"element":"العلاقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف واتجاه وعلاقة صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّها قوة إضافية تُرسم بجانب القوى الحقيقية","جعل اتجاهها إلى الخارج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.248Z"}'::jsonb),
('essay', 2, null::int, null, null, 'إجابة الطالب خاطئة جزئيًا: القوى الثلاث الأولى حقيقية ولها مصادر (الأرض تؤثر بالوزن، والطريق يؤثر بالقوة العمودية وبالاحتكاك)، أما «القوة المركزية» فليست قوة رابعة، بل هي اسم لمحصلة القوى نحو المركز؛ وفي هذه الحالة هي قوة الاحتكاك السكوني نفسها، لأن الوزن والقوة العمودية رأسيان ومتوازنان. التصحيح: يُرسم ثلاثة أسهم فقط من الجسم: $\boldsymbol{F}_g$ إلى أسفل، و$\boldsymbol{F}_{\text{N}}$ إلى أعلى مساوٍ له، و$\boldsymbol{f}_{f}$ أفقي نحو مركز المنعطف. ورسم سهم رابع يجعل المحصلة ضعف المطلوب.', '["الحكم بخطأ إضافة القوة المركزية","القوة المركزية محصلة لا قوة جديدة","مصدرها هنا الاحتكاك","المخطط الصحيح بثلاث قوى"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل","marks":1},{"element":"تحديد المصدر","marks":1},{"element":"المخطط المصحح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم كامل مع مخطط صحيح"},{"level":"2–3 درجات","description":"حكم وتعليل صحيحان مع نقص في المخطط"},{"level":"درجة واحدة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"تأييد إجابة الطالب أو لا إجابة"}]'::jsonb, '["حذف الاحتكاك والإبقاء على «القوة المركزية»","إضافة قوة طرد مركزي للتوازن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-21T13:36:33.249Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) القوة المحصلة (القوة المركزية) تتجه دائمًا نحو مركز الدائرة، والسرعة المتجهة مماسية للمسار؛ فهما متعامدتان في كل لحظة. (b) من القانون الثاني لنيوتن في الحركة الدائرية: $F_{\text{المحصلة}} = ma_{\text{C}} = \frac{mv^2}{r}$؛ فعند ثبات $m$ و$r$ يتناسب مقدار القوة المحصلة طرديًا مع مربع مقدار السرعة، فإذا تضاعف مقدار السرعة لزم أن تصبح القوة المحصلة أربعة أمثال قيمتها. (c) لأن القوة المحصلة عمودية على السرعة، فليس لها مركّبة في اتجاه الحركة (على المحور المماسي)؛ لذا لا تغير مقدار السرعة، وإنما تغير اتجاهها فقط.', '["القوة المحصلة نحو المركز والسرعة مماسية فهما متعامدتان","$F_{\\text{المحصلة}} = \\frac{mv^2}{r}$","مضاعفة السرعة تجعل القوة المطلوبة أربعة أمثالها","لا مركّبة للقوة في اتجاه السرعة فلا يتغير مقدارها"]'::jsonb, '["$F_{\\text{المحصلة}} = \\frac{mv^2}{r}$","$\\frac{m(2v)^2}{r} = 4\\frac{mv^2}{r}$"]'::jsonb, '[{"element":"الاتجاه والتعامد","marks":1},{"element":"العلاقة وأثر مضاعفة السرعة","marks":1},{"element":"تعليل ثبات مقدار السرعة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل القوة المحصلة في اتجاه السرعة","القول إن مضاعفة السرعة تضاعف القوة مرتين فقط","القول إن القوة المحصلة تزيد مقدار السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-21T13:36:33.249Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C6-L2-O07') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C6-L2-O08'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'جسم يدور مربوطًا بخيط في دائرة أفقية عكس اتجاه عقارب الساعة (منظورًا من أعلى). إذا انقطع الخيط عندما كان الجسم عند الموقع المبيّن، فأيّ المسارات المرقمة يسلكه الجسم (أهمل أثر الجاذبية في المسقط الأفقي)؟', null, '[{"src":"qimg/phys1/c6l2-o08-paths.svg","alt":"دائرة مركزها نقطة، وسهم رمادي منحنٍ أسفل يسارها يبين الدوران عكس عقارب الساعة. جسم عند أقصى يمين الدائرة يصله بالمركز خط متقطع. يخرج من الجسم أربعة مسارات متقطعة مرقمة: المسار 1 أفقي إلى اليمين على امتداد نصف القطر، والمسار 2 منحنٍ يصعد ثم ينعطف إلى اليسار، والمسار 3 مستقيم رأسي إلى أعلى مماس للدائرة، والمسار 4 مستقيم مائل إلى أعلى اليمين بزاوية 45 درجة."}]'::jsonb, '["المسار 3","المسار 1","المسار 2","المسار 4"]'::jsonb, 'فهم', 'تحديد مسار من شكل', 'سهل', 'الكتاب ص 169، 170 — انطلاق المطرقة، الشكل 6-7'),
('mcq', 2, 'في رياضة رمي المطرقة يدور الرامي بالمطرقة ثم يفلتها. في أيّ اتجاه تنطلق المطرقة لحظة إفلاتها (منظورًا من أعلى)؟', null, null, '["في اتجاه نصف القطر مبتعدة عن الرامي مباشرة","نحو الرامي في اتجاه مركز الدوران","في اتجاه سرعتها المماسية عند نقطة الإفلات","في مسار دائري أوسع حول الرامي بعد الإفلات"]'::jsonb, 'فهم', 'تحديد اتجاه', 'سهل', 'الكتاب ص 169، 170 — انطلاق المطرقة، الشكل 6-7'),
('mcq', 3, 'لماذا يتحرك جسم كان يدور بخيط في خط مستقيم بعد انقطاع الخيط مباشرة (منظورًا من أعلى)؟', null, null, '["لأن قوة الطرد المركزي تدفعه إلى الخارج بعد انقطاع الخيط مباشرة","لعدم وجود قوة أفقية تغير اتجاه سرعته، فيستمر بقصوره الذاتي","لأن القوة المركزية تبقى مؤثرة فيه فترة قصيرة بعد الانقطاع","لأن سرعته تصبح صفرًا لحظة الانقطاع ثم يبدأ الحركة من جديد"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 170، 171 — انطلاق المطرقة، القوة الوهمية'),
('mcq', 4, 'كرة تدور بخيط في دائرة أفقية عكس اتجاه عقارب الساعة (منظورًا من أعلى). انقطع الخيط عندما كانت الكرة عند الموقع $P$ في أقصى جنوب الدائرة. في أيّ اتجاه تتحرك الكرة بعد الانقطاع مباشرة؟', null, '[{"src":"qimg/phys1/c6l2-o08-compass.svg","alt":"دائرة مركزها نقطة، وسهم رمادي منحنٍ عند يسارها العلوي يبين الدوران عكس عقارب الساعة. كرة عند أسفل نقطة في الدائرة مكتوب عندها P. وفي أعلى يمين الشكل بوصلة: شمال إلى أعلى، وجنوب إلى أسفل، وشرق إلى اليمين، وغرب إلى اليسار."}]'::jsonb, '["نحو الجنوب","نحو الغرب","نحو الشمال","نحو الشرق"]'::jsonb, 'تطبيق', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 169، 170 — انطلاق المطرقة، الشكل 6-7'),
('mcq', 5, 'طفل يدير كرة بخيط في دائرة أفقية عكس اتجاه عقارب الساعة، ويريد أن تصيب الكرة الهدف المبيّن شمال الدائرة عند إفلات الخيط. عند أيّ موقع يجب أن يفلت الخيط (منظورًا من أعلى، وأهمل أثر الجاذبية)؟', null, '[{"src":"qimg/phys1/c6l2-o08-target.svg","alt":"دائرة مركزها نقطة، وسهم رمادي منحنٍ عند يسارها العلوي يبين الدوران عكس عقارب الساعة. أربعة مواقع على الدائرة: A عند أقصى اليمين (الشرق)، وB عند القمة (الشمال)، وC عند أقصى اليسار (الغرب)، وD عند الأسفل (الجنوب). في أعلى الشكل هدف دائري أحمر يقع رأسيًا فوق الموقع A تمامًا على مسافة كبيرة من الدائرة، ومكتوب بجانبه «الهدف». وفي أعلى يسار الشكل بوصلة: شمال إلى أعلى، وشرق إلى اليمين."}]'::jsonb, '["عند الموقع B","عند الموقع C","عند الموقع D","عند الموقع A"]'::jsonb, 'تحليل', 'تخطيط', 'صعب', 'الكتاب ص 169، 170 — انطلاق المطرقة، الشكل 6-7'),
('mcq', 6, 'سيارة تسلك منعطفًا دائريًا أفقيًا، ثم دخلت بقعة جليد أملس تمامًا ينعدم فيها الاحتكاك. كيف تتحرك السيارة (منظورًا من أعلى)؟', null, null, '["تكمل المنعطف الدائري نفسه لكن بسرعة أقل من قبل","تنزلق في خط مستقيم مماس للمنعطف عند بداية البقعة","تنزلق إلى الخارج في اتجاه نصف قطر المنعطف مباشرة","تنزلق نحو داخل المنعطف في اتجاه مركزه بسبب انعدام الاحتكاك"]'::jsonb, 'تطبيق', 'تطبيق في موقف', 'متوسط', 'الكتاب ص 170، 171 — انطلاق المطرقة، المسألة 11'),
('mcq', 7, 'ما الوصف الأدق لحركة المطرقة بعد إفلاتها، مع إهمال مقاومة الهواء؟', null, null, '["تتحرك في خط مستقيم أفقي إلى أن تصطدم بعائق أمامها دون أن تهبط","تسقط رأسيًا إلى أسفل عند نقطة الإفلات مباشرة","تنطلق في اتجاه المماس ثم تسلك مسار مقذوف أُطلق أفقيًا","تتحرك في خط نصف قطري مبتعدة عن الرامي ثم تسقط"]'::jsonb, 'تحليل', 'وصف حركة', 'صعب', 'الكتاب ص 169 — الشكل 6-7'),
('essay', 1, 'حدد اتجاه حركة حجر يدور بخيط في دائرة أفقية لحظة انقطاع الخيط، وفسّر ذلك مستعملًا القانون الأول لنيوتن، وبيّن لماذا لا يتحرك الحجر في اتجاه نصف القطر إلى الخارج.', null, null, null, 'فهم', 'تحديد وتفسير', 'سهل', 'الكتاب ص 170، 171 — انطلاق المطرقة، القوة الوهمية'),
('essay', 2, 'يبيّن الشكل حجرًا يدور بخيط في دائرة أفقية مع اتجاه عقارب الساعة (منظورًا من أعلى). انقطع الخيط عندما كان الحجر عند الموقع $P$. (a) ارسم مسار الحجر بعد الانقطاع مباشرة في المسقط الأفقي. (b) ما الزاوية بين هذا المسار والخيط لحظة الانقطاع؟ (c) لماذا لا يستمر الحجر في الدوران؟', null, '[{"src":"qimg/phys1/c6l2-o08-e-release.svg","alt":"دائرة مركزها نقطة، وسهم رمادي منحنٍ خارجها من الأعلى إلى اليمين يبين الدوران مع عقارب الساعة. خط مستقيم (الخيط) من المركز إلى حجر عند الموقع P في أعلى يسار الدائرة بزاوية 135 درجة من الاتجاه الأفقي الأيمن."}]'::jsonb, null, 'تطبيق', 'رسم مسار', 'متوسط', 'الكتاب ص 169، 170 — انطلاق المطرقة، الشكل 6-7'),
('essay', 3, 'في أثناء دوران حوض الغسالة لتجفيف الملابس، تلتصق الملابس بجدار الحوض بينما يخرج الماء من ثقوب الجدار. فسّر ما يحدث لكل من الملابس والماء بدلالة القوة المركزية واتجاه الحركة عند زوالها.', null, null, null, 'تحليل', 'تفسير ظاهرة', 'صعب', 'الكتاب ص 170، 171 — انطلاق المطرقة، المراجعة 13')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C6-L2-O08') and x.type = v.type and x.number = v.number);
