select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'عند انقطاع الخيط تزول القوة المركزية، فيتحرك الجسم بقصوره الذاتي في خط مستقيم في اتجاه سرعته المماسية لحظة الانقطاع؛ وعند أقصى يمين الدائرة ودورانٍ عكس عقارب الساعة تكون السرعة إلى أعلى (المسار 3).', '["","هذا مسار نصف قطري إلى الخارج كأن قوة طرد تدفع الجسم، ولا توجد مثل هذه القوة.","المسار المنحني يتطلب قوة محصلة تغير اتجاه السرعة، وقد زالت بانقطاع الخيط.","هذا الاتجاه يجمع بين المماس ونصف القطر، والجسم يحتفظ باتجاه سرعته لحظة الانقطاع فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-21T13:36:33.250Z"}'::jsonb),
('mcq', 2, 2, 'عند اختفاء قوة الشد في السلسلة لا توجد قوة تُكسب المطرقة تسارعًا نحو المركز، لذا تنطلق في اتجاه سرعتها المماسية للدائرة عند نقطة إفلاتها.', '["لا توجد قوة تدفع المطرقة إلى الخارج؛ فهي تحتفظ باتجاه سرعتها المماسية.","زوال قوة الشد يعني زوال القوة نحو المركز، فلا تتجه المطرقة نحوه.","","الحركة الدائرية تتطلب قوة مركزية، وقد زالت بزوال الشد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-21T13:36:33.250Z"}'::jsonb),
('mcq', 3, 1, 'بحسب القانون الأول لنيوتن يستمر الجسم في حركته بالسرعة المتجهة نفسها ما لم تؤثر فيه قوة محصلة؛ وبعد زوال الشد لا توجد قوة أفقية، فيتحرك في خط مستقيم في اتجاه سرعته لحظة الانقطاع.', '["قوة الطرد المركزي وهمية؛ ولو دفعت الجسم لتحرك نصف قطريًا لا مماسيًا.","","القوة المركزية هنا هي الشد، وتزول لحظة انقطاع الخيط.","سرعة الجسم لا تتغير فجأة لحظة الانقطاع؛ فهو يحتفظ بها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-21T13:36:33.251Z"}'::jsonb),
('mcq', 4, 3, 'عند أدنى نقطة (أقصى الجنوب) في دوران عكس عقارب الساعة تكون السرعة المماسية نحو الشرق، والكرة تتابع حركتها في هذا الاتجاه بعد زوال القوة المركزية.', '["هذا الاتجاه نصف قطري بعيدًا عن المركز، والكرة تتحرك في اتجاه سرعتها المماسية.","هذا عكس اتجاه الدوران؛ فعند أقصى الجنوب ودوران عكس عقارب الساعة تكون السرعة نحو الشرق.","هذا اتجاه المركز، ولا توجد قوة تدفع الكرة نحوه بعد انقطاع الخيط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-21T13:36:33.251Z"}'::jsonb),
('mcq', 5, 3, 'الكرة تنطلق في خط مستقيم مماس للدائرة عند نقطة الإفلات. عند A (أقصى الشرق) مع الدوران عكس عقارب الساعة تكون السرعة نحو الشمال، وخط المماس عندها يمر بالهدف الواقع شمالها مباشرة.', '["عند B تكون السرعة نحو الغرب، فتنطلق الكرة غربًا لا نحو الهدف.","عند C تكون السرعة نحو الجنوب، أي مبتعدة عن الهدف.","عند D تكون السرعة نحو الشرق، فتنطلق الكرة شرقًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-21T13:36:33.252Z"}'::jsonb),
('mcq', 6, 1, 'الاحتكاك السكوني بين العجلات والطريق هو القوة المركزية في المنعطف الأفقي؛ وبانعدامه لا تبقى قوة أفقية، فتستمر السيارة بقصوره الذاتي في خط مستقيم في اتجاه سرعتها المماسية لحظة دخول الجليد.', '["إكمال المنعطف يتطلب قوة مركزية، والاحتكاك الذي كان يوفرها انعدم.","","لا توجد قوة تدفع السيارة نصف قطريًا إلى الخارج؛ فهي تحتفظ باتجاه سرعتها.","انعدام الاحتكاك يعني انعدام القوة نحو المركز، فلا تتجه السيارة إليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-21T13:36:33.252Z"}'::jsonb),
('mcq', 7, 2, 'بعد الإفلات تنطلق المطرقة في خط مستقيم يكون مماسيًا للمسار الدائري عند نقطة الإفلات (في المسقط الأفقي)، ثم تُكمل مسارًا يشبه مسار أي جسم يُقذف بسرعة ابتدائية أفقية في الهواء بسبب الجاذبية.', '["الجاذبية الأرضية تؤثر فيها بعد الإفلات، فيتقوس مسارها إلى أسفل.","المطرقة تحتفظ بسرعتها الأفقية المماسية، فلا تسقط رأسيًا.","","اتجاه انطلاقها مماسي لا نصف قطري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-21T13:36:33.252Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يتحرك الحجر (منظورًا من أعلى) في خط مستقيم في اتجاه المماس للدائرة عند نقطة الانقطاع، أي في اتجاه سرعته لحظة الانقطاع. التفسير: قبل الانقطاع كانت قوة الشد هي القوة المركزية التي تغير اتجاه السرعة باستمرار؛ وعند الانقطاع تزول هذه القوة، وبحسب القانون الأول لنيوتن يستمر الجسم في حركته بالسرعة المتجهة نفسها ما لم تؤثر فيه قوة محصلة. ولا يتحرك نصف قطريًا إلى الخارج لأنه لا توجد قوة تدفعه إلى الخارج؛ فقوة الطرد المركزي وهمية.', '["الاتجاه: مماسي عند نقطة الانقطاع","زوال القوة المركزية (الشد)","القانون الأول: استمرار السرعة المتجهة","نفي الحركة نصف القطرية لعدم وجود قوة إلى الخارج"]'::jsonb, '[]'::jsonb, '[{"element":"الاتجاه","marks":1},{"element":"زوال القوة","marks":1},{"element":"القانون الأول","marks":1},{"element":"نفي الاتجاه نصف القطري","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد وتفسير كامل"},{"level":"2–3 درجات","description":"تحديد صحيح وتفسير ناقص"},{"level":"درجة واحدة","description":"تحديد الاتجاه فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الحجر يطير نصف قطريًا","تفسير الحركة بقوة طرد مركزي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-21T13:36:33.253Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) خط مستقيم يبدأ من $P$ مماس للدائرة في اتجاه الدوران؛ و$P$ في أعلى يسار الدائرة والدوران مع عقارب الساعة، فيتجه المسار إلى أعلى اليمين. (b) الزاوية $90^\circ$؛ لأن المماس عمودي على نصف القطر (الخيط). (c) لأن الدوران يتطلب قوة محصلة نحو المركز تغير اتجاه السرعة، وهذه القوة (قوة الشد) زالت بانقطاع الخيط، فيستمر الحجر بقصوره الذاتي في خط مستقيم.', '["المسار مستقيم مماسي في اتجاه الدوران","الاتجاه إلى أعلى اليمين","الزاوية $90^\\circ$","زوال القوة المركزية"]'::jsonb, '["حدد اتجاه الدوران عند $P$","ارسم المماس عند $P$ في اتجاه الحركة","المماس عمودي على نصف القطر"]'::jsonb, '[{"element":"الرسم","marks":1},{"element":"الاتجاه","marks":1},{"element":"الزاوية","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"رسم واتجاه وزاوية وتعليل صحيحة"},{"level":"2–3 درجات","description":"رسم صحيح مع خطأ في الاتجاه أو الزاوية"},{"level":"درجة واحدة","description":"تعليل صحيح دون رسم"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم المماس في عكس اتجاه الدوران","رسم المسار على امتداد الخيط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-21T13:36:33.253Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الملابس تتحرك في دائرة لأن جدار الحوض يؤثر فيها بقوة نحو المركز (القوة العمودية من الجدار) تعمل قوةً مركزية. أما قطرات الماء فعندما تصل إلى ثقب في الجدار لا يجد الجدار ما يدفعها به نحو المركز (ولا تكفي قوة تماسك الماء بالقماش)، فتزول القوة المركزية المؤثرة فيها، فتتحرك بقصورها الذاتي في خط مستقيم في اتجاه سرعتها المماسية لحظة وصولها إلى الثقب، فتخرج من الحوض. لا توجد قوة تدفع الماء إلى الخارج؛ فالماء يكمل حركته المستقيمة بينما يستمر الحوض والملابس في الانعطاف.', '["الجدار يوفر القوة المركزية للملابس","عند الثقب تزول القوة المركزية عن الماء","الماء يتحرك مماسيًا بقصوره الذاتي","نفي وجود قوة طرد"]'::jsonb, '[]'::jsonb, '[{"element":"الملابس","marks":1},{"element":"زوال القوة عن الماء","marks":1},{"element":"اتجاه حركة الماء","marks":1},{"element":"نفي قوة الطرد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للملابس والماء"},{"level":"2–3 درجات","description":"تفسير صحيح لأحدهما مع نقص في الآخر"},{"level":"درجة واحدة","description":"وصف دون تفسير بالقوى"},{"level":"صفر","description":"تفسير بقوة طرد مركزي أو لا إجابة"}]'::jsonb, '["القول إن قوة الطرد تدفع الماء للخارج","القول إن الماء يخرج نصف قطريًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (2%)"}],"at":"2026-11-21T13:36:33.253Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
